(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("ammianus-3-b", [{"sp": "HDR", "t": "Res Gestae (Libri XXVI–XXXI)"}, {"sp": "HDR", "t": "Liber XXVI", "st": "26"}, {"sp": "N", "t": "Dictis impensiore cura rerum ordinibus ad usque memoriae confinia propioris, convenerat iam referre a notioribus pedem, ut et pericula declinentur veritati saepe contigua, et examinatores contexendi operis deinde non perferamus intempestivos, strepentes ut laesos, si praeteritum sit, quod locutus est imperator in cena, vel omissum quam ob causam gregarii milites coerciti sunt apud signa, et quod non decuerat in descriptione multiplici regionum super exiguis silere castellis, quodque cunctorum nomina, qui ad urbani praetoris officium convenere, non sunt expressa, et similia plurima, praeceptis historiae dissonantia, discurrere per negotiorum celsitudines assuetae, non humilium minutias indagare causarum, quas si scitari voluerit quispiam, individua illa corpuscula volitantia per inane, ἀτόμους, ut nos appellamus, numerari posse sperabit.", "st": "26.1"}, {"sp": "N", "t": "Haec quidam veterum formidantes, cognitiones actuum variorum, stilis uberibus explicatas, non edidere superstites, ut in quadam ad Cornelium Nepotem epistula Tullius quoque testis reverendus affirmat. Proinde inscitia vulgari contempta ad residua narranda pergamus.", "st": "26.1"}, {"sp": "N", "t": "Hac volubilium casuum diritate, exitu luctuoso finita, obituque intervallato trium brevi tempore principum, corpore curato defuncti, missoque Constantinopolim, ut inter Augustorum reliquias conderetur, progresso Nicaeam versus exercitu, quae in Bithynia mater est urbium, potestatum civilium, militiaeque rectores, magnitudine curarum adstricti communium, interque eos quidam spe vana sufflati, moderatorem quaeritabant diu exploratum et gravem.", "st": "26.1"}, {"sp": "N", "t": "Et rumore tenus obscuris paucorum susurris, nomen praestringebatur Aequitii, scholae primae Scutariorum, etiam tum tribuni, qui cum potiorum auctoritate displicuisset ut asper et subagrestis, translata est suffragatio levis in Ianuarium Ioviani adfinem curantem summitatem necessitatum castrensium per Illyricum.", "st": "26.1"}, {"sp": "N", "t": "Quo itidem spreto, quia procul agebat, ut aptus ad id quod quaerebatur atque conveniens, Valentinianus, nulla discordante sententia, numinis adspiratione caelestis electus est, agens scholam Scutariorum secundam, relictusque apud Ancyram, postea secuturus, ut ordinatum est. Et quia nullo renitente hoc e re publica videbatur, missi sunt qui eum venire ocius admonerent, diebusque decem nullus imperii tenuit gubernacula, quod tunc evenisse, extis Romae inspectis, haruspex edixerat Marcus.", "st": "26.1"}, {"sp": "N", "t": "Inter haec tamen, nequid novaretur contrarium placitis, neve armatorum mobilitas, saepe versabilis, ad praesentium quendam inclinaret arbitrium, attente providebat Aequitius, et cum eo Leo, adhuc sub Dagalaifo magistro equitum rationes numerorum militarium tractans, exitialis postea magister officiorum, exercitus universi iudicium, quantum facere nitique poterant, ut Pannonii fautoresque principis designate firmantes.", "st": "26.1"}, {"sp": "N", "t": "Qui cum venisset accitus, implendique negotii praescius praesagiis, ut opinari dabatur, vel somniorum assiduitate, nec videri die secundo nec prodire in medium voluit, bissextum vitans Februarii mensis, tunc illucescens, quod aliquotiens rei Romanae fuisse norat infaustum. Cuius notitiam certam designabo.", "st": "26.1"}, {"sp": "N", "t": "Spatium anni vertentis id esse, periti mundani motus et siderum definiunt veteres, inter quos Meton et Euctemon et Hipparchus et Archimedes excellunt, cum sol perenni rerum sublimium lege, polo percurso signifero, quem ζῳδιακόν sermo Graecus appellat, trecentis et sexaginta quinque diebus emensis et noctibus, ad eundem redierit cardinem, ut (verbo tenus) si a secunda particula elatus Arietis, ad eam dimensione redierit terminata.", "st": "26.1"}, {"sp": "N", "t": "Sed anni intervallum verissimum, memoratis diebus et horis sex usque ad meridiem concluditur plenam, annique sequentis erit post horam sextam initium, porrectum ad vesperam. Tertius a prima vigilia sumens exordium, ad horam noctis extenditur sextam. Quartus a medio noctis ad usque claram trahitur lucem.", "st": "26.1"}, {"sp": "N", "t": "Ne igitur haec computatio variantibus annorum principiis, ut quodam post horam sextam diei, alio post sextam excurse nocturnam, scientiam omnem squalida diversitate confundat, et autumnalis mensis inveniatur quandoque vernalis, placuit senas illas horas quae quadriennio viginti colliguntur atque quattuor, in unius diei noctisque adiectae transire mensuram.", "st": "26.1"}, {"sp": "N", "t": "Hocque alte considerate, eruditis concinentibus multis, effectum est, ut ad unum distinctumque exitum, circumversio cursus annui revoluta, nec vaga sit nec incerta, nulloque errore deinceps obumbrata, ratio caelestis appareat et menses tempora retineant praestituta.", "st": "26.1"}, {"sp": "N", "t": "Haec nondum extentis fusius regnis, diu ignoravere Romani, perque saecula multa, obscuris difficultatibus implicati, tunc magis errorum profunda caligine fluctuabant, cum in sacerdotes potestatem transtulissent interkalandi, qui licenter gratificantes publicanorum vel litigantium commodis, ad arbitrium suum subtrahebant tempora vel augebant.", "st": "26.1"}, {"sp": "N", "t": "Hocque ex coepto emerserunt alia plurima, quae fallebant, quorum meminisse nunc supervacuum puto. Quibus abolitis, Octavianus Augustus Graecos secutus, hanc inconstantiam correcta turbatione composuit, spatiis duodecim mensium et sex horarum magna deliberatione collectis, per quae duodecim siderum domicilia sol discurrens motibus sempiternis anni totius intervalla concludit.", "st": "26.1"}, {"sp": "N", "t": "Quam rationem bissexti probatam, etiam victura cum saeculis Roma, adiumento numinis divini fundavit. Proinde pergamus ad reliqua.", "st": "26.1"}, {"sp": "N", "t": "Elapso die parum apto ad inchoandas rerum magnitudines (ut quidam existimant), propinquante iam vespera, monitu praefecti Sallustii, sub exitii denuntiatione statutum est prompta consensione cunctorum, ne potioris quisquam auctoritatis, vel suspectus altiora conari, procederet postridie mane.", "st": "26.2"}, {"sp": "N", "t": "Cumque multorum taedio quos votorum inanitas cruciabat, tandem finita nocte lux advenisset, in unum quaesito milite omni, progressus Valentinianus in campum, permissusque tribunal ascendere celsius structum, comitiorum specie, voluntate praesentium secundissima, ut vir serius rector pronuntiatur imperii.", "st": "26.2"}, {"sp": "N", "t": "Mox principali habitu circumdatus et corona, Augustusque nuncupatus, cum laudibus amplis, quas novitatis potuit excitare dulcedo, praemeditata dicere iam parabat. Eoque (ut expeditius loqueretur), brachium exsertante, obmurmuratio gravis exoritur, concrepantibus centuriis et manipulis cohortiumque omnium plebe urgentium destinate, confestim imperatorem alterum declarari.", "st": "26.2"}, {"sp": "N", "t": "Quod licet non nulli existimarunt, paucis corruptis, ad gratiam fieri despectorum, ex eo tamen id frustra creditum videbatur, quod non emercati, sed consoni totius multitudinis paria volentis clamores audiebantur, documento recenti fragilitatem pertimescentis sublimium fortunarum. Dein ex susurris immaniter strepentis exercitus, cieri tumultus violentior apparebat, et confidentia militis, erumpentis interdum ad perniciosa facinora, timebatur.", "st": "26.2"}, {"sp": "N", "t": "Quod Valentinianus magis prae cunctis ne fieret extimescens, elata propere dextera, vi principis fiducia pleni, ausus increpare quosdam, ut seditiosos et pertinaces, cogitata nullis interpellantibus absolvebat:-", "st": "26.2"}, {"sp": "N", "t": "“Exulto—provinciarum fortissimi defensores,—et prae me fero semperque laturus sum, nec speranti nec appetenti moderamina orbis Romani, mihi ut potissimo omnium, vestras detulisse virtutes.", "st": "26.2"}, {"sp": "N", "t": "“Quod erat igitur in manu positum vestra, nondum electo imperii formatore, utiliter et gloriose complestis, adscito in honorum verticem eo, quem ab ineunte adulescentia ad hanc usque aetatis maturitatem splendide integreque vixisse experiundo cognoscitis. Proinde pacatis auribus accipite (quaeso) simplicioribus verbis dicentem, quod conducere arbitror in commune.", "st": "26.2"}, {"sp": "N", "t": "“Adhiberi oportere in omnes casus socia potestate collegam, contemplatione poscente multiplici, nec ambigo nec repugno, curarum acervos et mutationes varias accidentium, ipse quoque ut homo formidans, sed studendum est concordiae viribus totis, per quam res quoque minimae convalescunt, quod impetrabitur facile, si patientia vestra, cum aequitate consentiens, id mihi quod mearum est partium, concesserit libens.", "st": "26.2"}, {"sp": "N", "t": "“Dabit enim, ut spero, Fortuna consiliorum adiutrix bonorum, quantum efficere et consequi possum, diligenter scrutanti moribus temperatum. Ut enim sapientes definiunt, non modo in imperio, ubi pericula maxima sunt et creberrima, verum etiam in privatis cottidianisque rationibus, alienum ad amicitiam, cum iudicaverit quisquam prudens, adiungere sibi debebit, non cum adiunxerit, iudicare.", "st": "26.2"}, {"sp": "N", "t": "“Haec cum spe laetiorum polliceor, vos firmitatem factorum retinentes et fidem, dum hiberna patitur quies, animorum reparate vigorem atque membrorum, ob nuncupationem augustam, debita protinus accepturi.”", "st": "26.2"}, {"sp": "N", "t": "Finita oratione, quam auctoritas erexerat inopina, flexit imperator in suam sententiam universos, consiliique eius viam secuti, qui paulo ante flagrantissimis vocibus aliud postulabant, circumsaeptum aquilis et vexillis, agminibusque diversorum ordinum ambitiose stipatum, iamque terribilem, duxerunt in regiam.", "st": "26.2"}, {"sp": "N", "t": "Dum haec in Oriente volubiles fatorum explicant sortes, Apronianus regens urbem aeternam, iudex integer et severus, inter curarum praecipua, quibus haec praefectura saepe sollicitatur, id primum opera curabat enixa, ut veneficos (qui tunc rarescebant) captos postque agitatas quaestiones nocuisse quibusdam apertissime confutatos, indicatis consciis morte multaret, atque ita paucorum discrimine reliquos (siqui laterent), formidine parium exturbaret.", "st": "26.3"}, {"sp": "N", "t": "Haec egisse ideo efficaciter fertur, quod Iuliani promotus arbitrio, agentis etiam tum per Syrias, in itinere unum amiserat oculum, suspicatusque artibus se nefariis appetitum, iusto quidem sed inusitato dolore, haec et alia magna quaeritabat industria. Unde quibusdam atrox visus est, in amphitheatrali curriculo undatim coeunte aliquotiens plebe, causas dispiciens criminum maximorum.", "st": "26.3"}, {"sp": "N", "t": "Denique post huius modi vindicata complura, Hilarinum aurigam convictum atque confessum, vixdum pubescentem filium suum venefico tradidisse, docendum secretiora quaedam legibus interdicta, ut nullo conscio adminiculis iuvaretur internis, capitali animadversione damnavit. Qui laxius retinente carnifice, subito lapsus, confugit ad ritus Christiani sacrarium, abstractusque exinde ilico, abscisa cervice consumptus est.", "st": "26.3"}, {"sp": "N", "t": "Verum haec similiaque tum etiam ut coercenda, mox cavebantur, et nulli vel admodum pauci, in his versati flagitiis, vigori publico insultarunt, sed tempore secuto longaeva impunitas nutrivit immania, usque eo grassante licentia, ut imitatus Hilarinum quidam senator, servumque suum modo non per syngrapham arcanis piacularibus inducendum, commisisse doctori malarum artium confutatus, supplicium redimeret, opima mercede, ut crebrior fama vulgarat.", "st": "26.3"}, {"sp": "N", "t": "Isque ipse, hoc genere quo iactatum est, absolutus, cum vitae pudere deberet et culpae, non abolendae incubuit maculae, sed tamquam inter multos probrosos, solus vacuus ab omni delicto, equo phalerato insidens, discurrensque per silices, multa post se nunc usque trahit agmina servulorum, per novum quoddam insigne, curiosius spectari affectans, ut Duillium accepimus veterem, post gloriosa illa navalis rei certamina, id sibi sumpsisse ut tibicine lenius praecinente rediret ad sua post cenam.", "st": "26.3"}, {"sp": "N", "t": "Sub hoc tamen Aproniano, ita iugiter copia necessariorum exuberavit, ut nulla saltim levia murmura super inopia victui congruentium, orerentur, quod assidue Romae contingit.", "st": "26.3"}, {"sp": "N", "t": "At in Bithynia Valentinianus princeps (ut praediximus) declaratus, dato in perendinum diem signo proficiscendi, convocatis primoribus, quasi tuta consilia, quam sibi placentia, secuturus, percunctabatur, quemnam ad imperii consortium oporteret assumi, silentibusque cunctis, Dagalaifus tunc equestris militiae rector, respondit fidentius: “Si tuos amas” inquit, “imperator optime, habes fratrem; si rem publicam, quaere quem vestias.”", "st": "26.4"}, {"sp": "N", "t": "Quo dicto asperatus ille sed tacitus, et occultans quae cogitabat, Nicomediam itineribus citis ingressus, Kalendis Martiis Valentem fratrem stabulo suo cum tribunatus dignitate praefecit.", "st": "26.4"}, {"sp": "N", "t": "Indeque cum venisset Constantinopolim, multa secum ipse diu volvens, et magnitudine urgentium negotiorum iam se superari considerans, nihil morandum ratus, quintum Kalendas Aprilis, productum eundem Valentem in suburbanum, universorum sententiis concinentibus—nec enim audebat quisquam refragari,—Augustum pronuntiavit, decoreque imperatorii cultus ornatum, et tempora diademate redimitum, in eodem vehiculo secum reduxit, participem quidem legitimum potestatis, sed in modum apparitoris morigerum, ut progrediens aperiet textus.", "st": "26.4"}, {"sp": "N", "t": "Quibus ita nullo interturbante perfectis, constricti rapidis febribus, imperatores ambo diu spe vivendi firmata, ut erant in inquirendis rebus graviores quam in componendis, suspectas morborum causas investigandas acerrime, Ursatio officiorum magistro, Delmatae crudo, et Viventio Sisciano, quaestori tunc commiserunt, ut loquebatur pertinax rumor, invidiam cientes Iuliani memoriae principis, amicisque eius, tamquam clandestinis praestigiis laesi. Sed hoc evanuit facile, ne verbo quidem tenus insidiarum indicio ullo reperto.", "st": "26.4"}, {"sp": "N", "t": "Hoc tempore velut per universum orbem Romanum, bellicum canentibus bucinis, excitae gentes saevissimae, limites sibi proximos persultabant. Gallias Raetiasque simul Alamanni populabantur; Sarmatae Pannonias et Quadi; Picti Saxonesque et Scotti, et Attacotti Britannos aerumnis vexavere continuis; Austoriani Mauricaeque aliae gentes, Africam solito acrius incursabant; Thracias et Pannonias diripiebant praedatorii globi Gothorum.", "st": "26.4"}, {"sp": "N", "t": "Persarum rex manus Armeniis iniectabat, eos in suam dicionem ex integro vocare vi nimia properans, sed iniuste causando, quod post Ioviani excessum, cum quo foedera firmarat et pacem, nihil obstare debebit, quo minus ea recuperaret, quae antea ad maiores suos pertinuisse monstrabat.", "st": "26.4"}, {"sp": "N", "t": "Acta igitur tranquillius hieme, concordissimi principes, unus nuncupatione praelatus, alter honori specie tenus adiunctus, percursis Thraciis Naessum advenerunt, ubi in suburbano, quod appellatum Mediana, a civitate tertio lapide disparatur, quasi mox separandi, partiti sunt comites.", "st": "26.5"}, {"sp": "N", "t": "Et Valentiniano quidem, cuius arbitrio res gerebatur, Iovinus evenit dudum promotus a Iuliano, per Gallias magister armorum, et Dagalaifus, quem militiae rectorem provexerat Iovianus: in Orientem vero secuturus Valentem, ordinatus est Victor, ipse quoque iudicio principis ante dicti provectus, cui iunctus est Arintheus. Lupicinus enim pridem a Ioviano pari modo promotus, magister equitum partes tuebatur eoas.", "st": "26.5"}, {"sp": "N", "t": "Tunc et Aequitius Illyriciano praeponitur exercitui, nondum magister, sed comes, et Serenianus, olim sacramento digressus, recinctus est, ut Pannonius, sociatusque Valenti, domesticorum praefuit scholae. Quibus ita digestis et militares partiti sunt numeri.", "st": "26.5"}, {"sp": "N", "t": "Et post haec cum ambo fratres Sirmium introissent, diviso palatio, ut potiori placuerat, Valentinianus Mediolanum, Constantinopolim Valens discessit.", "st": "26.5"}, {"sp": "N", "t": "Et Orientem quidem regebat potestate praefecti Sallustius, Italiam vero, cum Africa et Illyrico, Mamertinus, et Gallicas provincias Germanianus.", "st": "26.5"}, {"sp": "N", "t": "Agentes igitur in memoratis urbibus principes, sumpsere primitus trabeas consulares, omnisque hic annus dispendiis gravibus rem Romanam afflixit.", "st": "26.5"}, {"sp": "N", "t": "Alamanni enim perrupere Germaniae limites, hac ex causa solito infestius moti. Cum legatis eorum, missis ad comitatum, certa et praestituta ex more munera praeberi deberent, minora et vilia sunt attributa, quae illi suscepta, furenter agentes ut indignissima proiecere. Tractatique asperius ab Ursatio, tunc magistro officiorum, iracundo quodam et saevo, regressi factumque exaggerentes, ut contumeliose despectas gentes immanissimas concitarunt.", "st": "26.5"}, {"sp": "N", "t": "Et circa id tempus, aut non multo posterius, in Oriente Procopius in res surrexerat novas, quae prope Kalendas Novembris, venturo Valentiniano Parisios uno eodemque nuntiata sunt die.", "st": "26.5"}, {"sp": "N", "t": "Et Alamannis quidem occursurum Dagalaifum pergere mature praecepit, qui vastitatis propinquioribus locis, longius discesserant incruenti. Super appetitu vero Procopi, antequam adulesceret, reprimendo, curis diducebatur ambiguis, ea potissimum ratione sollicitus, quod ignorabat utrum Valente superstite, an exstincto, memoratus imperium affectarat.", "st": "26.5"}, {"sp": "N", "t": "Aequitius enim relatione Antoni tribuni accepta, agentis in Dacia mediterranea militem, qui nihil praeter negotium ipsum auditum obscure significabat, ipse quoque nondum liquida fide comperta, simplicibus verbis principem gestorum conscium fecit.", "st": "26.5"}, {"sp": "N", "t": "His cognitis Valentinianus eodem Aequitio aucto magisterii dignitate, repedare ad Illyricum destinabat, ne persultatis Thraciis perduellis iam formidatus, invaderet hostili excursu Pannonias. Documento enim recenti impendio terrebatur, reputans paulo antea Iulianum, contempto imperatore, bellorum civilium ubique victore, nec speratum ante nec exspectatum, ab urbe in urbem incredibili velocitate transisse.", "st": "26.5"}, {"sp": "N", "t": "Verum ardens ad redeundum, eius impetus molliebatur consiliis proximorum, suadentium et orantium, ne interneciva minantibus barbaris exponeret Gallias, neve hac causatione provincias desereret, egentes adminiculis magnis, eisque legationes urbium accessere nobilium, precantes ne in rebus duris et dubiis, inpropugnatas eas relinqueret, quas praesens eripere poterit discriminibus maximis, metu ambitiosi nominis sui Germanis incusso.", "st": "26.5"}, {"sp": "N", "t": "Tandem denique utilitate rei perpensius excogitata, in multorum sententias flexus, replicabat aliquotiens, hostem suum fratrisque solius esse Procopium, Alamannos vero totius orbis Romani; statuitque nusquam interim extra confinia moveri Gallorum.", "st": "26.5"}, {"sp": "N", "t": "Et ad usque Remos progressus, sollicitusque super Africa, ne repente perrumperetur, Neoterium, postea consulem, tunc notarium, ad eandem tuendam ire disposuit, et Masaucionem domesticum protectorem, ea consideratione, quod ibi sub patre Cretione quondam comite educatus, suspecta noverat loca, hisque scutarium adiunxit Gaudentium, olim sibi cognitum et fidelem.", "st": "26.5"}, {"sp": "N", "t": "Quia igitur uno eodemque tempore, utrubique turbines exarsere maestissimi, competenti loco singula digeremus, nunc partem in Oriente gestorum, deinde bella barbarica narraturi, quoniam pleraque et in occidentali et in eoo orbe eisdem mensibus sunt actitata, ne dum ex loco subinde saltuatim redire festinamus in locum, omnia confundentes, squaliditate maxima rerum ordines implicemus.", "st": "26.5"}, {"sp": "N", "t": "Insigni genere Procopius in Cilicia natus et educatus, ea consideratione qua propinquitate Iulianum, postea principem, contingebat, a primo gradu eluxit, et ut vita moribusque castigatior, licet occultus erat et taciturnus, notarius diu perspicaciter militans, et tribunus, iamque summatibus proximus, post Constanti obitum in rerum conversion, velut imperatoris cognatus, altius anhelabat, adiunctus consortio comitum: et apparebat eum, si umquam potuisset, fore quietis publicae turbatorem.", "st": "26.6"}, {"sp": "N", "t": "Hunc Iulianus Persidem ingrediens, consociato pari potestatis iure Sebastiano, in Mesopotamia cum manu militum reliquerat valida, mandaratque (ut susurravit obscurior fama, nemo enim dicti auctor exstitit verus), pro cognitorum ageret textu, et si subsidia rei Romanae languisse sensisset, imperatorem ipse se provideret ocius nuncupari.", "st": "26.6"}, {"sp": "N", "t": "Qui iniuncta civiliter agens et caute, Iuliani letaliter vulnerati funus et ad regenda communia comperit Iovianum evectum, falsoque rumore disperso, inter abeuntis anhelitus animae eundem Iulianum verbo mandasse, placere sibi Procopio clavos summae rei gerendae committi, veritus ne hac ex causa indemnatus occideretur, e medio se conspectu discrevit, maxime post Ioviani territus necem, notariorum omnium primi, quem Iuliano perempto veluti dignum imperio paucis militibus nominatum, novaque exinde coeptare suspectum, cruciabiliter didicerat interfectum.", "st": "26.6"}, {"sp": "N", "t": "Et quia se quaeri industria didicerat magna, vitans gravioris invidiae pondus, ad abdita longiusque remota, discessit. Cumque a Ioviano exploratius indagari latibula sua sentiret, et ferinae vitae iam fuisset pertaesum,—quippe a celsiore statu deiectus ad inferiora, etiam edendi penuria, in locis squalentibus, stringebatur, hominumque egebat colloquiis—postremae necessitatis impulsu, deviis itineribus ad Chalcedonos agrum pervenit.", "st": "26.6"}, {"sp": "N", "t": "Ubi quoniam ei illud firmius visum est receptaculum, apud fidissimum amicorum delitescebat, Strategium quendam, ex palatino milite senatorem, Constantinopolim quantum fieri poterat clanculo saepe intermeans, ut indicio eiusdem Strategi patuit, postquam saepius in factionis conscios est inquisitum.", "st": "26.6"}, {"sp": "N", "t": "Ritu itaque sollertissimi cuiusdam speculatoris, ignotus ob squalorem vultus et maciem, rumusculos colligebat tunc crebrescentes, ut sunt acerba semper instantia, incusantium multorum Valentem, quasi cupiditate aliena rapiendi succensum.", "st": "26.6"}, {"sp": "N", "t": "Cuius diritati adiectum erat incentivum exitiale, socer Petronius, ex praeposito Martensium militum, promotus repentino saltu patricius, animo deformis et habitu, qui ad nudandos sine discretione cunctos immaniter flagrans, nocentes pariter et insontes, post exquisita tormenta quadrupli nexibus vinciebat, debita iam inde a temporibus principis Aureliani perscrutans, et impendio maerens, si quemquam absolvisset indemnem.", "st": "26.6"}, {"sp": "N", "t": "Cuius morum intolerantiae, haec quoque pernicies accedebat, quod cum ditaretur luctibus alienis, erat inexorabilis et crudelis, et intrepido corde durissimus, nec reddendae nec accipiendae rationis umquam capax, invisior Cleandro, quem agentem sub imperatore Commodo praefecturam, sublata vecordia, diversas legimus vexasse fortunas, et onerosior Plautiano, qui praefectus itidem sub Severo, ultra mortalem tumens cuncta confuderat, ni gladio perisset ultore.", "st": "26.6"}, {"sp": "N", "t": "Haec lacrimosa, quae incitante Petronio, sub Valente clausere multas paupertinas et nobiles domos, impendentiumque spes atrocior provincialium, et militum paria gementium, sensibus imis haerebant, et votis, licet obscuris et tacitis permutatio status praesentis ope numinis summi concordi gemitu poscebatur.", "st": "26.6"}, {"sp": "N", "t": "Quae Procopius latenter accipiens, arbitratusque ubi felicius acciderit fatum, negotio levi ad apicem summae potestatis assumi, subsidebat ut praedatrix bestia viso, quod capi potuerit, protinus eruptura.", "st": "26.6"}, {"sp": "N", "t": "Cui in haec quae maturabat ardenti, fors hanc materiam dedit impendio tempestivam. Consumpta hieme festinans ad Syriam Valens, iamque fines Bithynorum ingressus docetur relationibus ducum, gentem Gothorum, ea tempestate intactam, ideoque saevissimam, conspirantem in unum, ad pervadenda parari collimitia Thraciarum: hocque cognito, ut impraepedite ipse pergeret quo tendebat, sufficiens equitum adiumentum et peditum, mitti iussit ad loca, in quibus barbarici timebantur excursus.", "st": "26.6"}, {"sp": "N", "t": "Dimoto itaque longius principe, Procopius aerumnis diuturnis attritus, et vel atrocem mortem clementiorem ratus malis quibus afflictabatur, aleam periculorum omnium iecit abrupte, et extrema iam perpeti nequaquam timens, praeeunte perdita ratione, facinus adoritur audacissimum; Divitenses, Tungricanosque Iuniores, ad procinctum urgentem per Thracias inter alios celerare dispositos, et Constantinopoli moraturos sollemniter biduum, per quosdam ex eisdem numeris notos sollicitare properans (quia cum omnibus loqui, periculosum erat et arduum), fidem paucorum elegit.", "st": "26.6"}, {"sp": "N", "t": "Qui pellecti spe praemiorum ingentium, sub consecratione iuris iurandi, promisere se quae vellet cuncta facturos, favorem quoque polliciti conturmalium, inter quos ipsi potiorem locum obtinebant in suadendo, stipendiis excellentes et meritis.", "st": "26.6"}, {"sp": "N", "t": "Utque condictum est, ubi excanduit radiis dies, idem Procopius, diductus in cogitationes varias, Anastasianas balneas petit, a sorore Constantini cognominatas, ubi locata noverat signa, doctusque per arcanorum conscios omnes in eius studium consensisse, societate coita nocturna, fide salutis data libenter, admissus constipatione vendibilium militum, cum honore quidem, sed in modum tenebatur obsessi, qui ut praetoriani quondam, post Pertinacis necem licitantem imperii praemia, Iulianum susceperant, ipsi quoque Procopium, infausti dominatus exordia molientem, attenti ad omne compendium defenderunt.", "st": "26.6"}, {"sp": "N", "t": "Stetit itaque subtabidus—excitum putares ab inferis,—nusquam reperto paludamento, tunica auro distincta, ut regius minister, indutus, a calce in pubem, in paedagogiani pueri speciem, purpureis opertus tegminibus pedum, hastatusque purpureum itidem pannulum laeva manu gestabat, ut in theatrali scaena simulacrum quoddam insigne per aulaeum vel mimicam cavillationem subito putares emersum.", "st": "26.6"}, {"sp": "N", "t": "Ad hoc igitur dehonestamentum honorum omnium ludibriose sublatus, et ancillari adulatione, beneficii allocutus auctores, opesque pollicitus amplas et dignitates, ob principatus primitias, processit in publicum multitudine stipatus armorum, signisque sublatis erectius ire pergebat, circumclausus horrendo fragore scutorum, lugubre concrepantium, quae metuentes ne a celsioribus tectis, saxis vel tegularum fragmentis conflictaretur, densius ipsis galearum cristis aptabant.", "st": "26.6"}, {"sp": "N", "t": "Huic intimidius incedenti, nec resistebat populus nec favebat; accendebatur tamen insita plerisque vulgarium, novitatis repentina iucunditate, ea re potius incitante, quod Petronium (ut praediximus) divitias violenter augentem, omnes eadem mente detestabantur, qui sepulta iam dudum negotia, et redivivas nebulas debitorum, in diversos ordines excitabat.", "st": "26.6"}, {"sp": "N", "t": "Cum itaque tribunal idem escendisset Procopius, et cunctis stupore defixis, timeret silentium triste, procliviorem viam ad mortem (ut sperabat), existimans advenisse, per artus tremore diffuse, implicatior ad loquendum, diu tacitus stetit; pauca tamen interrupta et moribunda voce dicere iam exorsus, quibus stirpis propinquitatem imperatoriae praetendebat, leni paucorum susurro, pretio illectorum, deinde tumultuariis succlamationibus plebis, imperator appellatus incondite, petit curiam raptim. Ubi nullo clarissimorum sed ignobilium paucitate inventa, palatium pessimo pede, festinatis passibus introiit.", "st": "26.6"}, {"sp": "N", "t": "Mirantur quidam profecto irrisione digna principia incaute coepta et temere, ad ingemiscendas erupisse rei publicae clades, ignari forsitan exemplorum, accidisse primitus arbitrantes.", "st": "26.6"}, {"sp": "N", "t": "Sic Adramytenus Andriscus, de genere quidam infimae sortis, ad usque Pseudophilippi nomen evectus, bellis Macedonicis tertium addidit grave. Sic Antiochiae Macrino imperatore agente, ab Emesa Heliogabalus exsiluit Antoninus. Ita inopino impetu Maximini, Alexander cum Mamaea matre confossus est. Ita in Africa superior Gordianus in imperium raptus, adventantium periculorum angoribus implicatus vitam laqueo spiritu intercluso profundit.", "st": "26.6"}, {"sp": "N", "t": "Igitur cuppediarum vilium mercatores, et qui intra regiam apparebant, aut apparere desierant, quique coetu militarium nexi, ad pacatiora iam vitae discesserant, in insoliti casus ambigua, partim inviti, alii volentes, adsciscebantur, non nulli omnia tutiora praesentibus rati, e civitate occulte dilapsi, imperatoris castra petivere, itineribus festinatis.", "st": "26.7"}, {"sp": "N", "t": "Hos omnes Sophronias vivacissimo cursu praegressus (tunc notarius) praefectus postea Constantinopoleos, Valentem a Caesarea Cappadocum iam profecturum, ut vaporatis aestibus Ciliciae iam lenitis, ad Antiochiae percurreret sedes, textu narrato gestorum, spe dubia (ut in talibus) percitum et stupentem, avertit Galatiam, res adhuc trepidas arrepturum.", "st": "26.7"}, {"sp": "N", "t": "Qui dum itineribus properat magnis, attentissima cura Procopius in dies agitabatur et noctes, subditivos quosdam ostentans, qui astutia confidenti, partim ab Oriente, alii e Gallis se venisse et Valentinianum obisse fingentes, cuncta patere novo et favorabili principi, memorabant.", "st": "26.7"}, {"sp": "N", "t": "Et quia res novae petulanter arreptae, celeritate muniri solent interdum, nequid formidandum omitteretur, confestim Nebridius, in locum Saluti praefectus praetorio, factione Petronii recens promotus, et Caesarius Constantinopolitanae urbis praefectus, in vincula compinguntur, et iubetur civitatem curare solita potestate Phronemius, esseque magister officiorum Euphrasius, ambo Galli institutis bonarum artium spectatissimi, et administratio negotiorum castrensium, Gomoario et Agiloni revocatis in sacramentum, committitur inconsulte, ut docuit rerum exitus proditarum.", "st": "26.7"}, {"sp": "N", "t": "Quia igitur Iulius comes, per Thracias copiis militaribus praesidens, oppressurus rebelles, si comperisset conata, ex propinquis stationibus timebatur, commentum excogitatum est validum, et quasi iussu Valentis, seria super barbaricis motibus tractaturus, Nebridii litteris adhuc clausi violenter expressis, accitus Constantinopolim, strictius tenebatur. Hacque callida fraude bellatrices Thraciae gentes sine cruore adquisitae, adminicula ausis tumultuariis maxima compararunt.", "st": "26.7"}, {"sp": "N", "t": "Post quae ita eventu laetiore completa, Araxius exambita regia praetorio praefectus accessit, velut Agilone genero suffragante, aliique plures ad aulae varios actus et administrandas provincias sunt admissi, quidam inviti, alii ultro semet offerentes cum praemiis.", "st": "26.7"}, {"sp": "N", "t": "Utique in certaminibus intestinis usu venire contingit, emergebant ex vulgari faece non nulli, desperatione consiliisque ductantibus caecis, contraque quidam orti splendide a culminibus summis ad usque mortes et exsilia corruebant.", "st": "26.7"}, {"sp": "N", "t": "Ubi per haec et similia factio firmiter videbatur esse composita, restabat ut abundans cogeretur militum manus, et impetratum est facile, id quod in publicis turbamentis, aliquotiens ausa ingentia, vel iustis exorsa primordiis impedivit.", "st": "26.7"}, {"sp": "N", "t": "Transeuntes ad expeditionem per Thracias, concitatae equitum peditumque turmae, blandeque acceptae et liberaliter, cum essent omnes in unum quaesitae iamque exercitus species apparebat, promissis uberrimis inhiantes, sub exsecrationibus diris in verba iuravere Procopii, hanc polliciti pertinaciam, quod eum suis animis defensabunt.", "st": "26.7"}, {"sp": "N", "t": "Inventa est enim occasio ad illiciendos eos perquam opportuna, quod Constanti filiam parvulam, cuius recordatio colebatur, sinu ipse circumferens necessitudinem praetendebat eiusdem. Adeptusque est aliud tempori congruum, quod Faustina matre puellae, casu praesente, quaedam acceperat habitus insignia principalis.", "st": "26.7"}, {"sp": "N", "t": "Adiungit his aliud veloci diligentia maturandum, et electi quidam stoliditate praecipites, ad capessendum Illyricum missi sunt, nullo praeter petulantiam adiumento confisi, aureos scilicet nummos, effigiatos in vultum novi principis, aliaque ad illecebras aptantes, quos correptos Aequitius, per eas regiones militum rector, exstinxit genere diverso poenarum.", "st": "26.7"}, {"sp": "N", "t": "Pariaque deinde metuens, obstruxit tres aditus angustissimos, per quos provinciae temptantur arctoae, unum per Daciam ripensem, alterum per Succos notissimum, tertium per Macedonas, quem appellant Acontisma. Hacque cautela vana persuasione rapiendi Illyrici destitutus usurpator indebitae potestatis magna perdidit instrumenta bellorum.", "st": "26.7"}, {"sp": "N", "t": "Dum haec ita aguntur, atrocitate nuntii Valens perculsus iamque revertens per Gallograeciam, auditis apud Constantinopolim gestis, diffidenter incedebat et trepide, ac repentino pavore vias providendi turbante, eo usque desponderat animum, ut augustos amictus abicere tamquam gravem sarcinam cogitaret, fecissetque profecto, ni vetantibus proximis, detractus a deformi proposito, firmatusque meliorum sententiis, agmina duo praeire iussisset, quibus nomina sunt Iovii atque Victores, castra perduellium irrupturos.", "st": "26.7"}, {"sp": "N", "t": "His iam propinquantibus, ipse Procopius a Nicaea regressus, quo nuper advenerat, cum Divitensibus desertorumque plebe promiscua, quam dierum brevi spatio congregarat, Mydgum acceleravit, qui locus Sangario alluitur flumine.", "st": "26.7"}, {"sp": "N", "t": "Ubi cum legiones iam pugnaturae congrederentur, inter reciprocantes missilia quasi procursatione hostem lacessens, solus prorupit in medium. Et secundioris ductu fortunae, ex contraria acie velut agnitum quendam Vitalianum, quem si norat ambigitur, Latine salute data blande produxit, eumque porrecta dextera saviatus omnibus hinc inde attonitis.", "st": "26.7"}, {"sp": "N", "t": "“En” inquit “cana Romanorum exercituum fides et religionibus firmis iuramenta constricta! Placet, fortissimi viri, pro ignotis tot suorum consurrexisse mucrones, utque Pannonius degener, labefactans cuncta et proterens, imperio quod ne votis quidem concipere ausus est umquam, potiatur, ingemiscere nos vestris nostrisque vulneribus! Quin potius sequimini culminis summi prosapiam, non ut rapiat aliena, sed in integrum maiestatis avitae restituatur, arma iustissima commoventem.”", "st": "26.7"}, {"sp": "N", "t": "Hac sermonis placiditate molliti omnes, qui acriter venerant pugnaturi, signorum apicibus aquilisque summissis descivere libentes ad eum, et pro terrifico fremitu, quem barbari dicunt barritum, nuncupatum imperatorem, stipatumque de more, consentientes in unum, reduxerunt ad castra, testati more militiae Iovem, invictum Procopium fore.", "st": "26.7"}, {"sp": "N", "t": "Huic perduellium prosperitati alia laetior accessit. Rumitalca enim tribunus, in societatem Procopianorum adscitus, et suscepta cura palatii, digesto mature consilio, permeatoque cum militibus mari, ad Drepanum ante, nunc Helenopolim venit, exindeque Nicaeam spe celerius occupavit.", "st": "26.8"}, {"sp": "N", "t": "Ad quam obsidendam, cum huius modi pugnarum peritis, Vadomario misso, ex duce et rege Alamannorum, Valens Nicomediam pergit. Exindeque profectus, oppugnationi Chalcedonis magnis viribus insistebat, cuius e muris probra in eum iaciebantur, et irrisive compellebatur ut Sabaiarius. Est autem sabaia ex ordeo vel frumento, in liquorem conversis, paupertinus in Illyrico potus.", "st": "26.8"}, {"sp": "N", "t": "Fessus denique inopia commeatuum, et obstinatione nimia defensorum, discedere iam parabat, cum inter haec clausi apud Nicaeam, patefactis subito portis, egressi, munitorum magna parte prostrata, ductore fidentissimo Rumitalca, properabant ardenter circumventuri Valentem a tergo, nondum a Chalcedonos suburbano digressum, et patrassent conata, ni rumore quodam praeverso, imminens exitium ille perdoctus, instantem vestigiis hostem per Sunonensem lacum et fluminis Galli sinuosos amfractus propere discedendo, frustra sequentem lusisset. Et hoc casu Bithynia quoque in Procopii dicionem redacta est.", "st": "26.8"}, {"sp": "N", "t": "Unde cum Ancyram Valens citis itineribus revertisset, comperissetque Lupicinum ab Oriente cum catervis adventare, non contemnendis, spe prosperorum erectior, Arintheum lectissimum ducem occursurum hostibus misit.", "st": "26.8"}, {"sp": "N", "t": "Qui ubi Dadastanam tetigit, in qua statione perisse diximus Iovianum, Hyperechium, sibi oppositum, repente vidit cum copiis, antehac cellae castrensis apparitorem, id est ventris ministrum et gutturis, cui ut amico Procopius auxilia ductanda commisit. Et dedignatus hominem superare certamine despicabilem, auctoritatis et celsi fiducia corporis, ipsis hostibus iussit, suum vincire rectorem: atque ita turmarum antesignanus umbratilis comprensus suorum est manibus.", "st": "26.8"}, {"sp": "N", "t": "Quae dum hoc modo procedunt, Venustus quidam, largitionum apparitor sub Valente, multo ante Nicomediam missus, ut aurum susceptum stipendii nomine, militibus per Orientem diffusis, viritim tribueret, hac tristitia cognita, alienum pervidens tempus, Cyzicum cum his quae susceperat, se citius contulit.", "st": "26.8"}, {"sp": "N", "t": "Ubi forte Serenianus repertus, domesticorum tunc comes, missus ad thesauros tuendos, urbem inexsuperabili moenium ambitu, monumentis quoque veteribus cognitam, fretus tumulturio praesidio, custodibat: ad quam expugnandam, Procopius, ut possessa Bithynia, sibi etiam Hellespontum iungeret, validam destinaverat manum.", "st": "26.8"}, {"sp": "N", "t": "Morabantur autem effectum sagittis et glandibus, ceterisque iaculis, obsidentium saepe globi confixi, et propugnatorum sollertia, claustrum per catenam ferream valde robustam ori portus insertum, quae ne rostratae irruerent naves hostiles, erat altrinsecus colligata.", "st": "26.8"}, {"sp": "N", "t": "Hanc post varios militum labores et ducum, fatigatorum acerrimis proeliis, Aliso quidam tribunus abscidit, exsertus bellator et prudens, hoc modo. Coniunctis tribus navigiis, testudinem hac specie superstruxit: densetis cohaerentes supra capita scutis, primi transtris instabant armati, alii post hos semet curvantes humilius, tertiis gradatim inclinatis summisse, ita ut novissimi suffraginibus insidentes, formam aedificii fornicati monstrarent. Quod machinae genus contra murales pugnas ideo figuratur hac specie, ut missilium ictus atque saxorum, per decursus cadentium labiles, instar imbrium evanescant.", "st": "26.8"}, {"sp": "N", "t": "Itaque coniectu telorum Aliso paulisper defensus, ingenti corporis robore, supposito stipite, eandem catenam fortius bipenni concidens, ita confregit, ut disiecta patefaceret aditum latum, hocque exitu civitas hostili impetu patuit improtecta. Qua causa exstincto postea proterviae totius auctore, cum in factionis participes saeviretur, hic idem tribunus, contemplatione facinoris clari, vitam cum militia retinens, diu post in Isauria oppetit, v astatoria manu confossus.", "st": "26.8"}, {"sp": "N", "t": "Hoc Marte Cyzico reserata, Procopius ad eam propere festinavit, veniaque universis qui repugnavere donatis, Serenianum solum iniectis vinculis, iussit duci Nicaeam servandum artissime.", "st": "26.8"}, {"sp": "N", "t": "Statimque Ormizdae mature iuveni, Ormizdae regalis illius filio, potestatem proconsulis detulit, et civilia more veterum et bella recturo. Qui agens pro moribus lenius, a militibus quos per devia Phrygiae, miserat Valens, subito corripiendus incursu, tanto vigore evasit, ut escensa navi quam ad casus pararat ancipites, sequentem ac paene captam uxorem, sagittarum nube diffusa defensam, averteret secum: matronam opulentam et nobilem, cuius verecundia et destinatio gloriosa, abruptis postea discriminibus, maritum exemit.", "st": "26.8"}, {"sp": "N", "t": "Ea victoria ultra homines sese Procopius efferens, et ignorans quod quivis beatus, versa rota Fortunae, ante vesperum potest esse miserrimus, Arbitionis domum, cui antea tamquam eadem sibi sentientis parcebat, ut propriae, iussit exinaniri, mobilis census inaestimabilis plenam, ideo indignatus, quod venire ad eum accitus, aliquotiens distulit, causatus incommoda senectutis, et morbos.", "st": "26.8"}, {"sp": "N", "t": "Et licet hac ex causa praesumptor momentum pertimesceret grave, tamen, cum obsistente nullo se in orientales provincias effundere libenti cunctorum assensione, iam licentius posset, avidas novitatem quandam visere, taedio asperioris imperii, quo tune tenebantur: erga alliciendas quasdam civitates Asiae legendosque eruendi peritos auri (ut sibi profuturos proeliis, quae magna exspectabat et crebra), segnius commoratus, in modum acuti mucronis obtunsus est.", "st": "26.8"}, {"sp": "N", "t": "Ut quondam Pescennius Niger, ad subveniendum spei rerum extremae, a Romano populo saepe accitus, dum diu cunctatur in Syria, a Severo superatus in sinu Issico (qui est in Cilicia, ubi Dareum Alexander fudit) fugatusque in suburbano quodam Antiochiae, gregarii manu militis interiit.", "st": "26.8"}, {"sp": "N", "t": "Haec adulta hieme Valentiniano et Valente consulibus agebantur. translato vero in Gratianum, adhuc privatum, et Dagalaifum amplissimo magistratu, aperto iam vere, suscitatis viribus Valens, iuncto sibi Lupicino cum robustis auxiliis, Pessinunta signa propere tulit, Phrygiae quondam, nunc Galatiae oppidum.", "st": "26.9"}, {"sp": "N", "t": "Quo praesidiis tutius communito, nequid inopinum per eos emergeret tractus, praeter radices Olympi montis excelsi, tramitesque fragosos, ire tendebat ad Lyciam, oscitantem ibi Gomoarium aggressurus.", "st": "26.9"}, {"sp": "N", "t": "Cui pertinaci conspiratione multorum, hac maxima consideration resistebatur, quod hostis eius (ut ante relatum est), Constanti filiam parvulam, cum matre Faustina, et in agminibus et cum prope in acie starent, lectica circumferens secum, ut pro imperiali germine cui se quoque iunctum addebat, pugnarent audentius, iras militum accenderat. Sicut aliquando dimicaturi Macedones cum Illyriis, regem adhuc infantem in cunis locavere post aciem, cuius metu ne traheretur captivus, adversos fortius oppresserunt.", "st": "26.9"}, {"sp": "N", "t": "Contra has calliditatis argutias, sagaci opitulatione nutanti negotio, consuluit imperator: et Arbitionem ex consule, agentem iam dudum in otio, ad se venire hortatus est, ut Constantiniani ducis verecundia truces animi lenirentur, neque secus evenit.", "st": "26.9"}, {"sp": "N", "t": "Nam cum omnibus provectior natu, et dignitate sublimior, canitiem reverendam ostenderet, multis ad perfidiam inclinatis, publicum grassatorem Procopium, milites vero secutos eius errorem, filios et laborum participes pristinorum, appellans, orabat, ut se ac si parentem magis sequerentur, felicissimis ductibus cognitum, quam profligate morem gererent nebuloni, destituendo iam et casuro.", "st": "26.9"}, {"sp": "N", "t": "Quibus cognitis Gomoarius, cum elusis hostibus unde venerat, redire posset innoxius, ad castra imperatoris, opportunitate intervalli proximi nactus captivi colore transivit, velut accursu multitudinis visae subito circumsaeptus.", "st": "26.9"}, {"sp": "N", "t": "Qua succensus alacritate, Valens castra promovit ad Phrygiam et prope Nacoliam collatis manibus partium, dum in ancipiti articulo proelium versaretur, Agilo rem excursu prodidit repentino, eumque secuti complures, iam pila quatientes et gladios, ad imperatorem transeunt cum vexillis, scuta perversa gestantes, quod defectionis signum est apertissimum.", "st": "26.9"}, {"sp": "N", "t": "Hoc praeter spem omnium viso Procopius, salutis intercluso suffragio, versus in pedes, circumiectorum nemorum secreta petebat et montium, Florentio sequente et Barchalba tribuno, quem per saevissima bella iam inde a Constanti temporibus notum, necessitas in crimen traxerat, non voluntas.", "st": "26.9"}, {"sp": "N", "t": "Maiore itaque noctis parte consumpta, cum a vespertino ortu luna praelucens in diem metum augeret, undique facultate evadendi exempta, consiliorum inops Procopius, ut in arduis necessitatibus solet, cum Fortuna expostulabat luctuosa et gravi, mersusque multiformibus curis, subito a comitibus suis artius vinctus, relate iam die, ductus ad castra, imperatori offertur, reticens atque defixus, statimque abscisa cervice, discordiarum civilium gliscentes turbines sepelivit et bella, ad veteris Perpennae exemplum, qui post Sertorium inter epulas obtruncatum, dominatione paulisper potitus, a frutectis ubi latebat, extractus, oblatusque Pompeio, eius iussu est interfectus.", "st": "26.9"}, {"sp": "N", "t": "Parique indignationis impetu Florentius et Barchalba, qui eum duxerunt, confestim, non pensata ratione, sunt interfecti. Nam si principem legitimum prodidissent, vel ipsa Iustitia iure caesos pronuntiaret; si rebellem et oppugnatorem internae quietis, ut ferebatur, amplas eis memorabilis facti oportuerat deferri mercedes.", "st": "26.9"}, {"sp": "N", "t": "Excessit autem vita Procopius anno quadragesimo, amplius mensibus decem: corpore non indecoro, nec mediocris staturae, subaquilus, humumque intuendo semper incedens, perque morum tristium latebras, illius similis Crassi, quem in vita semel risisse, Lucilius affirmat et Tullius, sed (quod est mirandum), quoad vixerat, incruentus.", "st": "26.9"}, {"sp": "N", "t": "Eisdem fere diebus, protector Marcellus, eiusdem cognatus, agens apud Nicaeam praesidium, proditione militum et interitu Procopii cognito, Serenianum intra palatium clausum, medio noctis horrore incautum adortus, occidit. Cuius mors saluti plurimis fuit.", "st": "26.10"}, {"sp": "N", "t": "Nam si victoriae superfuisset incultis moribus homo, et nocendi acerbitate conflagrans, Valentique ob similitudinem morum, et genitalis patriae vicinitatem, acceptus, occultas voluntates principis introspiciens, ad crudelitatem propensioris multas innocentium ediderat strages.", "st": "26.10"}, {"sp": "N", "t": "Quo interfecto, idem Marcellus, occupata celeri cursu Chalcedone, concrepantibus paucis, quos vilitas et desperatio trudebat in scelus, umbram principatus funesti capessit, gemina ratione fallente, quod et Gothorum tria milia regibus iam lenitis, ad auxilium transmissa Procopio, Constantianam praetendenti necessitudinem, ad societatem suam parva mercede traduci posse existimabat, quodque gesta in Illyrico etiam tum latebant.", "st": "26.10"}, {"sp": "N", "t": "Inter quae tam trepida, speculationibus fidis Aequitius doctus, conversam molem belli totius in Asiam, degressus per Succos, Philippopolim clausam praesidiis hostium, Eumolpiadam veterem, reserare magna vi conabatur, urbem admodum opportunam et impedituram eius appetitus, si pone relicta adiumenta Valenti laturus (nondum enim apud Nacoliam gesta compererat), festinare ad Haemimontum cogeretur.", "st": "26.10"}, {"sp": "N", "t": "Verum paulo postea cognita levi praesumptione Marcelli, milites missi sunt audaces et prompti, qui eum raptum, ut deditum noxae mancipium, in custodiam compegerunt. Unde post dies paucos productus, lateribus sulcatis acerrime, pariaque perpessis consortibus, interiit, hoc favorabilis solo quod abstulit Serenianum e medio, crudelem ut Phalarim, et illi fidum quia doctrinarum diritatem causis inanibus praetexebat.", "st": "26.10"}, {"sp": "N", "t": "Exstirpatis occasu ducis funeribus belli, saevitum est in multos acrius quam errata flagitaverant vel delicta, maximeque in Philippopoleos defensores, qui urbem seque ipsos, non nisi capite viso Procopii, quod ad Gallias portabatur, aegerrime dediderunt.", "st": "26.10"}, {"sp": "N", "t": "Ad gratiam tamen precantium, coerciti sunt aliqui lenius. Inter quos eminebat Araxius, in ipso rerum exustarum ardore adeptus ambitu praefecturam, et Agilone intercedente genero supplicio insulari multatus, breve post tempus evasit.", "st": "26.10"}, {"sp": "N", "t": "Euphrasius vero, itemque Phronemius, missi ad occiduas partes, arbitrio obiecti sunt Valentiniani, et absolute Euphrasio, Phronemius Cherronesum deportatur, inclementius in codem punitus negotio, ea re quod divo Iuliano fuit acceptus, cuius memorandis virtutibus, ambo fratres principes obtrectabant, nec similes eius, nec suppares.", "st": "26.10"}, {"sp": "N", "t": "His accedebant alia graviora, et multo magis quam in proeliis formidanda. Carnifex enim, et unci, et cruentae quaestiones, sine discrimine ullo aetatum et dignitatum, per fortunas omnes et ordines grassabantur, et pacis obtentu latrocinium detestandum agitabatur, infaustam victoriam exsecrantibus universis internecivo bello quovis graviorem.", "st": "26.10"}, {"sp": "N", "t": "Nam inter arma et lituos condicionis aequatio leviora facit pericula, et Martiae virtutis potestas, aut absumit quod occupat, aut nobilitat, et mors (si acciderit), nullum ignominiae continet sensum, finemque secum vivendi simul et dolendi perducit: ubi vero consiliis impiis iura quidem praetenduntur et leges, et Catonianae vel Cassianae sententiae fuco perliti resident iudices, agatur autem, quod agitur, ad voluntatem praetumidae potestatis, et ex eius libidine, incidentium vitae necisque momenta pensantur, ibi capitalis vertitur pernicies et abrupta.", "st": "26.10"}, {"sp": "N", "t": "Nam ut quisque ea tempestate ob quamlibet valuerat causam, regio imperio prope accedens, et aliena rapiendi aviditate exustus, licet aperte insontem, arcessens, ut familiaris suscipiebatur et fidus, ditandus casibus alienis.", "st": "26.10"}, {"sp": "N", "t": "Imperator enim promptior ad nocendum, criminantibus patens, et funereas delationes adsciscens, per suppliciorum diversitates effrenatius exsultavit, sententiae illius Tullianae ignarus, docentis infelices esse eos qui omnia sibi licere existimarunt.", "st": "26.10"}, {"sp": "N", "t": "Haec implacabilitas causae quidem piissimae, sed victoriae foedioris, innocentes tortoribus exposuit multos, vel sub eculeo locavit incurvos, aut ictu carnificis torvi substravit: quibus (si pateretur natura), vel denas animas profundere praestabat in pugna, quam lateribus fodicatis, omni culpa immunis, fortunis gementibus universis, quasi laesae maiestatis luere poenas, dilaniatis ante corporibus, quod omni est tristius morte.", "st": "26.10"}, {"sp": "N", "t": "Exin cum superata luctibus ferocia deflagrasset, proscriptiones et exsilia et quae leviora quibusdam videntur, quamquam sint aspera, viri pertulere summates, et (ut ditaretur alius) genere nobilis, et forte meritis locupletior, actus patrimonio praeceps, trususque in exsilium consumebatur angore, aut stipe precaria victitabat, nec modus ullus exitialibus malis impositus, quam diu principem et proximos opum satietas cepit et caedis.", "st": "26.10"}, {"sp": "N", "t": "Hoc novatore adhuc superstite, cuius actus multiplices docuimus et interitum, diem duodecimum Kalendas Augustas, consule Valentiniano primum cum fratre, horrendi terrores per omnem orbis ambitum grassati sunt subito, qualis nec fabulae nec veridicae nobis antiquitates exponunt.", "st": "26.10"}, {"sp": "N", "t": "Paulo enim post lucis exortum, densitate praevia fulgurum acrius vibratorum, tremefacta concutitur omnis terreni stabilitas ponderis, mareque dispulsum, retro fluctibus evolutis abscessit, ut retecta voragine profundorum, species natantium multiformes limo cernerentur haerentes, valliumque vastitates et montium tunc (ut opinari dabatur), suspicerent radios solis, quos primigenia rerum natura sub immensis gurgitibus amendavit.", "st": "26.10"}, {"sp": "N", "t": "Multis igitur navibus velut arida humo conexis, et licenter per exiguas undarum reliquias palantibus plurimis, ut pisces manibus colligerent et similia: marini fremitus velut gravati repulsam, versa vice consurgunt, perque vada ferventia insulis et continentis terrae porrectis spatiis violenter illisi, innumera quaedam in civitatibus, et ubi reperta sunt aedificia, complanarunt: proinde ut elementorum furente discordia, involuta facies mundi, miraculorum species ostendebat.", "st": "26.10"}, {"sp": "N", "t": "Relapsa enim aequorum magnitudo cum minime speraretur, milia multa necavit hominum et submersit, recurrentiumque aestuum incitata vertigine, quaedam naves, postquam umentis substantiae consenuit tumor, pessum datae visae sunt, exanimataque naufragiis corpora supina iacebant aut prona.", "st": "26.10"}, {"sp": "N", "t": "Ingentes aliae naves, extrusae rabidis flatibus, culminibus insedere tectorum (ut Alexandriae contigit) et ad secundum lapidem fere procul a litore contortae sunt aliquae, ut Laconicam prope Mothonen oppidum nos transeundo conspeximus, diuturna carie fatiscentem.", "st": "26.10"}, {"sp": "HDR", "t": "Liber XXVII", "st": "27"}, {"sp": "N", "t": "Dum per eoum orbem haec, quae narravimus, diversi rerum expediunt casus, Alamanni post aerumnosas iacturas et vulnera, quae congressi saepe Iuliano Caesari pertulerunt, viribus tandem resumptis, licet imparibus pristinis, ob causam expositam supra Gallicanos limites formidati iam persultabant. Statimque post Kalendas Ianuarias, cum per glaciales tractus hiemis rigidum inhorresceret sidus, cuneatim egressa, multitudo licentius vagabatur.", "st": "27.1"}, {"sp": "N", "t": "Horum portioni primae Charietto, tunc per utramque Germaniam comes, occursurus cum milite egreditur ad bella ineunda promptissimo, adscito in societatem laboris Severiano itidem comite, invalido et longaevo, qui apud Cabillona Divitensibus praesidebat et Tungricanis.", "st": "27.1"}, {"sp": "N", "t": "Proinde confertius agmine in unum coacto, ponteque brevioris aquae festina celeritate transmisso, visos eminus barbaros, Romani sagittis aliisque levibus iaculis incessebant, quae illi reciprocis iactibus valide contorquebant.", "st": "27.1"}, {"sp": "N", "t": "Ubi vero turmae congressae strictis conflixere mucronibus, nostrorum acies impetu hostium acriore concussa nec resistendi nec faciendi fortiter copiam repperit, cunctis metu compulsis in fugam, cum Severianum vidissent equo deturbatum, missilique telo perfossum.", "st": "27.1"}, {"sp": "N", "t": "Ipse denique Charietto, dum cedentes obiectu corporis et vocis obiurgatorio sonu audentius retinet, pudendumque diluere dedecus fiducia diu standi conatur, oppetit telo letali confossus.", "st": "27.1"}, {"sp": "N", "t": "Post cuius interitum, Erulorum Batavorumque vexillum direptum, quod insultando tripudiantes barbari crebro sublatum altius ostendebant, post certamina receptum est magna.", "st": "27.1"}, {"sp": "N", "t": "Qua clade cum ultimo maerore comperta, correcturus secius gesta, Dagalaifus a Parisiis mittitur. Eoque diu cunctante, causanteque diffusos per varia barbaros semet adoriri non posse, accitoque paulo postea ut cum Gratiano, etiam tum privato, susciperet insignia consulatus, Iovinus equitum magister accingitur, et instructus paratusque cautissime, observans utrumque sui agminis latus, venit prope locum Scarponna, ubi inopinus maiorem barbarorum plebem antequam armaretur, temporis brevi puncto praeventam ad internecionem exstinxit.", "st": "27.2"}, {"sp": "N", "t": "Exsultantes innoxii proelii gloria milites, ad alterius globi perniciem ducens, sensimque incedens rector eximius, speculatione didicit fida, direptis propius villis, vastatoriam manum quiescere prope flumen, iamque adventans, abditusque in valle densitate arbustorum obscura, videbat lavantes alios, quosdam comas rutilantes ex more, potantesque non nullos.", "st": "27.2"}, {"sp": "N", "t": "Et nanctus horam impendio tempestivam, signo repente per lituos dato, latrocinalia castra perrupit, contraque Germani, nihil praeter inefficaces minas iactanter sonantes et fremitum, nec expedire arma dispersa, nec componere aciem, nec resurgere in vires permittebantur urguente instanter victore. Quocirca forati pilis et gladiis, cecidere complures, absque his quos versos in pedes texere flexuosi tramites et angusti.", "st": "27.2"}, {"sp": "N", "t": "Hoc prospero rerum effectu, quem virtus peregerat et fortuna, aucta fiducia, Iovinus militem ducens, diligenti speculatione praemissa, in tertium cuneum qui restabat, propere castra commovit, et maturato itinere omnem prope Catelaunos invenit, ad congrediendum promptissimum.", "st": "27.2"}, {"sp": "N", "t": "Et vallo opportune metato, suisque pro temporis copia cibo recreatis et somno, primo aurorae exortu, in aperta planitie composuit aciem, dilatatam arte sollerti, ut spatiis amplioribus occupatis, aequiperare Romani hostium multitudinem apparerent, inferiores numero (licet viribus pares).", "st": "27.2"}, {"sp": "N", "t": "Signo itaque per bucinas dato, cum pede collato res agi coepisset, saeva vexillorum splendentium facie territi, stetere Germani. Quibus hebetatis parumper, reparatisque confestim, ad usque diei extimum concertatione protenta, validius imminens miles, fructum rei bene gestae sine dispendio quaesisset, ni Balchobaudes armaturarum tribunus, magniloquentia socordi coalitus, propinquante iam vespera, cessisset incondite. Quem si secutae residuae cohortes abissent, ad tristes exitus eo usque negotium venerat, ut nec acta nuntiaturus quisquam posset superesse nostrorum.", "st": "27.2"}, {"sp": "N", "t": "Sed resistens animorum acri robore miles, ita lacertis eminuit, ut hostium quattuor milibus sauciis, sex alia interficeret milia, ipse vero non amplius mille ducentis amitteret, ducentis tantummodo vulneratis.", "st": "27.2"}, {"sp": "N", "t": "Noctis itaque adventu proelio iam dirempto, refectisque viribus fessis, prope confinia lucis ductor egregius, in agminis quadrati figuram producto exercitu, cum comperisset occultantibus tenebris barbaros lapses, securus insidiarum per aperta camporum sequebatur et mollia, calcando semineces et constrictos, quos, vulneribus frigorum asperitate contractis, dolorum absumpserat magnitudo.", "st": "27.2"}, {"sp": "N", "t": "Exin progressus ulterius, revertens ubi nullum reppererat, didicit regem hostilium agminum cum paucis captum, ab Ascariis (quos ipse per iter aliud ad diripienda tentoria miserat Alamannica) suffixum patibulo. Ideoque iratus, in tribunum animadvertere statuit, ausum hoc inconsulta potestate superiore fecisse, eumque damnasset, ni militari impetu commissum facinus atrox documentis evidentibus constitisset.", "st": "27.2"}, {"sp": "N", "t": "Ei post haec redeunti Parisios post claritudinem recte gestorum, imperator laetus occurrit, brevique postea consulem designavit, illo videlicet ad gaudii cumulum accedente, quod eisdem diebus Procopii susceperat caput, a Valente transmissum.", "st": "27.2"}, {"sp": "N", "t": "Praeter haec alia multa narratu minus digna conserta sunt proelia, per tractus varios Galliarum, quae superfluum est explicare, cum neque operae pretium aliquod eorum habuere proventus, nec historiam producere per minutias ignobiles decet.", "st": "27.2"}, {"sp": "N", "t": "Hoc tempore vel paulo ante, nova portenti species per Annonariam apparuit Tusciam, idque quorsum evaderet, prodigialium rerum periti penitus ignorarunt. In oppido enim Pistoriensi, prope horam diei tertiam, spectantibus multis, asinus tribunali escenso audiebatur destinatius rugiens, et stupefactis omnibus, qui aderant quique didicerant referentibus aliis, nulloque coniectante ventura postea quod portendebatur evenit.", "st": "27.3"}, {"sp": "N", "t": "Terentius enim, humili genere in urbe natus et pistor, ad vicem praemii, quia peculatus reum detulerat Orfitum ex praefecto, hanc eandem provinciam correctoris administraverat potestate. Eaque confidentia deinceps inquietius agitans multa, in naviculariorum negotio falsum admisisse convictus, ut ferebatur, perit carnificis manu, regente Claudio Romam.", "st": "27.3"}, {"sp": "N", "t": "Multo tamen antequam hoc contingeret, Symmachus Aproniano successit, inter praecipua nominandus exempla doctrinarum atque modestiae. Quo instante urbs sacratissima otio copiisque abundantius solito fruebatur, et ambitioso ponte exsultat quem ipse, iudicio principum maximorum, et magna civium laetitia dedicavit, ingratorum, ut res docuit apertissima.", "st": "27.3"}, {"sp": "N", "t": "Qui consumptis aliquot annis, domum eius in Transtiberino tractu pulcherrimam incenderunt, ea re perciti, quod vilis quidam plebeius finxerat, illum dixisse sine indice ullo vel teste, libenter se vino proprio calcarias exstincturum, quam id venditurum pretiis quibus sperabant.", "st": "27.3"}, {"sp": "N", "t": "Advenit post hunc urbis moderator Lampadius, ex praefecto praetorio, homo indignanter admodum sustinens, si (etiam cum spueret) non laudaretur, ut id quoque prudenter praeter alios faciens, sed non numquam severus et frugi.", "st": "27.3"}, {"sp": "N", "t": "Hic cum magnificos praetor ederet ludos, et uberrime largiretur, plebis nequiens tolerare tumultum, indignis multa donari saepe urgentis, ut et liberalem se et multitudinis ostenderet contemptorem, accitos a Vaticano quosdam egentes, opibus ditaverat magnis.", "st": "27.3"}, {"sp": "N", "t": "Vanitatis autem eius exemplum, ne latius evagemur, hoc unum sufficiet poni, leve quidem, sed cavendum iudicibus. Per omnia enim civitatis membra, quae diversorum principum exornarunt impensae, nomen proprium inscribebat, non ut veterum instaurator, sed conditor. Quo vitio laborasse et Traianus dicitur princeps, unde eum herbam parietinam iocando cognominarunt.", "st": "27.3"}, {"sp": "N", "t": "Hic praefectus exagitatus est motibus crebris, uno omnium maximo, cum collecta plebs infima domum eius prope Constantinianum lavacrum iniectis facibus incenderat et malleolis, ni vicinorum et familiarum veloci concursu a summis tectorum culminibus petita saxis et tegulis abscessisset.", "st": "27.3"}, {"sp": "N", "t": "Eaque vi territus ipse, primitiis crebrescentis seditionis in maius, secessit ad Mulvium pontem, quem struxisse superior dicitur Scaurus, ut lenimenta ibidem tumultus opperiens, quem causa concitaverat gravis.", "st": "27.3"}, {"sp": "N", "t": "Aedificia erigere exordiens nova, vel vetusta quaedam instaurans, non ex titulis solitis parari iubebat impensas, sed si ferrum quaerebatur, aut plumbum, aut aes aut quicquam simile, apparitores immittebantur, qui velut ementes diversas raperent species, nulla pretia persolvendo, unde accensorum iracundiam pauperum, damna deflentium crebra, aegre potuit celeri vitare digressu.", "st": "27.3"}, {"sp": "N", "t": "Advenit successor eius ex quaesitore palatii, Viventius, integer et prudens Pannonius, cuius administratio quieta fuit et placida, copia rerum omnium affluente. Sed hunc quoque discordantis populi seditiones terruere cruentae, quas tale negotium excitarat.", "st": "27.3"}, {"sp": "N", "t": "Damasus et Ursinus supra humanum modum ad rapiendam episcopi sedem ardentes, scissis studiis asperrime conflictabantur, ad usque mortis vulnerumque discrimina adiumentis utriusque progressis, quae nec corrigere sufficiens Viventius nec mollire, coactus vi magna, secessit in suburbanum.", "st": "27.3"}, {"sp": "N", "t": "Et in concertatione superaverat Damasus, parte quae ei favebat instante. Constatque in basilica Sicinini, ubi ritus Christiani est conventiculum, uno die centum triginta septem reperta cadavera peremptorum, efferatamque diu plebem aegre postea delenitam.", "st": "27.3"}, {"sp": "N", "t": "Neque ego abnuo, ostentationem rerum considerans urbanarum, huius rei cupidos ob impetrandum quod appetunt, omni contentione laterum iurgare debere, cum id adepti, futuri sint ita securi, ut ditentur oblationibus matronarum, procedantque vehiculis insidentes, circumspecte vestiti, epulas curantes profusas, adeo ut eorum convivia regales superent mensas.", "st": "27.3"}, {"sp": "N", "t": "Qui esse poterant beati re vera, si magnitudine urbis despecta, quam vitiis opponunt, ad imitationem antistitum quorundam provincialium viverent, quos tenuitas edendi potandique parcissime, vilitas etiam indumentorum, et supercilia humum spectantia, perpetuo numini, verisque eius cultoribus, ut puros commendant, et verecundos. Hactenus deviasse sufficiet, nunc ad rerum ordines revertamur.", "st": "27.3"}, {"sp": "N", "t": "Dum aguntur ante dicta per Gallias et Italiam, novi per Thracias exciti sunt procinctus. Valens enim ut consulto placuerat fratri, cuius regebatur arbitrio, arma concussit in Gothos, ratione iusta permotus, quod auxilia misere Procopio, civilia bella coeptanti. Ergo conveniet pauca super harum origine regionum et situ transcurrere, per brevem excessum.", "st": "27.4"}, {"sp": "N", "t": "Erat Thraciarum descriptio facilis, si veteres concinerent stili, quorum obscura varietas, quoniam opus veritatem professum non iuvat, sufficiet ea quae vidisse meminimus expedire.", "st": "27.4"}, {"sp": "N", "t": "Has terras immensa quondam camporum placiditate aggerumque altitudine fuisse porrectas, Homeri perennis auctoritas docet, aquilonem et zephyrum ventos exinde flare fingentis, quod aut fabulosum est, aut tractus antehac diffusi latissime, destinatique nationibus feris, cuncti Thraciarum vocabulo censebantur.", "st": "27.4"}, {"sp": "N", "t": "Et partem earum habitavere Scordisci, longe nunc ab eisdem provinciis disparati, saevi quondam et truces, et (ut antiquitas docet), hostiis captivorum Bellonae litantes et Marti, humanumque sanguinem in ossibus capitum cavis bibentes avidius, quorum asperitate post multiplices pugnarum aerumnas saepe res Romana vexata postremo omnem amisit exercitum, cum rectore.", "st": "27.4"}, {"sp": "N", "t": "Sed (ut nunc cernimus), eadem loca, formata in cornuti sideris modum, effingunt theatri faciem speciosam. Cuius in summitate occidentali montibus praeruptis densitate Succorum patescunt angustiae, Thracias dirimentes et Daciam.", "st": "27.4"}, {"sp": "N", "t": "Partem vero sinistram, arctois obnoxiam stellis, Haemimontanae celsitudines claudunt, et Hister, qua Romanum caespitem lambit, urbibus multis et castris contiguus et castellis.", "st": "27.4"}, {"sp": "N", "t": "Per dextrum (quod australe est) latus, scopuli tenduntur Rhodopes, unde eoum iubar exsurgit, finitur in fretum; cui undosius ab Euxino ponto labenti, pergentique fluctibus reciprocis ad Aegaeum, discidium panditur terrarum angustum.", "st": "27.4"}, {"sp": "N", "t": "Ex angulo tamen orientali, Macedonicis iungitur collimitiis, per artas praecipitesque vias, quae cognominantur Acontisma: cui proxima Arethusa cursualis est statio, in qua visitur Euripidis sepulcrum, tragoediarum sublimitate conspicui, et Stagira, ubi Aristotelem (ut Tullius ait), fundentem aureum flumen, accipimus natum.", "st": "27.4"}, {"sp": "N", "t": "Haec quoque priscis temporibus loca barbari tenuere, morum sermonumque varietate dissimiles, e quibus praeter alios ut immaniter efferati memorantur Odrysae, ita humanum fundere sanguinem assueti, ut cum hostium copia non daretur, ipsi inter epulas post cibi satietatem et potus, suis velut alienis corporibus imprimerent ferrum.", "st": "27.4"}, {"sp": "N", "t": "Verum aucta re publica, dum consulare vigeret imperium, has gentes antehac semper indomitas, vagantesque sine cultu vel legibus, Marcus Didius ingenti destinatione repressit, Drusus intra fines continuit proprios, Minucius prope amnem Hebrum a celsis Odrysarum montibus defluentem, superatas proelio stravit, post quos residui ab Appio Claudio pro consule sunt infesta concertatione deleti. Oppida enim in Bosporo sita et Propontide classes optinuere Romanae.", "st": "27.4"}, {"sp": "N", "t": "Advenit post hos imperator Lucullus, qui cum durissima gente Bessorum conflixit omnium primus, eodemque impetu Haemimontanos acriter resistentes oppressit. Quo imminente, Thraciae omnes in dicionem veterum transiere nostrorum, hocque modo post procinctus ancipites, rei publicae sex provinciae sunt quaesitae.", "st": "27.4"}, {"sp": "N", "t": "Inter quas prima ex fronte, quae Illyriis est confinis, Thracia speciali nomine appellatur: quam Philippopolis, Eumolpias vetus, et Beroea, amplae civitates exornant. Post hanc Haemimontus Hadrianopolim habet (quae dicebatur Uscudama), et Anchialon, civitates magnas et opulentas. Dein Mysia, ubi Marcianopolis est, a sorore Traiani principis ita cognominata, et Dorostorus et Nicopolis et Odessus, iuxtaque Scythia, in qua celebriora sunt aliis oppida Dionysopolis et Tomi et Calatis. Europa omnium ultima, praeter municipia urbibus nitet duabus, Apris et Perintho, quam Heracleam posteritas dixit.", "st": "27.4"}, {"sp": "N", "t": "Rhodopa huic annexa, Maximianopolim habet et Maroneam et Aenum, qua condita et relicta, Aeneas Italiam auspiciorum prosperitate perpetua, post diuturnos occupavit errores.", "st": "27.4"}, {"sp": "N", "t": "Constat autem (ut vulgavere rumores assidui), omnes paene agrestes, qui per regiones praedictas montium circumcolunt altitudines, salubritate virium, et praerogativa quadam vitae longius propagandae, nos anteire, idque inde contingere arbitrantur, quod colluvione ciborum abstinent calidisque, et perenni viriditate roris asperginibus gelidis corpora constringente, aurae purioris dulcedine potiuntur, radiosque solis, suapte natura vitales, primi omnium sentiunt, nullis adhuc maculis rerum humanarum infectos. His ita digestis, pedem referamus ad coepta.", "st": "27.4"}, {"sp": "N", "t": "Procopio superato in Phrygia, internarumque dissensionum materia consopita, Victor magister equitum ad Gothos est missus, cogniturus aperte, quam ob causam gens amica Romanis, foederibusque longae pacis obstricta, tyranno dederat adminicula, bellum principibus legitimis inferenti. Qui ut factum firma defensione purgarent, litteras eiusdem obtulere Procopii, ut generis Constantiniani propinquo, imperium sibi debitum sumpsisse commemorantis, veniaque dignum asserentes errorem.", "st": "27.5"}, {"sp": "N", "t": "Quibus eodem referente Victore compertis, Valens parvi ducens excusationem vanissimam, in eos signa commovit motus adventantis iam praescios, et pubescente vere, quaesito in unum exercitu, prope Daphnen nomine munimentum, est castra metatus, ponteque contabulato supra navium foros, flumen transgressus est Histrum, resistentibus nullis.", "st": "27.5"}, {"sp": "N", "t": "Iamque sublatus fiducia, cum ultro citroque discurrens, nullum inveniret quem superare poterat vel terrere: omnes enim formidine perciti militis cum apparatu ambitioso propinquantis, montes petivere Serrorum, arduos et inaccessos, nisi perquam gnaris.", "st": "27.5"}, {"sp": "N", "t": "Ne igitur aestate omni consumpta, sine ullo remearet effectu, Arintheo magistro peditum misso cum praedatoriis globis, familiarum rapuit partem, quae antequam ad dirupta venirent et flexuosa, capi potuerunt, per plana camporum errantes. Hocque tantum, quod fors dederat, impetrato, redit cum suis innoxius, nec illato gravi vulnere nec accepto.", "st": "27.5"}, {"sp": "N", "t": "Anno secuto, ingredi terras hostiles pari alacritate conatus, fusius Danubii gurgitibus evagatis, impeditus mansit immobilis prope Carporum vicum, stativis castris ad usque autumnum locatis emensum. Unde quia nihil agi potuit dirimente magnitudine fluentorum, Marcianopolim ad hiberna discessit.", "st": "27.5"}, {"sp": "N", "t": "Simili pertinacia, tertio quoque anno, per Novidunum navibus ad transmittendum amnem conexis, perrupto barbarico, continuatis itineribus longius agentes Greuthungos bellicosam gentem aggressus est, postque leviora certamina, Athanaricum ea tempestate iudicem potentissimum, ausum resistere, cum manu quam sibi crediderit abundare, extremorum metu coegit in fugam, ipseque cum omnibus suis Marcianopolim redivit ad hiemem agendam (ut in illis tractibus) habilem.", "st": "27.5"}, {"sp": "N", "t": "Aderant post diversos triennii casus finiendi belli materiae tempestivae. Prima quod ex principis diuturna permansione metus augebatur hostilis, dein quod commerciis vetitis ultima necessariorum inopia barbari stringebantur, adeo ut, legatos supplices saepe mittentes, venialem poscerent pace.", "st": "27.5"}, {"sp": "N", "t": "Quibus imperator rudis quidem, verum spectator adhuc aequissimus rerum, antequam adulationum perniciosis illecebris captus rem publicam funeribus perpetuo deflendis affligeret, in commune consultans pacem dari oportere decrevit.", "st": "27.5"}, {"sp": "N", "t": "Missique vicissim Victor et Arintheus, qui tunc equestrem curabant militiam et pedestrem, cum propositis condicionibus assentiri Gothos docuissent litteris veris, praestituitur componendae paci conveniens locus. Et quoniam asserebat Athanaricus, sub timenda exsecratione iuris iurandi se esse obstrictum, mandatisque prohibitum patris, ne solum calcaret aliquando Romanum, et adigi non poterat, indecorumque erat et vile ad eum imperatorem transire: recte noscentibus placuit navibus remigio directis in medium flumen, quae vehebant cum armigeris principem, gentisque iudicem inde cum suis, foederari, ut statutum est, pacem.", "st": "27.5"}, {"sp": "N", "t": "Hocque composito, et acceptis obsidibus, Valens Constantinopolim redit, ubi postea Athanaricus proximorum factione genitalibus terris expulsus, fatali sorte decessit et ambitiosis exsequiis ritu sepultus est nostro.", "st": "27.5"}, {"sp": "N", "t": "Inter haec Valentiniano magnitudine quassato morborum, agitanteque extrema, colloquio occultiore Gallorum, qui aderant in commilitio principis, ad imperium Rusticus Iulianus, tunc magister memoriae, poscebatur, quasi afflatu quodam furoris, bestiarum more humani sanguinis avidus, ut ostenderat cum proconsulari potestate regeret Africam.", "st": "27.6"}, {"sp": "N", "t": "In praefectura enim urbana, quam adhuc administrans exstinctus est, tempus anceps metuens tyrannidis, cuius arbitrio, tamquam inter dignorum inopiam, ad id escenderat columen, lenis videri cogebatur et mollior.", "st": "27.6"}, {"sp": "N", "t": "Contra hos nitebantur aliqui studiis altioribus in favorem Severi, magistri tunc peditum, ut apti ad hoc impetrandum, qui licet asper esset et formidatus, tolerabilior tamen fuit, et praeferendus modis omnibus ante dicto.", "st": "27.6"}, {"sp": "N", "t": "Sed dum haec cogitantur in cassum, imperator remediis multiplicibus recreatus, vixque se mortis periculo contemplans extractum, Gratianum filium suum, adulto iam proximum, insignibus principatus ornare meditabatur.", "st": "27.6"}, {"sp": "N", "t": "Et paratis omnibus militeque firmato, ut animis id acciperet promptis, cum Gratianus venisset, progressus in campum, tribunal escendit, splendoreque nobilium circumdatus potestatum, dextra puerum apprehensum, productumque in medium, oratione contionaria destinatum imperatorem exercitui commendabat.", "st": "27.6"}, {"sp": "N", "t": "“Faustum erga me vestri favoris indicium, hunc loci principalis circumferens habitum, quo potior aliis iudicatus sum, multis et claris: consiliorum sociis votorumque auspicibus vobis, pietatis officium aggrediar tempestivum, prospera deo spondente, cuius sempiternis auxiliis stabit Romana res inconcussa.", "st": "27.6"}, {"sp": "N", "t": "“Accipite igitur, quaeso, placidis mentibus, viri fortissimi, desiderium nostrum, id reputantes, quod haec quae fieri caritatis sanciunt iura, non tantum transire voluimus per conscientiam vestram, verum etiam probata firmari, ut congrua vobis et profutura.", "st": "27.6"}, {"sp": "N", "t": "“Gratianum hunc meum adultum, quem diu versatum inter liberos vestros, commune diligitis pignus, undique muniendae tranquillitatis publicae causa, in augustum assumere commilitium paro, si propitia caelestis numinis vestraeque maiestatis voluntas parentis amorem iuverit praeeuntem: non rigido cultu ab incunabulis ipsis (ut nos) educatum, nec tolerantia rerum coalitum asperarum, nec capacem adhuc Martii pulveris, ut videtis, sed familiae suae laudibus, maiorumque factis praestantibus, concinentem—parcius invidiae metu dicitur—protinus surrecturum.", "st": "27.6"}, {"sp": "N", "t": "“Ut enim mihi videri solet mores eius et appetitus, licet nondum maturos, saepe pensanti: ineunte adulescentia, quoniam humanitate et studiis disciplinarum sollertium est expolitus, librabit suffragiis puris merita recte secusve factorum: faciet, ut sciant se boni intellegi: in pulchra facinora procursabit, signis militaribus et aquilis adhaesurus: solem nivesque et pruinas et sitim perferet et vigilias: castris (si necessitas adegerit aliquotiens) propugnabit: salutem pro periculorum sociis obiectabit: et quod pietatis summum primumque munus est, rem publicam ut domum paternam diligere poterit, et avitam.”", "st": "27.6"}, {"sp": "N", "t": "Nondum finita oratione, dictis cum assensu laeto auditis, pro suo quisque loco et animo, milites alius alium anteire festinans, tamquam utilitatis et gaudiorum participes, Gratianum declararunt Augustum, clamorum amplissimo sonu blandum fragorem miscentes armorum.", "st": "27.6"}, {"sp": "N", "t": "Quo viso maiore fiducia Valentinianus exultans, corona indumentisque supremae fortunae ornatum, filium osculatus, iamque fulgore conspicuum, alloquitur advertentem quae dicebantur.", "st": "27.6"}, {"sp": "N", "t": "“En,” inquit, “habes, mi Gratiane, amictus, ut speravimus omnes, augustos, meo commilitonumque nostrorum arbitrio, delatos ominibus faustis. Accingere igitur pro rerum urgentium pondere, ut patris patruique collega, et assuesce impavidus penetrare cum agminibus peditum gelu pervios Histrum et Rhenum, armatis tuis proximus stare, sanguinem spiritumque considerate pro his impendere quos regis, nihil alienum putare, quod ad Romani imperii pertinet statum.", "st": "27.6"}, {"sp": "N", "t": "“Haec pro tempore praecepisse sufficiet, cetera monere non desinam. Nunc reliqui vos estis, rerum maximi defensores, quos rogo et obtestor, ut accrescentem imperatorem fidei vestrae commissum, servetis affectione fundata.”", "st": "27.6"}, {"sp": "N", "t": "His dictis sollemnitate omni firmatis, Eupraxius (Caesariensis Maurus) magister ea tempestate memoriae, primus omnium exclamavit: “Familia Gratiani hoc meretur” statimque promotus quaestor multa et prudentibus aemulanda bonae fiduciae reliquit exempla, nusquam a statu naturae discedens intrepidae, sed constans semper legumque similis, quas omnibus una eademque voce loqui in multiplicibus advertimus causis: qui tunc magis in suscepta parte iustitiae permanebat, cum eum recta monentem, exagitaret minax imperator et nimius.", "st": "27.6"}, {"sp": "N", "t": "Consurrectum est post haec in laudes maioris principis et novelli, maximeque pueri, quem oculorum flagrantior lux commendabat, vultusque et reliqui corporis iucundissimus nitor, et egregia pectoris indoles: quae imperatorem implesset cum veterum lectissimis comparandum, si per fata proximosque licuisset, qui virtutem eius etiam tum instabilem obnubilarunt actibus pravis.", "st": "27.6"}, {"sp": "N", "t": "In hoc tamen negotio, Valentinianus morem institutum antiquitus supergressus, non Caesares sed Augustos germanum nuncupavit et filium, benevole satis. Nec enim quisquam antehac adscivit sibi pari potestate collegam, praeter principem Marcum, qui Verum, adoptivum fratrem, absque diminutione aliqua maiestatis imperatoriae, socium fecit.", "st": "27.6"}, {"sp": "N", "t": "His ex sententia rectoris et militum ordinatis, vix dies intercessere pauci cum Mamertinum, praefectum praetorio, ab urbe regressum, quo quaedam perrexerat correcturus, Avitianus ex vicario peculatus detulerat reum.", "st": "27.7"}, {"sp": "N", "t": "Cui ideo Vulcatius successit Rufinus, omni ex parte perfectus, et velut apicem senectutis honoratae praetendens, sed lucrandi opportunas occasiones occultationis spe numquam praetermittens.", "st": "27.7"}, {"sp": "N", "t": "Qui nanctus copiam principis, Orfitum ex praefecto urbis solutum exsilio, patrimonii redintegrata iactura, remitti fecit in lares.", "st": "27.7"}, {"sp": "N", "t": "Et quamquam Valentinianus, homo propalam ferus, inter imperitandi exordia, ut asperitatis opinionem molliret, impetus truces retinere non numquam in potestate animi nitebatur, serpens tamen vitium et dilatum, paulatim licentius erupit ad perniciem plurimorum, quod auxit ira acerbius effervescens. Hanc enim ulcus esse animi diuturnum, interdumque perpetuum, prudentes definiunt, nasci ex mentis mollitia consuetum, id asserentes argumento probabili, quod iracundiores sunt incolumibus languidi, et feminae maribus, et iuvenibus senes, et felicibus aerumnosi.", "st": "27.7"}, {"sp": "N", "t": "Eminuit tamen per id tempus inter alias humilium neces, mors Dioclis ex comite largitionum Illyrici, quem ob delicta brevia flammis iussit exuri; et Diodori ex agente in rebus, triumque apparitorum potestatis vicariae per Italiam, ob id necatorum atrociter, quod apud eum questus est comes, Diodorum quidem adversus se civiliter implorasse iuris auxilium, officiales vero iussu iudicis ausos monere proficiscentem, ut responderet ex lege. Quorum memoriam apud Mediolanum colentes nunc usque Christiani, locum ubi sepulti sunt Ad Innocentis appellant.", "st": "27.7"}, {"sp": "N", "t": "Dein cum in negotio Maxentii cuiusdam Pannonii, ob exsecutionem a iudice recte maturari praeceptam, trium oppidorum ordines mactari iussisset, interpellavit Eupraxius, tunc quaestor, et “Parcius” inquit “agito, piissime principum: hos enim, quos interfici tamquam noxios iubes, ut martyras (id est divinitati acceptos) colet religio Christiana.”", "st": "27.7"}, {"sp": "N", "t": "Cuius salutarem fiduciam praefectus imitatus Florentius, cum in re quadam venia digna audisset, eum percitum ira, iussisse itidem ternos per ordines urbium interfici plurimarum, “Et quid agetur” ait “si oppidum aliquod curialis non habuerit tantos? Inter reliqua id quoque suspendi debet, ut cum habuerit, occidantur.”", "st": "27.7"}, {"sp": "N", "t": "Ad hanc inclementiam illud quoque accedebat, dictu dirum et factu, quod siquis eum adisset, iudicium potentis inimici declinans, aliumque sibi postulans dari, hoc non impetrato, ad eundem quem metuebat, licet multa praetenderet iusta, remittebatur. Itemque aliud audiebatur horrendum, quod ubi debitorum aliquem egestate obstrictum nihil reddere posse discebat, interfici debere pronuntiabat.", "st": "27.7"}, {"sp": "N", "t": "Haec autem et similia licenter ideo altiore fastu quidam principes agunt, quod amicis emendandi secus cogitata vel gesta copiam negant, inimicos loqui terrent amplitudine potestatis. Nil autem valet correctio pravitatum apud eos qui quod effici velint maximae putant esse virtutis.", "st": "27.7"}, {"sp": "N", "t": "Profectus itaque ab Ambianis, Treverosque festinans, nuntio percellitur gravi, qui Britannias indicabat barbarica conspiratione ad ultimam vexatas inopiam, Nectaridumque comitem maritimi tractus occisum, et Fullofauden ducem hostilibus insidiis circumventum.", "st": "27.8"}, {"sp": "N", "t": "Quibus magno cum horrore compertis, Severum etiam tum domesticorum comitem misit, si fors casum dedisset optatum, correcturum sequius gesta: quo paulo postea revocato, Iovinus … in eadem loca profectus reverti eisdem celeri gradu permisit, adminicula petiturus exercitus validi; id enim instantes necessitates flagitare firmabat.", "st": "27.8"}, {"sp": "N", "t": "Postremo ob multa et metuenda, quae super eadem insula rumores assidui perferebant, electus Theodosius illuc properare disponitur, officiis Martiis felicissime cognitus, asscitaque animosa legionum et cohortium pube, ire tendebat praeeunte fiducia speciosa.", "st": "27.8"}, {"sp": "N", "t": "Et quoniam cum Constantis principis actus componerem, motus adulescentis et senescentis oceani, situmque Britanniae, pro captu virium explanavi, ad ea quae digesta sunt semel, revolvi superfluum duxi, ut Ulixes Homericus apud Phaeacas ob difficultatem nimiam replicare formidat.", "st": "27.8"}, {"sp": "N", "t": "Illud tamen sufficiet dici, quod eo tempore Picti in duas gentes divisi, Dicalydonas et Verturiones, itidemque Attacotti, bellicosa hominum natio, et Scotti, per diversa vagantes, multa populabantur. Gallicanos vero tractus Franci et Saxones, eisdem confines, quo quisque erumpere potuit, terra vel mari, praedis acerbis incendiisque, et captivorum funeribus omnium violabant.", "st": "27.8"}, {"sp": "N", "t": "Ad haec prohibenda, si copiam dedisset fortuna prosperior, orbis extrema dux efficacissimus petens, cum venisset ad Bononiae litus, quod a spatio controverso terrarum, angustiis reciproci distinguitur maris, attolli horrendis aestibus assueti, rursusque sine ulla navigantium noxa, in speciem complanari camporum, exinde transmeato lentius freto, defertur Rutupias, stationem ex adverso tranquillam.", "st": "27.8"}, {"sp": "N", "t": "Unde cum consecuti Batavi venissent et Heruli, Ioviique et Victores, fidentes viribus numeri, egressus tendensque ad Lundinium, vetus oppidum quod Augustam posteritas appellavit, divisis plurifariam globis, adortus est vagantes hostium vastatorias manus, graves onere sarcinarum, et propere fusis, qui vinctos homines agebant et pecora, praedam excussit, quam tributarii perdidere miserrimi.", "st": "27.8"}, {"sp": "N", "t": "Eisdemque restituta omni praeter partem exiguam, impensam militibus fessis, mersam difficultatibus summis antehac civitatem, sed subito, quam salus sperari potuit recreatam, in ovantis speciem laetissimus introiit.", "st": "27.8"}, {"sp": "N", "t": "Ubi ad audenda maiora, prospero successu elatus, tutaque scrutando consilia, futuri morabatur ambiguus, diffusam variarum gentium plebem, et ferocientem immaniter, non nisi per dolos occultiores, et improvisos excursus, superari posse, captivorum confessionibus, et transfugarum indiciis, doctus.", "st": "27.8"}, {"sp": "N", "t": "Denique edictis propositis, impunitateque promissa, desertores ad procinctum vocabat, et multos alios per diversa libero commeatu dispersos. Quo monitu rediere plerique, incentivo perciti, relevatusque anxiis curis, Civilem nomine recturum Britannias pro praefectis, ad se poposcerat mitti, virum acrioris ingenii, sed iusti tenacem et recti, itidemque Dulcitium, ducem scientia rei militaris insignem.", "st": "27.8"}, {"sp": "N", "t": "Haec in Britanniis agebantur. Africam vero, iam inde ab exordio Valentiniani imperii, exurebat barbarica rabies, per procursus audentiores, et crebris caedibus et rapinis intenta. Quam rem militaris augebat socordia, et aliena invadendi cupiditas, maximeque Romani nomine comitis.", "st": "27.9"}, {"sp": "N", "t": "Qui venturi providus transferendaeque in alios invidiae artifex, saevitia morum multis erat exosus, hac praecipue causa, quod superare hostes in vastandis provinciis festinabat, affinitate Remigii tunc magistri officiorum confisus, quo prava et contraria referente, princeps (ut prae se ferebat ipse) cautissimus, lacrimosa dispendia diutius ignoravit Afrorum.", "st": "27.9"}, {"sp": "N", "t": "Gestorum autem per eas regiones seriem plenam, et Rurici praesidis legatorumque mortem, et cetera luctuosa, cum adegerit ratio, diligentius explicabo.", "st": "27.9"}, {"sp": "N", "t": "Et quoniam adest liber locus dicendi quae sentimus, aperte loquemur: hunc imperatorem omnium primum in maius militares fastus ad damna rerum auxisse communium, dignitates opesque eorum sublimius erigentem, et quod erat publice privatimque dolendum, indeflexa saevitia punientem gregariorum errata, parcentem potioribus, qui tamquam peccatis indulta licentia, ad labes delictorum immanium consurgebant; qui ex eo altius anhelantes, ex nutu suo indistanter putant omnium pendere fortunas.", "st": "27.9"}, {"sp": "N", "t": "Horum flatus et pondera inventores iuris antiqui mollientes, etiam insontes quosdam aliquotiens suppliciis aboleri censuere letalibus. Quod saepe contingit, cum ob multitudinis crimina non nulli sortis iniquitate plectuntur innoxii; id enim non numquam ad privatorum pertinuit causas.", "st": "27.9"}, {"sp": "N", "t": "At in Isauria, globatim per vicina digressi praedones, oppida villasque uberes libera populatione vexantes, magnitudine iacturarum Pamphyliam afflictabant et Cilicas. Quos cum nullis arcentibus, internecive cuncta disperdere, Asiae vicarius ea tempestate Musonius advertisset, Athenis Atticis antehac magister rhetoricus, deploratis novissime rebus, luxuque adiumento militari marcente, adhibitis semermibus paucis, quos Diogmitas appellant, unum grassatorum cuneum (si patuisset facultas), adoriri conatus, per angustum quendam transiens devexitatis anfractum, ad inevitabiles venit insidias, et ibi cum his confossus est quos ducebat.", "st": "27.9"}, {"sp": "N", "t": "Tali successu latrones praetumidos, palantesque per varia confidentius, interfectis aliquibus, ad latebrosa montium saxa, quae incolunt, excitae tandem copiae contruserunt; ubi cum eis nec quiescendi nec inveniendi ad victum utilia copia laxaretur, per indutias pacem sibi tribui poposcerunt, Germanicopolitanis auctoribus, quorum apud eos ut signiferae manus semper valuere sententiae, obsidibusque datis (ut imperatum est), immobiles diu mansere, nihil audentes hostile.", "st": "27.9"}, {"sp": "N", "t": "Haec inter Praetextatus praefecturam urbis sublimius curans, per integritatis multiplices actus et probitatis, quibus ab adulescentiae rudimentis inclaruit, adeptus est id quod raro contingit, ut cum timeretur, amorem non perderet civium, minus firmari solitum erga iudices formidatos.", "st": "27.9"}, {"sp": "N", "t": "Cuius auctoritate iustisque veritatis suffragiis, tumultu lenito, quem Christianorum iurgia concitarunt, pulsoque Ursino, alta quies est parta, proposito civium Romanorum aptissima, et adulescebat gloria praeclari rectoris, plura et utilia disponentis.", "st": "27.9"}, {"sp": "N", "t": "Namque et Maeniana sustulit omnia, fabricari Romae priscis quoque vetita legibus, et discrevit ab aedibus sacris privatorum parietes, eisdem inverecunde conexos, ponderaque per regiones instituit universas, cum aviditati multorum, ex libidine trutinas componentium, occurri nequiret. In examinandis vero litibus ante alios id impetravit quod laudando Brutum Tullius refert, ut cum nihil ad gratiam faceret, omnia tamen grata viderentur esse, quae factitabat.", "st": "27.9"}, {"sp": "N", "t": "Sub idem fere tempus, Valentiniano ad expeditionem caute (ut rebatur ipse) profecto, Alamannus regalis (Rando nomine) diu praestruens quod cogitabat, Mogontiacum praesidiis vacuam cum expeditis ad latrocinandum latenter irrepsit.", "st": "27.10"}, {"sp": "N", "t": "Et quoniam casu Christiani ritus invenit celebrari sollemnitatem, impraepedite cuiusque modi fortunae virile et muliebre secus cum supellectili non parva indefensum abduxit.", "st": "27.10"}, {"sp": "N", "t": "Parvo inde post intervallo, inopina rei Romanae spes laetiorum adfulsit. Cum enim Vithicabius rex, Vadomarii filius, specie quidem molliculus et morbosus, sed audax et fortis, ardores in nos saepe succenderet bellicos, opera navabatur impensior, ut qualibet concideret strage.", "st": "27.10"}, {"sp": "N", "t": "Et quia temptatus aliquotiens, nullo genere potuit superari vel prodi, fraude citerioris vitae ministri, studio sollicitante nostrorum, occubuit, cuius post necem aliquatenus hostiles torpuere discursus. Interfector tamen prae metu poenarum, quas verebatur si patuisset negotium, ad Romanum solum se celeri transtulit gradu.", "st": "27.10"}, {"sp": "N", "t": "Parabatur post haec contentioribus curis, et per copias multiformes, in Alamannos expeditio solitis gravior, destinatius id publica tutela poscente, quoniam reparabilis gentis motus timebantur infidi: milite nihilo minus accenso, cui ob suspectos eorum mores nunc infimorum et supplicum, paulo post ultima minitantium, nullae quiescendi dabantur indutiae.", "st": "27.10"}, {"sp": "N", "t": "Contracta igitur undique mole maxima catervarum, armis et subsidiis rei cibariae diligenter instructa, accitoque Sebastiano comite cum Illyricis et Italicis numeris, quos regebat, anni tempore iam tepente Valentinianus cum Gratiano Moenum transiit, visoque nemine, divisis agminibus quadratis, ipse medius incedebat, Iovino et Severo, magistris rei castrensis, altrinsecus ordinum latera servantibus, ne repentino invaderentur adsultu.", "st": "27.10"}, {"sp": "N", "t": "Protinusque inde ductantibus itinerum callidis, exploratis accessibus, per regiones longo situ porrectas, sensim gradiens miles, irritatior ad pugnandum, velut repertis barbaris minaciter infrendebat. Et quoniam aliquot diebus emensis, nullus potuit qui resisteret inveniri, cuncta satorum et tectorum quae visebantur, iniecta cohortium manu, vorax flamma vastabat, praeter alimenta quae colligi dubius rerum eventus adigebat et custodiri.", "st": "27.10"}, {"sp": "N", "t": "Post haec leniore gressu princeps ulterius tendens, cum prope locum venisset, cui Solicinio nomen est, velut quadam obice stetit, doctus procursantium relatione verissima, barbaros longe conspectos.", "st": "27.10"}, {"sp": "N", "t": "Qui nullam ad tuendam salutem viam superesse cernentes, ni se celeri defendissent occursu, locorum gnaritate confisi, unum spirantibus animis, montem occupavere praecelsum, per confragosos colles undique praeruptum et invium, absque septentrionali latere (unde facilem habet devexitatem et mollem). Signis ilico fixis ex more, cum undique ad arma conclamaretur, imperio principis et ductorum stetit regibilis miles, vexillum opperiens extollendum: quod erat opportune subeundae indicium pugnae.", "st": "27.10"}, {"sp": "N", "t": "Ergo quia spatium deliberandi aut exiguum dabatur aut nullum, hinc impatientia militis perterrente, inde horrenda circumsonantibus Alamannis, id consilium ratio celeritatis admisit, ut arctoam montium partem, quam clementer diximus esse proclivem, Sebastianus occuparet cum suis, fugientes Germanos, si fors ita tulisset, levi negotio confossurus: quo ita (ut placuit) maturato, Gratianoque apud signa Iovianorum retro detento, cuius aetas erat etiam tum proeliorum impatiens et laborum, Valentinianus ut dux cunctator et tutus, centurias et manipulos capite intecto collustrans, nullo potentium in conscientiam arcani adhibito, remota multitudine stipatorum, speculatum radices aggerum avolavit cum paucis, quorum industriam norat et fidem, praedicans (ut erat sui arrogans aestimator) inveniri posse aliam viam, ducentem ad arduos clivos, praeter eam quam inspexere procursatores.", "st": "27.10"}, {"sp": "N", "t": "Per ignota itaque et palustres uligines devius tendens, insidiatricis manus locatae per abdita subito oppetisset accursu, ni necessitatis adiumento postremo, per labilem limum incitato iumento digressus, legionum se gremiis immersisset, post abruptum periculum, cui adeo proximus fuit, ut galeam eius cubicularius ferens, auro lapillisque distinctam, cum ipso tegmine penitus interiret, nec postea vivus reperiretur aut interfectus.", "st": "27.10"}, {"sp": "N", "t": "Proinde quiete reficiendis corporibus data, signoque erecto, quod solet ad pugnam hortari, tubarum minacium accendente clangore, fidentissimo impetu acies motas, prompte ante alios praeiere duo iuvenes lecti, in principiis adeundi discriminis, Salvius et Lupicinus, scutarius unus, alter e schola gentilium, bellum fragore terribili concitantes: hastasque crispando, cum ad rupium obiecta venissent, trudentibusque Alamannis evadere ad celsiora conarentur, advenit omne pondus armorum, eisdemque antesignanis, per hirta dumis et aspera, magno virium nisu in editas sublimitates erepsit.", "st": "27.10"}, {"sp": "N", "t": "Acri igitur partium spiritu, conflictus cuspidibus temptatur infestis, et hinc arte belli doctior miles, inde licet feroces sed incauti barbari dexteris coiere collatis, quos latius sese pandens exercitus, infusis utrimque cornibus afflictabat, per fremitus territos, et equorum hinnitus, et tubas.", "st": "27.10"}, {"sp": "N", "t": "Nihilominus tamen ipsi assumpta fiducia restiterunt, aequataque parumper proeliorum sorte, haud parva mole certatum est, dum ruinarum funeribus mutuis res gerebatur.", "st": "27.10"}, {"sp": "N", "t": "Disiecti denique Romanorum ardore, metuque turbati, miscentur ultimis primi, dumque in pedes versi discedunt, verrutis hostilibus forabantur et pilis. Postremo dum anheli currunt et fessi, pandebant sequentibus poplites et suras et dorsa. Stratis denique multis, lapsorum partem Sebastianus, cum subsidiali manu locatus post montium terga, trucidavit ex incauto latere circumventam: dispersi ceteri silvarum se latebris amendarunt.", "st": "27.10"}, {"sp": "N", "t": "In hac dimicatione, nostri quoque periere non contemnendi. Inter quos Valerianus fuit domesticorum omnium primus, et Natuspardo quidam scutarius, exsertus ita bellator, ut Sicinio veteri comparetur, et Sergio. Hisque tali casuum diversitate perfectis, milites ad hiberna, imperatores Treveros reverterunt.", "st": "27.10"}, {"sp": "N", "t": "Per haec tempora Vulcatio Rufino absoluto vita, dum administrat, ad regendam praefecturam praetorianam ab urbe Probus accitus, claritudine generis et potentia et opum amplitudine cognitus orbi Romano, per quem universum paene patrimonia sparsa possedit, iuste an secus, non iudicioli est nostri.", "st": "27.11"}, {"sp": "N", "t": "Hunc quasi genuina quaedam (ut fingunt poetae) fortuna vehens praepetibus pinnis, nunc beneficum ostendebat, et amicos altius erigentem, aliquotiens insidiatorem dirum et per cruentas noxium simultates. Et licet potuit (quoad vixit) ingentia, largiendo et intervallando potestates assiduas, erat tamen interdum timidus ad audaces, contra timidos celsior, ut videretur cum sibi fideret, de cothurno strepere tragico, et ubi paveret, omni humilior socco.", "st": "27.11"}, {"sp": "N", "t": "Atque ut natantium genus, elemento suo expulsum, haud ita diu spirat in terris, ita ille marcebat absque praefecturis, quas ob iugi familiarum licentia, capessere cogebatur, numquam innocentium per cupiditates immensas, utque multa perpetrarent impune, dominum suum mergentium in rem publicam.", "st": "27.11"}, {"sp": "N", "t": "Namque fatendum est numquam ille, magnanimitate coalitus, clienti vel servo agere quicquam iussit illicitum, sed si eorum quemquam crimen ullum compererat admisisse, vel ipsa repugnante Iustitia, non explorato negotio, sine respectu boni honestique defendebat. Quod vitium reprehendens, ita pronuntiat Cicero: “Quid enim interest inter suasorem facti et probatorem? aut quid refert utrum voluerim fieri an gaudeam factum?”", "st": "27.11"}, {"sp": "N", "t": "Suspiciosus tamen et munitus suopte ingenio fuit, et subamarum arridens, blandiensque interdum, ut noceat.", "st": "27.11"}, {"sp": "N", "t": "Id autem perspicuum est in eius modi moribus malum, tum maxime cum celari posse existimatur; ita implacabilis et directus, ut si laedere quemquam instituisset, nec exorari posset nec ad ignoscendum erroribus inclinari, ideoque aures eius non cera sed plumbo videbantur obstructae. In summis divitiarum et dignitatum culminibus, anxius et sollicitus, ideoque semper levibus morbis afflictus. Hae per occidentales plagas series rerum fuere gestarum.", "st": "27.11"}, {"sp": "N", "t": "Rex vero Persidis, longaevus ille Sapor, et ab ipsis imperitandi exordiis dulcedini rapinarum addictus, post imperatoris Iuliani excessum, et pudendae pacis icta foedera, cum suis paulisper nobis visus amicus, calcata fide sub Ioviano pactorum, iniectabat Armeniae manum ut eam, velut placitorum abolita firmitate, dicioni iungeret suae.", "st": "27.12"}, {"sp": "N", "t": "Et primo per artes fallendo diversas, nationem hominum potentem dispendiis levibus afflictabat, sollicitans quosdam optimatum et satrapas, alios excursibus occupans improvisis.", "st": "27.12"}, {"sp": "N", "t": "Dein per exquisitas periuriisque mixtas illecebras, captum regem ipsum Arsacen, adhibitumque in convivium, iussit ad latentem trahi posticam, eumque effossis oculis vinctum catenis argenteis, quod apud eos honoratis vanum suppliciorum aestimatur esse solacium, exterminavit ad castellum Agabana nomine, ubi discruciatus ceciderat ferro poenali.", "st": "27.12"}, {"sp": "N", "t": "Deinde nequid intemeratum perfidia praeteriret, Sauromace pulse, quem auctoritas Romana praefecit Hiberiae, Aspacurae cuidam potestatem eiusdem detulit gentis, diademate addito, ut arbitrio se monstraret insultare nostrorum.", "st": "27.12"}, {"sp": "N", "t": "Quibus ita studio nefando perfectis, Cylaci spadoni et Artabanni, quos olim susceperat perfugas, commisit Armeniam (horum alter ante gentis praefectus, magister alter fuisse dicebatur armorum) eisdemque mandarat, ut Artogerassam intentiore cura exscinderent, oppidum muris et viribus validum, quod thesauros et uxorem cum filio tuebatur Arsacis.", "st": "27.12"}, {"sp": "N", "t": "Iniere (ut statutum est) obsidium duces. Et quoniam munimentum, positum in asperitate montana, rigente tunc caelo nivibus et pruinis, adiri non poterat, eunuchus Cylaces, aptusque ad muliebria palpamenta, Artabanne ascito, prope moenia ipsa, fide non amittendae salutis accepta, propere venit, et cum socio ad interiora susceptus, ut postulavit, suadebat minaciter defensoribus et reginae, motum Saporis inclementissimi omnium lenire deditione veloci.", "st": "27.12"}, {"sp": "N", "t": "Multis post haec ultro citroque dictitatis, heiulanteque muliere truces mariti fortunas, proditionis acerrimi compulsores, in misericordiam flexi, mutavere consilium, et spe potiorum erecti, secretis colloquiis ordinarunt, hora praestituta nocturna, reclusis subito portis, validam manum erumpere, vallumque hostile caedibus aggredi repentinis, ut lateant id temptantes, polliciti se provisuros.", "st": "27.12"}, {"sp": "N", "t": "Quibus religione firmatis, egressi, biduumque ad deliberandum quid capessere debeant, sibi concedi clausos petisse asseverantes, in desidiam obsessores traduxerunt, et vigiliis quibus ob securitatem altiore stertitur somno, civitatis aditu reserato iuventus exsiluit velox, passibusque insonis, expeditis mucronibus, repens, cum castra nihil metuentium invasissent, iacentes multos nullis resistentibus trucidarunt.", "st": "27.12"}, {"sp": "N", "t": "Haec inopina defectio, necesque insperatae Persarum, inter nos et Saporem discordiarum excitavere causas immanes, illo etiam accedente, quod Arsacis filium Papam, suadente matre cum paucis e munimento digressum, susceptumque imperator Valens apud Neocaesaream morari praecepit, urbem Polemoniaci Ponti notissimam, liberali victu curandum et cultu.", "st": "27.12"}, {"sp": "N", "t": "Qua humanitate Cylaces et Artabannes illecti, missis oratoribus ad Valentem, auxilium eundemque Papam sibi regem tribui poposcerunt.", "st": "27.12"}, {"sp": "N", "t": "Sed pro tempore adiumentis negatis, per Terentium ducem Papa reducitur in Armeniam, recturus interim sine ullis insignibus gentem, quod ratione iusta est observatum, ne fracti foederis nos argueremur et pacis.", "st": "27.12"}, {"sp": "N", "t": "Hoc comperto textu gestorum, Sapor ultra hominem efferatus, concitis maioribus copiis, Armenias aperta praedatione vastabat. Cuius adventu territus Papa, itidemque Cylaces et Arrabannes, nulla circumspectantes auxilia, celsorum montium petivere secessus, limites nostros disterminantes et Lazicam, ubi per silvarum profunda, et flexuosos colles mensibus quinque delitescentes, regis multiformes lusere conatus.", "st": "27.12"}, {"sp": "N", "t": "Qui operam teri frustra contemplans, sidere flagrante brumali, pomiferis exustis arboribus, castellisque munitis et castris quae ceperat superata vel prodita, cum omni pondere multitudinis Artogerassam circumsaeptam, et post varies certaminum casus, lassatis defensoribus patefactam incendit: Arsacis uxorem erutam inde cum thesauris abduxit.", "st": "27.12"}, {"sp": "N", "t": "Quas ob causas ad eas regiones Arintheus cum exercitu mittitur comes, suppetias laturus Armeniis, si eos exagitare procinctu gemino temptaverint Persae.", "st": "27.12"}, {"sp": "N", "t": "Inter quae Sapor immensum quantum astutus, et cum sibi conduceret, humilis aut elatus, societatis futurae specie Papam ut incuriosum sui per latentes nuntios increpabat, quod maiestatis regiae velamento, Cylaci serviret et Arrabanni, quos ille praeceps blanditiarum illecebris interfecit, capitaque caesorum ad Saporem ut ei morigerus misit.", "st": "27.12"}, {"sp": "N", "t": "Hac clade late diffusa, Armenia omnis perisset inpropugnata, ni Arinthei adventu territi Persae, eam incursare denuo distulissent, hoc solo contenti, quod ad imperatorem misere legatos, petentes nationem eandem, ut sibi et Ioviano placuerat, non defendi.", "st": "27.12"}, {"sp": "N", "t": "Quibus repudiatis, Sauromaces pulsus (ut ante diximus) Hiberiae regno, cum duodecim legionibus et Terentio remittitur, et eum amni Cyro iam proximum, Aspacures oravit, ut socia potestate consobrini regnarent, causatus ideo se nec cedere, nec ad partes posse transire Romanas, quod Ultra eius filius obsidis lege tenebatur adhuc apud Persas.", "st": "27.12"}, {"sp": "N", "t": "Quae imperator edoctus, ut concitandas ex hoc quoque negotio turbas consilio prudenti molliret, divisioni acquievit Hiberiae, ut eam medius dirimeret Cyrus, et Sauromaces Armeniis finitima retineret et Lazis, Aspacures Albaniae Persisque contigua.", "st": "27.12"}, {"sp": "N", "t": "His percitus Sapor, pati se exclamans indigna, quod contra foederum textum iuvarentur Armenii, et evanuit legatio, quam super hoc miserat corrigendo, quodque se non assentiente, nec conscio, dividi placuit Hiberiae regnum: velut obseratis amicitiae foribus, vicinarum gentium auxilia conquirebat, suumque parabat exercitum, ut reserata caeli temperie subverteret omnia, quae ex re sua struxere Romani.", "st": "27.12"}, {"sp": "HDR", "t": "Liber XXVIII", "st": "28"}, {"sp": "N", "t": "Dum apud Persas (ut supra narravimus), perfidia regis motus agitat insperatos, et in eois tractibus bella rediviva consurgunt, anno sexto decimo et eo diutius post Nepotiani exitium, saeviens per urbem aeternam, urebat cuncta Bellona, ex primordiis minimis ad clades excita luctuosas, quas obliterasset utinam iuge silentium! Ne forte paria quandoque temptentur, plus exemplis generalibus nocitura quam delictis.", "st": "28.1"}, {"sp": "N", "t": "Ac licet ab hoc textu cruento gestorum exquisite narrando iustus me retraheret metus, multa reputantem et varia, tamen praesentis temporis modestia fretus, carptim ut quaeque memoria digna sunt explanabo, nec pigebit quid ex his quae apud veteres acciderunt timuerim docere succincte.", "st": "28.1"}, {"sp": "N", "t": "Bello Medico primo, cum diripuissent Asiam Persae, obsidentes Miletum molibus magnis, minantesque defensoribus cruciabiles neces, iniecere clausis necessitatem, ut omnes magnitudine malorum afflicti, peremptis caritatibus propriis, proiectoque in ignem mobili censu, arsuros se certatim congererent, in communem pereuntis patriae rogum.", "st": "28.1"}, {"sp": "N", "t": "Hoc argumentum paulo postea digestum tumore tragico Phrynichus in theatrum induxerat Athenarum, paulisperque iucunde auditus, cum cothurnatius stilus procederet lacrimosus, indignatione damnatus est populi, arbitrati non consolandi gratia sed probrose monendi, quae pertulerat amabilis civitas, nullis auctorum adminiculis fulta, hos quoque dolores scaenicis adnumerasse fabulis insolenter. Erat enim Atheniensium colonia Miletus, deducta inter Ionas alios per Nileum filium Codri, qui fertur pro patria bello se Dorico devovisse.", "st": "28.1"}, {"sp": "N", "t": "Sed ad proposita veniamus.", "st": "28.1"}, {"sp": "N", "t": "Maximinus regens quondam Romae vicariam praefecturam, apud Sopianas Valeriae oppidum obscurissime natus est, patre tabulario praesidialis officii, orto a posteritate Carporum, quos antiquis excitos sedibus, Diocletianus transtulit in Pannoniam.", "st": "28.1"}, {"sp": "N", "t": "Is post mediocre studium liberalium doctrinarum defensionemque causarum ignobilem, et administratas Corsicam itidemque Sardiniam, rexit deinde Tusciam. Unde morato in itinere diutius successore, transgressus ad curandam urbis annonam, etiam provinciae moderamina retinebat, egitque consideratione triplici inter exordia cautius.", "st": "28.1"}, {"sp": "N", "t": "Primo quod recalebant in auribus eius parentis effata, quid augurales alites vel cantus monerent oscinum adprime callentis, ad usque sublimia regimenta venturum, sed periturum ferro poenali: dein quod nanctus hominem Sardum, quem ipse postea per dolosas fallacias interemit, ut circumtulit rumor, eliciendi animulas noxias, et praesagia sollicitare larvarum, perquam gnarum: dum superesset ille, timens ne proderetur, tractabilis erat et mollior; postremo quod tamquam subterraneus serpens, per humiliora reptando, nondum maiores funerum excitare poterat causas.", "st": "28.1"}, {"sp": "N", "t": "Principium autem unde latius se funditabat, emersit ex negotio tali. Chilo ex vicario, et coniux eius Maxima nomine, questi apud Olybrium, ea tempestate urbi praefectum, vitamque suam venenis petitam asseverantes, impetrarunt ut hi quos suspectati sunt, ilico rapti, compingerentur in vincula, organarius Sericus, et Asbolius palaestrita, et haruspex Campensis.", "st": "28.1"}, {"sp": "N", "t": "Verum negotio tepescente propter diuturnam morborum asperitatem, qua tenebatur Olybrius, morarum impatientes, hi qui rem detulerunt, libello petiverunt oblato, ut examinandum iurgium praefecto mandaretur annonae, idque studio celeritatis concessum est.", "st": "28.1"}, {"sp": "N", "t": "Accepta igitur nocendi materia, Maximinus effudit genuinam ferociam, pectori crudo affixam, ut saepe faciunt amphitheatrales ferae, diffractis tandem solutae posticis.", "st": "28.1"}, {"sp": "N", "t": "Cumque multiformiter quasi in proludiis negotium spectaretur, et quidam sulcatis lateribus, nominassent nobiles aliquos, tamquam usos artificibus laedendi per clientes aliosque humiles, notos reos et indices, supra plantam (ut dicitur) evagatus, tartareus cognitor, relatione maligna, docuit principem, non nisi suppliciis acrioribus, perniciosa facinora scrutari posse vel vindicari, quae Romae perpetravere complures.", "st": "28.1"}, {"sp": "N", "t": "His ille cognitis, efferatus, ut erat vitiorum inimicus acer magis quam severus, uno proloquio, in huius modi causas, quas arroganter proposito maiestatis imminutae miscebat, omnes quos iuris prisci iustitia, divorumque arbitria, quaestionibus exemere cruentis, si postulasset negotium, statuit tormentis affligi.", "st": "28.1"}, {"sp": "N", "t": "Utque congeminata potestas, erectaque sublatius, altiores consarcinaret aerumnas, Maximino Romae agere disposito pro praefectis, sociavit ad haec cognoscenda, quae in multorum pericula struebantur, Leonem notarium, postea officiorum magistrum, bustuarium quendam latronem Pannonium, efflantem ferino rictu crudelitatem, etiam ipsum nihilo minus humani sanguinis avidissimum.", "st": "28.1"}, {"sp": "N", "t": "Auxit obstinatum Maximini ingenium ad laedendum adventus collegae similis et litterarum cum ampla dignitate dulcedo. Ideoque pedes huc et illuc exsultando contorquens, saltare, non incedere videbatur, dum studebat inter altaria celsius gradientes (ut quidam memorant) imitari Brachmanas.", "st": "28.1"}, {"sp": "N", "t": "Iamque lituis cladium concrepantibus internarum, rerum atrocitate torpentibus cunctis, praeter multa cruda et immitia quorum nec diversitas comprehendi, nec numerus potest, mors Marini causarum defensoris eminuit. Quem ut ausum Hispanillae cuiusdam, artibus pravis, affectasse coniugium, transeunter indiciorum fide discussa, supplicio letali damnavit.", "st": "28.1"}, {"sp": "N", "t": "Et quoniam existimo, forsitan aliquos haec lecturos, exquisite scrutando notare, strepentes id actum esse prius, non illud, aut ea quae viderint praetermissa: hactenus faciendum est satis, quod non omnia narratu sunt digna, quae per squalidas transiere personas, nec si fieri fuisset necesse, instructiones vel ex ipsis tabulariis suppeterent publicis, tot calentibus malis, et novo furore, sine retinaculis imis summa miscente, cum iustitium esse, quod timebatur, non iudicium, aperte constaret.", "st": "28.1"}, {"sp": "N", "t": "Tunc Cethegus senator, adulterii reus delatus, cervice perit abscisa, et Alypius nobilis adulescens, ob levem relegatus errorem, aliique humiles, publica morte oppetiverunt: in quorum miseriis, velut sui quisque discriminis cernens imaginem, tortorem et vincula somniabat, et deversoria tenebrarum.", "st": "28.1"}, {"sp": "N", "t": "Eodem tempore etiam Hymetii praeclarae indolis viri, negotium est actitatum, cuius hunc fuisse novimus textum. Cum Africam pro consule regeret, Carthaginiensibus victus inopia iam lassatis, ex horreis Romano populo destinatis, frumentum venumdedit, pauloque postea, cum provenisset segetum copia, integre sine ulla restituit mora.", "st": "28.1"}, {"sp": "N", "t": "Verum quoniam denis modiis singulis solidis indigentibus venundatis, emerat ipse tricenos, interpretii compendium ad principis aerarium misit. Ideoque Valentinianus, per nundinationem suspicatus parum quam oportuerat missum, eum bonorum parte multavit.", "st": "28.1"}, {"sp": "N", "t": "Ad cuius cladem exaggerandam, id quoque eisdem diebus acciderat, non minus exitiale. Amantius haruspex, ea tempestate prae ceteris notus, occultiore indicio proditus, quod ob prava quaedam implenda, ad sacrificandum ab eodem esset adscitus Hymetio, inductusque in iudicium, quamquam incurvus sub eculeo staret, pertinaci negabat instantia.", "st": "28.1"}, {"sp": "N", "t": "Quo infitiante, secretioribus chartis ab eius domo prolatis, commonitorium repertum est, manu scriptum Hymetii, petentis ut obsecrato ritu sacrorum sollemnium numine, erga se imperatores delenirentur. Cuius extima parte quaedam invectiva legebantur in principem ut avarum et truculentum", "st": "28.1"}, {"sp": "N", "t": "Haec Valentinianus relatione iudicum doctus, asperius interpretantium facta, vigore nimio in negotium iussit inquiri. Et quia Frontinus, consiliarius ante dicti minister fuisse conceptae precationis arguebatur, concisus virgis, atque confessus, ablegatus est in exsilium ad Britannos, Amantius vero, damnatus postea rerum capitalium interiit.", "st": "28.1"}, {"sp": "N", "t": "Post hanc gestorum seriem Hymetius ad oppidum ductus Ocriculum, audiendus ab Ampelio urbi praefecto, et Maximino vicario, confestimque perdendus (ut apparebat) data sibi copia audentius imperatoris praesidium appellavit, nominisque eius perfugio tectus, servabatur incolumis.", "st": "28.1"}, {"sp": "N", "t": "Super hoc princeps consultus, senatui negotium dedit. Qui cum rem librata iustitia comperisset, eumque ad Boas, Delmatiae locum, exterminasset, aegre imperatoris iracundiam tulit, perciti vehementer, quod hominem addictum (ut ipse proposuerat) morti, clementiori sententia didicerat plexum.", "st": "28.1"}, {"sp": "N", "t": "Ob haec et huius modi multa, quae cernebantur in paucis, omnibus timeri sunt coepta. Et ne tot malis dissimulatis, paulatimque serpentibus, acervi crescerent aerumnarum, nobilitatis decreto legati mittuntur: Praetextatus ex urbi praefecto, et ex vicario Venustus, et ex consulari Minervius, oraturi ne delictis supplicia sint grandiora, neve senator quisquam, inusitato et illicito more, tormentis exponeretur.", "st": "28.1"}, {"sp": "N", "t": "Qui cum intromissi in consistorium haec referrent, negantem Valentinianum se id statuisse, et calumnias perpeti clamitantem, moderate redarguit quaestor Eupraxius, hacque libertate emendatum est crudele praeceptum, supergressum omnia diritatis exempla.", "st": "28.1"}, {"sp": "N", "t": "Circa hos dies Lollianus, primae lanuginis adulescens, Lampadi filius ex praefecto, exploratius causam Maximino spectante, convictus codicem noxiarum artium nondum per aetatem firmato consilio, descripsisse, exsulque mittendus (ut sperabatur) patris impulsu, provocavit ad principem, et iussus ad eius comitatum adduci, de fumo (ut aiunt) in flammam, traditus Phalangio (Baeticae consulari) cecidit funesti carnificis manu.", "st": "28.1"}, {"sp": "N", "t": "Super his etiam Tarracius Bassus, postea urbi praefectus, et frater eius Camenius, et Marcianus quidam et Eusaphius, omnes clarissimi, arcessiti in crimen, quod eiusdem conscii veneficiis, aurigam fovere dicebantur Auchenium, documentis etiam tum ambiguis, suffragante absoluti sunt Victorino, ut dispersus prodidit rumor, qui erat amicus Maximino iunctissimus.", "st": "28.1"}, {"sp": "N", "t": "Nec minus feminae quoque calamitatum participes fuere similium. Nam ex hoc quoque sexu, peremptae sunt originis altae complures, adulteriorum flagitiis obnoxiae, vel stuprorum. Inter quas notiores fuere Claritas et Flaviana, quarum altera cum duceretur ad mortem, indumento (quo vestita erat) abrepto, ne velamen quidem secreto membrorum sufficiens retinere permissa est. Ideoque carnifex, nefas admisisse convictus immane, vivus exustus est.", "st": "28.1"}, {"sp": "N", "t": "Paphius quin etiam et Cornelius, senatores, ambo venenorum artibus pravis se polluisse confessi, eodem pronuntiante Maximino sunt interfecti. Pari sorte etiam procurator monetae extinctus est. Sericum enim, et Asbolium supra dictos, quoniam cum hortaretur passim nominare quos vellent, adiecta religione firmarat, nullum igni vel ferro se puniri iussurum, plumbi validis ictibus interemit. Et post hoc flammis Campensem haruspicem dedit, in negotio eius nullo sacramento constrictus.", "st": "28.1"}, {"sp": "N", "t": "Opportunum est (ut arbitror) explanare nunc causam, quae ad exitium praecipitem Aginatium impulit, iam inde a priscis maioribus nobilem, ut locuta est pertinacior fama; nec enim super hoc ulla documentorum rata est fides.", "st": "28.1"}, {"sp": "N", "t": "Anhelans flatu superbo, Maximinus etiam tum praefectus annonae, nanctusque audaciae incitamenta non levia, tendebat ad usque Probi contemptum, viri summatum omnium maximi, iureque praefecturae praetorianae regentis provincias.", "st": "28.1"}, {"sp": "N", "t": "Quod Aginatius indignissime ferens, dolensque in examinandis causis Maximinum ab Olybrio sibi praelatum, cum esset ipse vicarius Romae, familiari sermone docuit Probum occulte, facile vanum hominem recalcitrantem sublimibus meritis posse opprimi, si ille id fieri censuisset.", "st": "28.1"}, {"sp": "N", "t": "Has litteras (ut quidam asseverabant), Probus ad Maximinum eruditiorem iam in sceleribus, commendatumque principi pertimescens, nullo conscio praeter baiulum, misit. Hisque recitatis, ita homo ferus exarsit, ut machinas omnes in Aginatium deinde commoveret, velut serpens vulnere ignoti cuiusdam attritus.", "st": "28.1"}, {"sp": "N", "t": "Accessit his alia potior insidiarum materia, quae eundem Aginatium obruit. Victorinum enim defunctum insimulabat, ut Maximini actus (dum supererat) venditantem, cuius ex testamento legata ipse sumpserat non aspernanda, parique petulantia Anepsiae quoque, eius uxori, lites minabatur et iurgia.", "st": "28.1"}, {"sp": "N", "t": "Quae haec metuens ut Maximini muniretur auxilio, finxit maritum in voluntate, quam condiderat nuper, argenti tria milia pondo eidem reliquisse. Qui aviditate nimia flagrans (nec enim hoc quoque vitio caruit) petit hereditatis medietatem. Verum etiam hoc (ut parum sufficienti) nequaquam contentus, aliud commentus est (ut arbitrabatur) honestum et tutum, et ne amitteret amplam sibi oblatam lucrandi uberis patrimonii, Victorini privignam, Anepsiae filiam, petit filio coniugem, idque assentiente muliere prompte firmatum est.", "st": "28.1"}, {"sp": "N", "t": "Per haec et alia simili maerore deflenda, quae decolorabant speciem urbis aeternae, grassabatur per strages multiplices fortunarum, homo cum gemitu nominandus, ultra forenses terminos semet extentans. Namque et resticulam de fenestra praetorii quadam remota, dicitur semper habuisse suspensam, cuius summitas quaedam velut damnosa colligeret, nullis quidem indiciis fulta, sed nocitura insontibus multis: et Mucianum Barbarumque apparitores aliquotiens discretim trudi iubebat, ad fallendum aptissimos.", "st": "28.1"}, {"sp": "N", "t": "Hi tamquam heiulando casus quibus se simulabant oppressos, iudicis exaggerando crudelitatem, remedium nullum aliud reis ad obtinendam vitam superesse eadem replicando saepe asseverabant, ni criminibus magnis petissent nobiles viros, quibus ad sui societatem annexis facile eos absolvi posse firmabant.", "st": "28.1"}, {"sp": "N", "t": "Ob quae implacabilitate ultra apposita iam pergente, manus vinculis sunt artatae complurium, ortuque nobiles inculti videbantur et anxii. Nec eorum culpari quisquam debuit, cum salutantes humum paene curvatis contingentibus membris, persaepe clamantem audirent, spiritus ferini latronem, nullum se invito reperiri posse insontem.", "st": "28.1"}, {"sp": "N", "t": "Quae verba effectui propere iuncta, terruissent profecto Numae Pompilii similis, et Catonem. Prorsus enim sic agebatur, ut nec in alienis malis quorumdam exarescerent lacrimae: quod in variis et confragosis actibus vitae plerumque contingit.", "st": "28.1"}, {"sp": "N", "t": "A iure tamen iustitiaque crebro discedens, ferreus cognitor erat uno quasi praecipuo tolerabilis. Interdum enim exoratus parcebat aliquibus, quod prope vitium esse, in hoc loco legitur apud Tullium: “Nam si implacabiles iracundiae sunt, summa est acerbitas: sin autem exorabiles, summa levitas; quae tamen (ut in malis) acerbitati anteponenda est.”", "st": "28.1"}, {"sp": "N", "t": "Post haec praegresso Leone, acceptoque successore, ad principis comitatum Maximinus accitus, auctusque praefectura praetoriana, nihilo lenior fuit, etiam longius nocens, ut basilisci serpentes.", "st": "28.1"}, {"sp": "N", "t": "In id tempus aut non multo prius, scopae florere sunt visae, quibus nobilitatis curia mundabatur, idque portendebat, extollendos quosdam despicatissimae sortis ad gradus potestatum excelsos.", "st": "28.1"}, {"sp": "N", "t": "Et quamlibet tempestivum est ad ordinem redire coeptorum, tamen nihil impedituri temporum cursus, immorabimur paucis, quae per iniquitatem curantium vicariam praefecturam in urbe, contra quam oportuerat, gesta sunt, quia ad nutum Maximini et voluntatem eisdem ministris velut apparitoribus gerebantur.", "st": "28.1"}, {"sp": "N", "t": "Post hunc venit Ursicinus ad mitiora propensior, qui quoniam cautus esse voluit et civilis, rettulerat Esaiam cum aliis, ob commissum adulterium in Rufinam detentis, Marcellum maritum eius ex agente in rebus reum imminutae maiestatis deferre conari: ideoque ut cunctator contemptus, et ad haec fortiter exsequenda parum conveniens, e vicaria potestate discessit.", "st": "28.1"}, {"sp": "N", "t": "Huic successit Hemonensis Simplicius, Maximini consiliarius ex grammatico, per administrationem nec erectus nec tumidus sed obliquo aspectu terribilis, qui compositis ad modestiam verbis acerba meditabatur in multos. Et primo Rufinam, cum universis auctoribus adulterii commissi vel consciis, interfecit, super quibus Ursicinum rettulisse praediximus, alios deinde complures nullo noxiorum discrimine vel insontium.", "st": "28.1"}, {"sp": "N", "t": "Cruento enim certamine cum Maximino velut antepilano suo contendens, superare eum in succidendis familiarum nobilium nervis studebat, Busirim veterem et Antaeum imitatus et Phalarim, ut taurus ei solus deesse videretur Agrigentinus.", "st": "28.1"}, {"sp": "N", "t": "His in hunc modum ac talibus actis, Hesychia quaedam matrona, ob intentatum crimen in domo apparitoris, cui custodienda est tradita, multa pertimescens et saeva, fulcro plumeo vultu contracto incubuit, et animam occluso narium spiramento effudit.", "st": "28.1"}, {"sp": "N", "t": "Adiunctum est his aliud haut mitius malum. Eumenius enim et Abienus, ambo ex coetu amplissimo, infamati sub Maximino, in Fausianam feminam non obscuram, post Victorini obitum, quo iuvante vixere securius, Simplicii adventu perterrefacti, non secus volentis maligna cum minis, ad secreta receptacula se contulerunt.", "st": "28.1"}, {"sp": "N", "t": "Sed Fausiana damnata, inter reos recepti, vocatique edictis, semet abstrusius amendarunt: quorum Abienus apud Anepsiam diu delitescebat. Sed ut solent insperati casus aggravare miserabilis clades, Apaudulus nomine, servus Anepsiae, verberatae coniugis dolore perculsus, negotium ad Simplicium detulit, nocte progressus, missique apparitores, indicatos e latebris abstraxerunt.", "st": "28.1"}, {"sp": "N", "t": "Et Abienus quidem, exaggerate crimine stupri, quod intulisse dicebatur Anepsiae, morte multatus est. Mulier vero ut continendae vitae spem firmam dilato posset habere supplicio, appetitam se nefariis artibus, vim in domo Aginati perpessam, adseveravit.", "st": "28.1"}, {"sp": "N", "t": "Haec (ut gesta sunt) malignius ad principem Simplicius rettulit, agensque ibi Maximinus infestus, ob causam quam supra docuimus, Aginatio, simultate una cum potestate in maius accensa, oravit impense ut rescriberetur eum occidi: et impetravit facile male sanus incitator et potens.", "st": "28.1"}, {"sp": "N", "t": "Metuensque gravioris invidiae pondus, ne pronuntiante Simplicio, et consiliario suo et amico, periret homo patriciae stirpis, retinuit apud se paulisper imperiale praeceptum, haerens et ambigens quemnam potissimum exsecutorem atrocis rei fidum inveniret et efficacem.", "st": "28.1"}, {"sp": "N", "t": "Tandemque, ut solent pares facile congregari cum paribus, Doryphorianus quidam repertus est Gallus, audax ad usque insaniam, cui hanc operam implere brevi pollicito, deferri providit vicariam, et commonitorium cum Augusti litteris tradidit, instruens hominem saevum quidem sed rudem, qua celeritate Aginatium sine ullo deleret obstaculo, dilatione qualibet inventa forsitan evasurum.", "st": "28.1"}, {"sp": "N", "t": "Festinavit (ut mandatum est) Doryphorianus magnis itineribus Romam, et inter administrandi initia, magna quaeritabat industria, qua vi senatorem perspicui generis interficeret, iuvantibus nullis. Cognitoque eum iam pridem repertum, in villa propria custodiri, ipse tamquam capita sontium Aginatium, pariterque Anepsiam horrore medio tenebrarum audire disposuit, quo tempore hebetari solent obstrictae terroribus mentes: ut inter innumera multa, Aiax quoque Homericus docet, optans perire potius luce, quam pati formidinis augmenta nocturnae.", "st": "28.1"}, {"sp": "N", "t": "Et quoniam iudex, quin immo praedo nefandus, ad id solum quod promisit intentus, cuncta extollebat in maius, iusso sub quaestione Aginatio statui, agmina fecit introire carnificum, catenisque sonantibus triste, mancipia squalore diuturno marcentia, in domini caput ad usque ultimum lacerabat exitium, quod in stupri quaestione fieri vetuere clementissimae leges.", "st": "28.1"}, {"sp": "N", "t": "Denique cum iam contigua morti tormenta ancillae voces expressissent obliquas, indicii fide parum plene discussa, Aginatius ad supplicium duci pronuntiatur abrupte, nec auditus cum magnis clamoribus appellaret nomina principum, sublimis raptus occiditur, pari sententia Anepsia interfecta. Haec agitante (cum adesset) perque emissarios (cum procul ageret) Maximino, funera urbs deploravit aeterna.", "st": "28.1"}, {"sp": "N", "t": "Sed vigilarunt ultimae dirae caesorum. Namque ut postea tempestive dicetur, et idem Maximinus sub Gratiano intoleranter se efferens, damnatorio iugulatus est ferro, et Simplicius in Illyrico truncatus, et Doryphorianum pronuntiatum capitis reum, trusumque in carcerem Tullianum, matris consilio, princeps exinde rapuit, reversumque ad lares per cruciatus oppressit immensos. Verum unde huc fleximus revertamur. Is urbanarum rerum status, ut ita dixerim, fuit.", "st": "28.1"}, {"sp": "N", "t": "At Valentinianus magna animo concipiens et utilia, Rhenum omnem a Raetiarum exordio, ad usque fretalem Oceanum, magnis molibus communiebat, castra extollens altius et castella, turresque assiduas per habiles locos et opportunos, qua Galliarum extenditur longitudo: non numquam etiam ultra flumen aedificiis positis, subradens barbaros fines.", "st": "28.2"}, {"sp": "N", "t": "Denique cum reputaret munimentum celsum et tutum, quod ipse a primis fundarat auspiciis, praeterlabente Nicro nomine fluvio, paulatim subverti posse undarum pulsu immani, meatum ipsum aliorsum vertere cogitavit, et quaesitis artificibus peritis aquariae rei, copiosaque militis manu arduum est opus aggressus.", "st": "28.2"}, {"sp": "N", "t": "Per multos enim dies compaginatae formulae e roboribus, coniectaeque in alveum, fixis refixisque aliquotiens prope ingentibus stilis, fluctibus erectis confundebantur, avulsaeque vi gurgitis interibant.", "st": "28.2"}, {"sp": "N", "t": "Vicit tamen imperatoris vehementior cura, et morigeri militis labor, mento tenus (dum operaretur) saepe demersi: tandem non sine quorundam discrimine, castra praesidiaria, inquietudini ringentis amnis exempta, nunc valida sunt.", "st": "28.2"}, {"sp": "N", "t": "His ac talibus laetus exsultansque exin, quae pro anni et temporis statu utilia conducerent rei publicae studium habuit, ut officio principis congruebat. Ratusque aptissimum ad id quod deliberabat implendum, trans Rhenum in monte Piri (qui barbaricus locus est) munimentum exstruere disposuit raptim. Utque celeritas effectum negotii faceret tutum, per Syagrium tunc notarium, postea praefectum et consulem, Aratorem monuit ducem, ut dum undique altum esset silentium, id arripere conaretur.", "st": "28.2"}, {"sp": "N", "t": "Transiit cum notario dux (ut iussum est) statim, fodereque per militem quem duxit fundamenta exorsus, Hermogenen susceperat successorem, eodemque puncto quidam optimates Alamanni venere, obsidum patres, quos lege foederis mansuraeque diutius pacis haut aspernanda pignora tenebamus.", "st": "28.2"}, {"sp": "N", "t": "Qui flexis poplitibus supplicabant, ne Romani securitatis improvidi, quorum fortunam sempiterna fides caelo contiguam fecit, pravo deciperentur errore, pactisque calcatis, rem adorerentur indignam.", "st": "28.2"}, {"sp": "N", "t": "Verum haec et similia loquentes in cassum, cum nec audirentur, nec quietum aliquid vel mite referri sentirent, filiorum flentes exitium discesserunt, eisdemque aegre digressis, ex abdito collis propinqui sinu, barbaricus prosiluit globus, optimatibus tum danda responsa (ut intellegi dabatur) opperiens: et adortus milites seminudos, humum etiam tum gestantes, expeditis agiliter gladiis, obtruncabant, inter quos etiam duces ambo sunt caesi.", "st": "28.2"}, {"sp": "N", "t": "Nec indicaturus gesta superfuit quisquam, praeter Syagrium, qui deletis omnibus ad comitatum reversus, irati sententia principis sacramento exutus, abiit ad lares, id commeruisse saevo iudicatus arbitrio, quod evaserit solus.", "st": "28.2"}, {"sp": "N", "t": "Haec inter per Gallias latrociniorum rabies saeva scatebat in perniciem multorum, observans celebres vias, fundensque indistanter quidquid inciderat fructuosum. Denique praeter complures alios quos absumpserunt insidiae tales, Constantianus tribunus stabuli impetu est clandestino exceptus, moxque interfectus, Valentiniani affinis, Cerealis et Iustinae germanus.", "st": "28.2"}, {"sp": "N", "t": "At procul, tamquam horum similia cientibus furiis, per omne latus Maratocupreni grassatores acerrimi vagabantur, vici huius nominis incolae, in Syria prope Apamiam positi, nimium quantum numero et exquisitis fallaciis abundantes, ideoque formidati, quod mercatorum militumque honoratorum specie sine strepitu ullo diffusi, opimas domos et villas et oppida pervadebant.", "st": "28.2"}, {"sp": "N", "t": "Nec quisquam adventum eorum cavere poterat inopinum, non destinata, sed varia petentium et longinqua, et quocumque ventus duxerat, inrumpentium: quam ob causam prae ceteris hostibus Saxones timentur ut repentini. Et quamlibet coniurati multorum opes attriverint, oestroque concepti furoris exagitati, strages edidere luctificas, sanguinis nihilo minus avidi quam praedarum, tamen ne per minutias gesta narrando, rectum aliquatenus operis impediam cursum, id unum sufficiet, eorum exitiale poni commentum.", "st": "28.2"}, {"sp": "N", "t": "Quaesitus in unum impiorum hominum globus, imitatus rationalis officium, ipsumque iudicem, vespertinis tenebris lugubre clamante praecone, civitatem ingressi, ambitiosam domum cuiusdam primatis, ut proscripti iussique interfici, cum gladiis obsederunt, raptaque suppellectili pretiosa, quia subito perculsi familiares, hebetatis sensibus non defenderant dominum, caesis pluribus ante revolutam lucem gressu discessere veloci.", "st": "28.2"}, {"sp": "N", "t": "Verum cum exuviis referti multorum, rapiendi dulcedinem praetermitterent, interceptam, imperiali motu, oppressi interiere omnes ad unum, eorumque suboles parva etiam tum, ne ad parentum exempla subcresceret, pari sorte deleta est, et lares versi, quos ambitiose luctuosis aliorum dispendiis construxerunt. Et haec quidem textu processere narrato.", "st": "28.2"}, {"sp": "N", "t": "Theodosius vero dux nominis incluti, animi vigore collecto, ab Augusta profectus, quam veteres appellavere Lundinium, cum milite industria comparato sollerti, versis turbatisque Britannorum fortunis opem maximam tulit, opportuna ubique ad insidiandum barbaris praeveniens loca, nihilque gregariis imperans, cuius non ipse primitias alacri capesseret mente.", "st": "28.3"}, {"sp": "N", "t": "Hocque genere cum strenui militis munia et praeclari ducis curas expleret, fusis variis gentibus et fugatis, quas insolentia nutriente securitate, aggredi Romanas res inflammabat, in integrum restituit civitates et castra, multiplicibus quidem damnis afflicta, sed ad quietem temporis longi fundata.", "st": "28.3"}, {"sp": "N", "t": "Evenerat autem eodem haec agente facinus dirum, erupturum in periculum grave, ni inter ipsa conatus principia fuisset exstinctum.", "st": "28.3"}, {"sp": "N", "t": "Valentinus quidam natus in Valeria Pannoniae, superbi spiritus homo, Maximini illius exitialis vicarii, postea praefecti coniugis frater, ob grave crimen actus in Britannias exsul, quietis impatiens ut malefica bestia, ad res perniciosas consurgebat et novas, in Theodosium tumore quodam, quem solum resistere posse nefandis cogitationibus advertebat.", "st": "28.3"}, {"sp": "N", "t": "Multa tamen clam palamque circumspiciens, crescente flatu cupiditatis immensae, exsules sollicitabat et milites, pro temporis captu ausorum illecebrosas pollicendo mercedes.", "st": "28.3"}, {"sp": "N", "t": "Iamque propinquante temptatorum effectu, doctus haec unde convenerat, dux alacrior ad audendum, et corde celso ad vindictam compertorum erectus, Valentinum quidem cum paucis arta ei societate iunctissimis, letali poena plectendos, Dulcitio dediderat duci: militari scientia vero, qua superabat praesentes, futura coniciens, de coniuratis quaestiones agitari prohibuit, ne formidine sparsa per multos, reviviscerent provinciarum turbines consopiti.", "st": "28.3"}, {"sp": "N", "t": "Hinc ad corrigenda plura conversus et necessaria, periculo penitus dempto, cum aperte constaret, nulla eius propitiam deseruisse fortunam, instaurabat urbes et praesidiaria (ut diximus) castra, limitesque vigiliis tuebatur et praetenturis, recuperatamque provinciam, quae in dicionem concesserat hostium, ita reddiderat statui pristino, ut eodem referente et rectorem haberet legitimum, et Valentia deinde vocaretur arbitrio principis, velut ovantis gaudio nuntio inaestimabili cognito.", "st": "28.3"}, {"sp": "N", "t": "Inter haec tam praecipua, Arcanos genus hominum a veteribus institutum, super quibus aliqua in actibus Constantis rettulimus, paulatim prolapsos in vitia a stationibus suis removit: aperte convictos, acceptarum promissarumque magnitudine praedarum allectos, quae apud nos agebantur, aliquotiens barbaris prodidisse. Id enim illis erat officium, ut ultro citroque, per longa spatia discurrentes, vicinarum gentium strepitus nostris ducibus intimarent.", "st": "28.3"}, {"sp": "N", "t": "Ita spectatissime ante dictis rebus aliisque administratis similibus, ad comitatum accitus, tripudiantesque relinquens provincias, ut Furius Camillus vel Cursor Papirius, victoriis crebris et salutaribus erat insignis. Et favore omnium ad usque fretum deductus, leni vento transgressus, venit ad commilitium principis, cumque gaudio susceptus et laudibus, in locum Iovini ut lenti successit, qui equorum copias tuebatur.", "st": "28.3"}, {"sp": "N", "t": "Diu multumque a negotiis discussus urbanis, adigente cumulo foris gestorum, ad ea strictim exsequenda regrediar, exorsus ab Olybrii praefectura, tranquilla nimis et leni, qui numquam ab humanitatis statu deiectus, sollicitus erat et anxius, nequid usquam factum eius asperum inveniretur aut dictum, calumniarum acerrimus insectator, fisci lucra unde poterat circumcidens, iustorum iniustorumque distinctor, et arbiter plenus, in subiectos admodum temperatus.", "st": "28.4"}, {"sp": "N", "t": "Sed obnubilabat haec omnia vitium, parum quidem nocens rei communi, sed in alto iudice maculosum, quod citeriorem vitam paene omnem vergentem in luxum, per argumenta scaenica amoresque peregerat, nec vetitos nec incestos.", "st": "28.4"}, {"sp": "N", "t": "Post hunc urbem rexit Ampelius, cupidus ipse quoque voluptatum, Antiochiae genitus, ex magistro officiorum, ad proconsulatum geminum, indeque multo postea ad praefecturae culmen evectus, lectus alia et ad populi favorem adipiscendum aptissimus, non numquam tamen rigidus, atque utinam in proposito perseverans. Correxisset enim ex parte, licet exigua, irritamenta gulae et ganeas taetras, ni flexus in molliora, amisisset gloriam diu victuram.", "st": "28.4"}, {"sp": "N", "t": "Namque statuerat, ne taberna vinaria ante horam quartam aperiretur, neve aquam vulgarium calefaceret quisquam, vel usque ad praestitutum diei spatium lixae coctam proponerent carnem, vel honestus quidam mandens videretur in publico.", "st": "28.4"}, {"sp": "N", "t": "Quae probra aliaque his maiora, dissimulatione iugi neglecta, ita effrenatius exarserunt, ut nec Epimenides ille Cretensis, si fabularum ritu ab inferis excitatus redisset ad nostra, solus purgare sufficeret Romam: tanta plerosque labes insanabilium flagitiorum oppressit.", "st": "28.4"}, {"sp": "N", "t": "Et primo nobilitatis, ut aliquotiens pro locorum copia fecimus, dein plebis digeremus errata, incidentia veloci constringentes excessu.", "st": "28.4"}, {"sp": "N", "t": "Praenominum claritudine conspicui quidam (ut putant) in immensum semet extollunt, cum Reburri et Elabunii et Pagonii Gereonesque appellentur, ac Dalii cum Tarraciis et Perrasiis, aliisque ita decens sonantibus originum insignibus multis.", "st": "28.4"}, {"sp": "N", "t": "Non nullos fulgentes sericis indumentis, ut ducendos ad mortem, vel ut sine diritate ominis loquamur, praegresso exercitu, arma cogentes, manipulatim concitato fragore sequitur multitudo servorum.", "st": "28.4"}, {"sp": "N", "t": "Tales ubi comitantibus singulos quinquaginta ministris, tholos introierint balnearum, “Ubi ubi sunt nostri?” minaciter clamant: si apparuisse subito ignotam compererint meretricem, aut oppidanae quondam prostibulum plebis, vel meritorii corporis veterem lupam, certatim concurrunt, palpantesque advenam, deformitate magna blanditiarum ita extollunt, ut Samiramim Parthi vel Cleopatras Aegyptus aut Artemisiam Cares vel Zenobiam Palmyreni. Et haec admittunt hi quorum apud maiores censoria nota senator afflictus est, ausus dum adhuc non deceret, praesente communi filia coniugem osculari.", "st": "28.4"}, {"sp": "N", "t": "Ex his quidam cum salutari pectoribus oppositis coeperint, osculanda capita in modum taurorum minacium obliquantes, adulatoribus offerunt genua suavianda, vel manus, id illis sufficere ad beate vivendum existimantes, et abundare omni cultu humanitatis peregrinum putantes, cuius forte etiam gratia sunt obligati, interrogatum, quibus thermis utatur aut aquis, aut ad quam successerit domum.", "st": "28.4"}, {"sp": "N", "t": "Et cum ita graves sint et cultores virtutum, (ut putant) si venturos undelibet equos aut aurigas quendam didicerint nuntiasse, ita velociter imminent eidem et percunctantur, ut Tyndaridas fratres eorum suspexere maiores, cum priscis illis victoriis indicatis gaudio cuncta complessent.", "st": "28.4"}, {"sp": "N", "t": "Horum domus otiosi quidam garruli frequentant, variis assentandi figmentis, ad singula ulterioris fortunae verba plaudentes, parasitorum in comoediis facetias affectando. Ut enim illi sufflant milites gloriosos, obsidiones et pugnas contra milia hostium, eisdem ut heroicis aemulis assignantes, ita hi quoque columnarum constructiones, alta fronte suspensas mirando, atque parietes lapidum circumspectis coloribus nitidos, ultra mortalitatem nobiles viros extollunt.", "st": "28.4"}, {"sp": "N", "t": "Poscuntur etiam in conviviis aliquotiens trutinae, ut appositi pisces et volucres ponderentur, et glires, quorum magnitudo saepius replicata, non sine taedio praesentium, ut antehac inusitata, laudatur assidue, maxime cum haec eadem numerantes, notarii triginta prope assistant, cum thecis et pugillaribus tabulis, ut deesse solus magister ludi litterarii videretur.", "st": "28.4"}, {"sp": "N", "t": "Quidam detestantes ut venena doctrinas, Iuvenalem et Marium Maximum curatiore studio legunt, nulla volumina praeter haec in profundo otio contrectantes, quam ob causam non iudicioli est nostri.", "st": "28.4"}, {"sp": "N", "t": "Cum multa et varia pro amplitudine gloriarum et generum lectitare deberent, audientes destinatum poenae Socratem, coniectumque in carcerem, rogasse quendam scite lyrici carmen Stesichori modulantem, ut doceretur id agere, dum liceret: interroganteque musico, quid ei poterit hoc prodesse, morituro postridie, respondisse, “Ut aliquid sciens amplius e vita discedam.”", "st": "28.4"}, {"sp": "N", "t": "Ita autem pauci sunt inter eos severi vindices delictorum ut, si aquam calidam tardius attulerit servus, trecentis affligi verberibus iubeatur: si hominem sponte occiderit propria, instantibus plurimis, ut damnetur ut reus, dominus hactenus exclamabit: “Quid faciat male factis famosus et nequam? et siquid aliud eius modi deinceps ausus fuerit, corrigetur.”", "st": "28.4"}, {"sp": "N", "t": "Civilitatis autem hoc apud eos est nunc summum, quod expedit peregrino fratrem interficere cuiuslibet, quam cum rogatus sit ad convivium excusare: defectum enim patrimonii se opimi perpeti senator existimat, si is defuerit quem aliquotiens libratis sententiis, invitaverit semel.", "st": "28.4"}, {"sp": "N", "t": "Pars eorum si agros visuri processerunt longius, aut alienis laboribus venaturi, Alexandri Magni itinera se putant aequiperasse, vel Caesaris: aut si a lacu Averni lembis invecti sunt pictis Puteolos, velleri certamen, maxime cum id vaporato audeant tempore. Ubi si inter aurata flabella laciniis sericis insederint muscae, vel per foramen umbraculi pensilis radiolus irruperit solis, queruntur quod non sunt apud Cimmerios nati.", "st": "28.4"}, {"sp": "N", "t": "Dein cum a Silvani lavacro vel Mamaeae aquis ventitant sospitalibus, ut quisquam eorum egressus, tenuissimis se terserit linteis, solutis pressoriis, vestes luce nitentes ambigua diligenter explorat, quae una portantur sufficientes ad induendos homines undecim: tandemque electis aliquot involutus, receptis anulis quos (ne violentur humoribus) famulo tradidit, digitis ut metatis abit.", "st": "28.4"}, {"sp": "N", "t": "Enim vero siqui vetus in commilitio principis recens digressus fuerit in otium ut aevi provecti, ille tali praesente coetu … mirionum … cantilenae praesul existimatur: ceteri taciturni audiunt dicta … solus pater familias textui narrans aliena, et placentia referens, et erudite pleraque fallendo.", "st": "28.4"}, {"sp": "N", "t": "Quidam ex his (licet rari) aleatorum vocabulum declinantes, ideoque se cupientes appellari potius tesserarios: inter quos tantum differt, quantum inter fures atque latrones. Hoc tamen fatendum est, quod cum omnes amicitiae Romae tepescant, aleariae solae, quasi gloriosis quaesitae sudoribus, sociales sunt et affectus nimii firmitate plena conexae: unde quidam ex his gregibus inveniuntur ita concordes, ut Quintilios esse existimes fratres. Ideoque videre licet ignobilem artis tesserariae callentem arcana, ut Catonem Porcium ob repulsam praeturae, nec suspectam antea nec speratam, incedere gravitate composita maestiorem, quod ei in maiore convivio vel consessu proconsularis quidam est antelatus.", "st": "28.4"}, {"sp": "N", "t": "Subsident aliqui copiosos homines senes aut iuvenes, orbos vel caelibes, aut etiam uxores habentes seu liberos (nec enim hoc titulo discrimen aliquod observatur), ad voluntates condendas allicientes eos praestigiis miris: qui cum, supremis iudiciis ordinatis, quaedam reliquerint his quibus morem gerendo testati sunt, ilico pereunt, ut id impleri sorte fatorum operante nec putes, nec facile possit aegritudo testari nec funus comitatur his quisquam.", "st": "28.4"}, {"sp": "N", "t": "Alius cum dignitate (licet mediocri), cervice tumida gradiens, notos antea obliquato contuetur aspectu, ut post captas Syracusas existimes reverti Marcellum.", "st": "28.4"}, {"sp": "N", "t": "Multi apud eos negantes esse superas potestates in caelo, nec in publicum prodeunt nec prandent nec lavari arbitrantur se cautius posse, antequam ephemeride scrupulose sciscitata didicerint, ubi sit verbi gratia signum Mercurii, vel quotam Cancri sideris partem polum discurrens obtineat luna.", "st": "28.4"}, {"sp": "N", "t": "Alius si creditorem suum flagitare molestius adverterit debitum, ad aurigam confugit, audentem omnia praelicenter, eumque ut veneficum curat urgeri: unde non nisi reddita cautione, dispendioque afflictus gravi discedit. Et additur huic, debitorem voluntarium includit ut proprium, nec ante eius professionem absolvit.", "st": "28.4"}, {"sp": "N", "t": "Parte alia uxor, ut proverbium loquitur vetus, eamdem incudem diu noctuque tundendo, maritum testari compellit, hocque idem ut faciat uxor, urget maritus instanter: et periti iuris altrinsecus assciscuntur, unus in cubiculo alter eius aemulus in triclinio, repugnantia tractaturi: eisdemque subseruntur genitalium fatorum interpretes controversi, hinc praefecturas profusius largientes, et sepulturas divitum matronarum; inde ad exsequias virorum iam adventantes necessaria parari oportere iubentes: et testatur ancilla suapte natura pallidior, spiritu pridie consumpto defuncta … um Roma atque, ut Tullius ait: “Nec in rebus humanis quicquam bonum norunt nisi quod fructuosum sit: amicos tamquam pecudes eos potissimum diligunt, ex quibus se sperant maximum fructum esse capturos.”", "st": "28.4"}, {"sp": "N", "t": "Cumque mutuum illi quid petunt, soccatos ut Miconas videbis et Lachetas: cum adiguntur ut reddant, ita cothurnatos et turgidos, ut Heraclidas illos Cresphontem et Temenum putes. Hactenus de senatu.", "st": "28.4"}, {"sp": "N", "t": "Nunc ad otiosam plebem veniamus et desidem. In qua nitent, ut nominibus cultis, quidam calceorum expertes, ut Messores Statarii Semicupae et Serapini, et Cicimbricus cum Gluturino et Trulla, et Lucanicus cum Pordaca et Salsula, similesque innumeri.", "st": "28.4"}, {"sp": "N", "t": "Hi omne quod vivunt, vino et tesseris impendunt et lustris, et voluptatibus et spectaculis: eisque templum et habitaculum et contio et cupitorum spes omnis Circus est maximus: et videre licet per fora et compita et plateas et conventicula, circulos multos collectos in se controversis iurgiis ferri, aliis aliud (ut fit) defendentibus.", "st": "28.4"}, {"sp": "N", "t": "Inter quos hi qui ad satietatem vixerunt, potiores auctoritate longaeva, per canos et rugas clamitant saepe, rem publicam stare non posse, si futura concertatione, quem quisque vindicat, carceribus non exsiluerit princeps, et inominalibus equis, parum cohaerenter circumflexerit metam.", "st": "28.4"}, {"sp": "N", "t": "Et ubi neglegentiae tanta est caries, exoptato die equestrium ludorum illucescente, nondum solis puro iubare, effusius omnes festinant praecipites, ut velocitate currus ipsos anteeant certaturos: super quorum eventu discissi votorum studiis anxii, plurimi agunt pervigiles noctes.", "st": "28.4"}, {"sp": "N", "t": "Unde si ad theatralem ventum fuerit vilitatem, artifices scaenarii per sibilos exploduntur, siqui sibi aere humiliorem non conciliaverit plebem. Qui si defuerit strepitus, ad imitationem Tauricae gentis, peregrinos vociferantur pelli debere, quorum subsidiis semper nisi sunt ac steterunt, et taetris vocibus et absurdis; quae longe abhorrent a studiis et voluntate veteris illius plebis, cuius multa facete dicta memoria loquitur et venuste.", "st": "28.4"}, {"sp": "N", "t": "Id enim nunc repertum est pro sonitu laudum impensiore, per applicatos homines ad plaudendum, ut in omni spectaculo exodiario venatori aurigae et histrionum generi omni, et iudicibus celsis, itidemque minoribus, nec non etiam matronis, clametur assidue: “Per te illi discant”; quid autem debeat disci, nemo sufficit explanare.", "st": "28.4"}, {"sp": "N", "t": "In his plerique distentioribus saginis addicti, praeeunte nidoris indagine, acutisque vocibus feminarum, a galliciniis ipsis, in modum pavonum ieiunitate clangentium, humum summis pedum unguibus contingentes, aulis assistunt, digitos praerodentes, dum patinae defervescunt: alii nauseam horridae carnis, dum excoquitur, intentius despectantes, ut discissarum pecudum exta rimari cum anatomicis Democritum putes, docentem quibus modis posteritas mederi doloribus possit internis.", "st": "28.4"}, {"sp": "N", "t": "Sit satis interim haec digessisse super rebus urbanis. Nunc redeamus ad cetera, quae per provincias agitavere multiplices casus.", "st": "28.4"}, {"sp": "N", "t": "Erupit Augustis ter consulibus Saxonum multitudo, et Oceani difficultatibus permeatis, Romanum limitem gradu petebat intento, saepe nostrorum funeribus pasta: cuius eruptionis primae procellam Nannenus sustinuit comes, regionibus eisdem appositus, dux diuturno bellorum labore compertus.", "st": "28.5"}, {"sp": "N", "t": "Sed tunc ad mortem destinatae plebi congressus, cum milites quosdam ruisse, et se vulneratum imparem fore certaminibus adverteret crebris, docto imperatore quid agi deberet, id est adeptus, ut peditum magister Severus opitulatum rebus dubiis adveniret.", "st": "28.5"}, {"sp": "N", "t": "Qui ducens militem rei sufficientem, cum venisset ad loca, discriminatis ordinibus, superbos barbaros ante colluctationem adeo terruit et turbavit, ut nec controversas opponerent manus, sed signorum aquilarumque fulgore praestricti, venialem poscerent pacem.", "st": "28.5"}, {"sp": "N", "t": "Diuque variatis consiliis, cum id rei publicae conducere videretur, pactis indutiis, et datis ex condicione proposita iuvenibus multis, habilibus ad militiam, discedere permissi sunt Saxones, sine impedimento, unde venerant, reversuri.", "st": "28.5"}, {"sp": "N", "t": "Quibus omni iam formidine vacuis, reditumque parantibus, occulte pedites missi, insidias in abdita quadam valle struxerunt, unde praetereuntes aggredi negotio poterant levi. Sed longe secus accidit quam sperabatur.", "st": "28.5"}, {"sp": "N", "t": "Sonitu enim adventantium perciti, exsiluere quidam intempestive, visique subito, dum se firmare festinant, ululantibus lugubre barbaris, vertuntur in pedes. Stetere tamen mox conglobati, extremaque sorte vires (licet non integras) suggerente, confligere cogebantur, multaque caede perculsi, concidissent nullo relicto, ni cataphractorum equitum cuneus, ad inferendum periculum transeuntibus barbaris, ex alio latere prope divortium itineris, pari modo locatus, clamore percitus tristi, agiliter subvenisset.", "st": "28.5"}, {"sp": "N", "t": "Exin concursum infestius, firmatisque pectoribus, hinc inde incumbentes Romani clausos hostes eductis gladiis obtruncabant: nec quisquam eorum genitales revisere potuit lares, ne uno quidem caedibus concorporalium superesse permisso. Ac licet iustus quidam arbiter rerum, factum incusabit perfidum et deforme, pensato tamen negotio, non feret indigne manum latronum exitialem tandem copia data consumptam.", "st": "28.5"}, {"sp": "N", "t": "Post haec ita prospere consummata, Valentinianus versando sententias multiformes, anxia sollicitudine stringebatur, reputans multa et circumspiciens, quibus commentis Alamannorum et Macriani regis frangeret fastus, sine fine vel modo rem Romanam irrequietis motibus confundentis.", "st": "28.5"}, {"sp": "N", "t": "Immanis enim natio iam inde ab incunabulis primis varietate casuum imminuta, ita saepius adulescit, ut fuisse longis saeculis aestimetur intacta. Seditque consilia alia post alia imperatori probanti, Burgundios in eorum excitari perniciem, bellicosos et pubis immensae viribus affluentes, ideoque metuendos finitimis universis.", "st": "28.5"}, {"sp": "N", "t": "Scribebatque frequenter ad eorum reges per taciturnos quosdam et fidos, ut eisdem tempore praestituto supervenirent, pollicitus ipse quoque, transito cum Romanis agminibus Rheno, occurrere pavidis, pondus armorum vitantibus insperatum.", "st": "28.5"}, {"sp": "N", "t": "Gratanter ratione gemina principis acceptae sunt litterae: prima quod iam inde a temporibus priscis subolem se esse Romanam Burgundii sciunt, dein quod salinarum finiumque causa Alamannis saepe iurgabant. Et catervas misere lectissimas, quae antequam milites congregarentur in unum, ad usque ripas Rheni progressae, imperatore ad struenda munimenta districto, terrori nostris fuere vel maximo.", "st": "28.5"}, {"sp": "N", "t": "Igitur paulisper morati, cum neque Valentinianus (ut spoponderat) die praedicto venisset, nec promissorum aliquid adverterent factum, ad comitatum misere legatos, poscentes adminicula sibi dari, redituris ad sua, ne nuda hostibus exponerent terga.", "st": "28.5"}, {"sp": "N", "t": "Quod ubi negari per ambages sentirent et moras, maesti exinde discesserunt et indignati. Hocque comperto, reges ut ludibrio habiti saevientes, captivis omnibus interfectis, genitales repetunt terras.", "st": "28.5"}, {"sp": "N", "t": "Apud hos generali nomine rex appellatur Hendinos, et ritu veteri potestate deposita removetur, si sub eo fortuna titubaverit belli, vel segetum copiam negaverit terra, ut solent Aegyptii casus eius modi suis assignare rectoribus. Nam sacerdos apud Burgundios omnium maximus vocatur Sinistus, et est perpetuus, obnoxius discriminibus nullis, ut reges.", "st": "28.5"}, {"sp": "N", "t": "Per hanc occasionem impendio tempestivam, Alamannos gentis ante dictae metu dispersos, aggressus per Raetias Theodosius (ea tempestate magister equitum) pluribus caesis, quoscumque cepit ad Italiam iussu principis misit, ubi fertilibus pagis acceptis, iam tributarii circumcolunt Padum.", "st": "28.5"}, {"sp": "N", "t": "Hinc (tamquam in orbem migrantes alium) ad Tripoleos Africanae provinciae veniamus aerumnas, quas (ut arbitror) Iustitia quoque ipsa deflevit, quae unde instar exarsere flammarum, textus aperiet absolutus.", "st": "28.6"}, {"sp": "N", "t": "Austoriani his contermini partibus barbari, in discursus semper expediti veloces, vivereque assueti rapinis et caedibus, paulisper pacati, ad genuinos turbines revoluti sunt, hanc causam praetendentes ut seriam.", "st": "28.6"}, {"sp": "N", "t": "Stachao quidam nomine popularis eorum, ut in otio nostra peragrando licentius agebat quaedam vetita legibus, inter quae illud potius eminebat, quod provinciam omni fallaciarum via prodere conabatur, ut indicia docuere verissima: quocirca supplicio flammarum absumptus est.", "st": "28.6"}, {"sp": "N", "t": "Huius necem ulcisci, ut propinqui damnatique iniuste causantes, ferarum similes rabie concitarum, exsiluere sedibus suis, Ioviano etiam tum imperante, veritique prope Leptim accedere, civitatem muris et populo validam, suburbano eius uberrimo insedere per triduum, mactatisque agrestibus, quos inopinus hebetaverat pavor, vel confugere coegerat ad speluncas, incensa suppellectili multa, quae vehi non poterat, referti rapinis reverterunt ingentibus, trahentes captivum Silvam quoque casu cum caritatibus in agro inventum, ordinis sui primatem.", "st": "28.6"}, {"sp": "N", "t": "Hac subita clade Leptitani perterriti, ante incrementa malorum, quae intentabat barbaricus tumor, praesidium imploravere Romani, comitis per Africam recens provecti. Qui cum venisset, militaris copias ducens, ferreque opem rebus rogaretur afflictis, non nisi abundanti commeatu aggesto, et camelorum quattuor milibus apparatis, castra firmabat esse moturum.", "st": "28.6"}, {"sp": "N", "t": "Hocque responso, miserandis civibus stupefactis, atque negantibus, sufficere se posse post vastationes et incendia ita enormibus instrumentis remedia quaerere damnorum immanium, dissimulanter diebus ibi quadraginta consumptis, nullo temptato, inde discesserat comes.", "st": "28.6"}, {"sp": "N", "t": "Qua spe Tripolitani frustrati, formidantesque extrema, allapso legitimo die concilii, quod apud eos est annuum, Severum et Flaccianum creavere legatos, Victoriarum aurea simulacra Valentiniano ob imperii primitias oblaturos, utque lacrimosas provinciae ruinas docerent intrepide.", "st": "28.6"}, {"sp": "N", "t": "Quibus compertis, Romanus, misso equite velocissimo, magistrum officiorum petit Remigium, affinem suum vel rapinarum participem, ut provideret imperatoris arbitrio cognitionem huius negotii Vincentio vicario sibique deferri.", "st": "28.6"}, {"sp": "N", "t": "Venerunt in comitatum legati, aditoque principe, verbis quae perpessi sunt ostenderunt: obtulerunt decreta, textum continentia rei totius. Quibus lectis cum neque relationi officiorum magistri, faventis Romani flagitiis, nec contraria referentibus crederetur, promissa disceptatio plena dilata est eo more, quo solent inter potiorum occupationes ludi potestates excelsae.", "st": "28.6"}, {"sp": "N", "t": "Dum remedia quaedam a commilitio principis exspectantur, suspensis Tripolitanis, diuque anxiis, rursus globi supervenere barbarici, fiducia sublati praeteritorum, Leptitanoque agro et Oeensi interneciva populatione transcursis, expleti praedarum acervis ingentibus, abscesserunt, occisis decurionibus multis, inter quos Rusticianus sacerdotalis, et Nicasius enitebat aedilis.", "st": "28.6"}, {"sp": "N", "t": "Haec autem eruptio ideo arceri non potuit, quod ad legatorum preces negotiorum quoque militarium cura praesidi delata Ruricio, mox translata est ad Romanum.", "st": "28.6"}, {"sp": "N", "t": "Et iam recens inflictae cladis nuntius missus ad Gallias, excitavit acrius principem. Ideoque tribunus et notarius Palladius mittitur, ut et militi disperso per Africam praeberet stipendium debitum, et gesta per Tripolim fide congrua scrutaretur.", "st": "28.6"}, {"sp": "N", "t": "Inter tales tamen consulendi moras exspectandique responsa, Austoriani successu gemino insolentes, ut rapaces alites advolarunt, irritamento sanguinis atrocius efferatae; cunctisque (nisi quos fuga discriminibus eximeret) interemptis, praedas quas antehac reliquerant, avexerunt arboribus exsectis et vitibus.", "st": "28.6"}, {"sp": "N", "t": "Tunc Mychon quidam nobilis oppidanus et potens, captus in suburbano lapsusque, antequam vinciretur, quia pedibus aeger evadere penitus vetabatur, in puteum aquis vacuum sese coniecit, unde costa diffracta levatus a barbaris, ductusque prope portas, coniugis miseratione redemptus est, et ad pinnas muri fune sublatus post biduum interiit.", "st": "28.6"}, {"sp": "N", "t": "Unde elati in pertinaciam saevissimi grassatores, ipsa pulsavere moenia Leptitana, funestis plangoribus resonantia feminarum, quas numquam antea hostiliter clausas pavor exanimabat insolitus, obsessaque urbe per octo continuos dies, cum quidam oppugnatores sine ullo vulnerarentur effectu, redierunt ad propria tristiores.", "st": "28.6"}, {"sp": "N", "t": "Ob quae super salute dubii cives, ultimaque temptantes, profectis ante legatis nondum reversis, Iovinum mittunt atque Pancratium, quae viderint, quaeque ipsi perpessi sint, imperatorem fida relatione docturos. Qui Severum apud Carthaginem inventum et Flaccianum superiores illos legatos percontando quid egerint, cognoverunt eos audiri a vicario iussos et comite. E quibus Severus ilico perit vexatus acerbitate morborum: nihilo minus tamen properarunt ad comitatum magnis itineribus ante dicti.", "st": "28.6"}, {"sp": "N", "t": "Ingresso post haec Palladio Africam, Romanus, quas ob res venerat ante praestructurus, ut securitatem suam in tuto locaret, numerorum principiis per quosdam secretorum mandaverat conscios, ut ei tamquam potenti et palatii summatibus proximo, stipendii, quod pertulerat, praestarent maximam partem: et ita est factum.", "st": "28.6"}, {"sp": "N", "t": "Confestimque ille ditatus perrexit ad Lepcim, utque ad veritatis perveniret indaginem, Erechthium et Aristomenem facundos municipes et insignes, libere suas civiumque et finitimorum retexentes aerumnas, ad loca vastata secum eduxit.", "st": "28.6"}, {"sp": "N", "t": "Quibus aperte cuncta monstrantibus, luctuosis provinciae cineribus visis revertit, Romanumque ut desidem increpans, relaturum se cuncta verissime, quae viderat, minabatur ad principem. Atque ille ira percitus et dolore, se quoque mox referre firmavit, quod missus ut notarius incorruptus, donativum militis omne in quaestus averterit proprios.", "st": "28.6"}, {"sp": "N", "t": "Qua gratia flagitiorum arbitra conscientia, cum Romano deinde Palladius concordabat, reversusque ad comitatum, arte mendaciorum impia Valentinianum fefellerat, Tripolitanos frustra queri commemorans. Ideoque rursus ad Africam cum Iovino postremo omnium legatorum Remittitur—Pancratius enim decesserat apud Treveros–ut cum vicario ipse merita legationis quoque secundae spectaret: praeter haec linguas Erechthi et Aristomenis praecidi iusserat imperator, quos invidiosa quaedam locutos idem Palladius intimarat.", "st": "28.6"}, {"sp": "N", "t": "Secutus, ut statutum est, vicarium notarius venit ad Tripolim. Hocque comperto Romanus domesticum suum illuc volucriter misit, et Caecilium consiliarium in ea provincia genitum, per quos— incertum pretio an fallaciis—circumventi municipes omnes gravabant Iovinum, destinatius asserentes nihil eorum mandasse, quae docuerat principem: eo usque iniquitate grassante ut ipse quoque Iovinus ad salutis suae discrimen confiteretur se imperatori mentitum.", "st": "28.6"}, {"sp": "N", "t": "Quibus per Palladium regressum iam cognitis, Valentinianus ad acerbitatem proclivior Iovinum quidem ut auctorem, Caelestinum vero Concordiumque et Lucium ut falsi conscios et participes puniri supplicio capitali praecepit, Ruricium autem praesidem ut mendacem morte multari, hoc quoque accedente quod in relatione eius verba quaedam (ut visum est) immodica legebantur.", "st": "28.6"}, {"sp": "N", "t": "Ac Ruricius quidem apud Sitifim caesus est, reliqui apud Uticam sententia vicarii Crescentis addicti. Flaccianus tamen ante legatorum interitum, cum a vicario audiretur et comite, constanter saluti suae propugnans, acclamationibus iratorum militum impetuque cum conviciis paene confossus est, obicientium, ideo Tripolitanos non potuisse defendi, quod ipsi ad expeditionalis usus praebere necessaria detrectarunt.", "st": "28.6"}, {"sp": "N", "t": "Et ob haec trusus in carcerem, dum consultus super eo, quid conveniret agi, decerneret imperator, sollicitatis (ut dabatur opinari) custodibus, in urbem Romam abierat profugus, ibique delitescens, fatali lege discessit.", "st": "28.6"}, {"sp": "N", "t": "Hoc memorando fine externis domesticisque cladibus vexata, conticuit Tripolis, non indefensa, quia vigilavit Iustitiae oculus sempiternus, ultimaeque legatorum et praesidis dirae. Diu enim postea huius modi casus emersit: solutus sacramento Palladius, destitutusque fastu quo tumebat, discessit ad otium.", "st": "28.6"}, {"sp": "N", "t": "Et cum Theodosius ductor exercituum ille magnificus, oppressurus Firmum perniciosa coeptantem, venisset in Africam, et proscripti Romani rem mobilem (ut iussum est) scrutaretur, inter chartas eius inventa est et Meteri cuiusdam epistula, id continens “Domino patrono Romano Meterius,” et in fine post multa nihil ad rem pertinentia: “Salutat te Palladius proiecticius, qui non aliam ob causam dicit se esse proiectum, nisi quod in causa Tripolitanorum apud aures sacras mentitus est.”", "st": "28.6"}, {"sp": "N", "t": "His litteris ad comitatum missis et lectis, Valentiniani iussu Meterius raptus, suam esse confitetur epistulam, ideoque Palladius exhiberi praeceptus, cogitans quas criminum coxerit moles, in statione primis tenebris observata custodum absentia, qui festo die Christiani ritus in ecclesia pernoctabant, innodato gutture laquei nexibus interiit.", "st": "28.6"}, {"sp": "N", "t": "Hoc fortunae secundioris iudicio plene comperto, deletoque tristium concitore turbarum, exsiluerunt Erechthius et Aristomenes e latebris, qui cum sibi iussas abscidi linguas didicissent, ut prodigas, ad longe remota declinarunt et abdita, doctoque super nefanda fraude Gratiano imperatore fidentius—Valentinianus enim obierat—ad Hesperium proconsulem et Flavianum vicarium audiendi sunt missi, quorum aequitas auctoritate mixta iustissima, torto Caecilio, aperta confessione cognovit, ipsum suasisse civibus suis, ut gravarent mentiendo legatos. Haec acta secuta est relatio gestorum pandens plenissimam fidem; ad quam nihil responsum est.", "st": "28.6"}, {"sp": "N", "t": "Et nequid cothurni terribilis fabulae relinquerent intemptatum, hoc quoque post depositum accessit aulaeum. Romanus ad comitatum profectus secum Caecilium duxit, cognitores accusaturum, ut inclinatos in provinciae partem: isque Merobaudis favore susceptus, necessarios sibi plures petierat exhiberi.", "st": "28.6"}, {"sp": "N", "t": "Qui cum Mediolanum venissent, frustraque se tractos ob simultates documentis probabilibus ostendissent, absoluti redierunt ad lares. Valentiniano tamen superstite, post superiora quae narravimus, Remigius quoque digressus ad otium, laqueo vitam elisit, ut congruo docebimus loco.", "st": "28.6"}, {"sp": "HDR", "t": "Liber XXIX", "st": "29"}, {"sp": "N", "t": "Exacta hieme rex Persarum gentium Sapor, pugnarum fiducia pristinarum immaniter arrogans, suppleto numero suorum abundeque firmato, erupturos in nostra cataphractos et sagittarios et conductam miserat plebem.", "st": "29.1"}, {"sp": "N", "t": "Contra has copias, Traianus comes et Vadomarius ex rege Alamannorum cum agminibus perrexere pervalidis, hoc observare principis iussu appositi, ut arcerent potius quam lacesserent Persas.", "st": "29.1"}, {"sp": "N", "t": "Qui cum venissent Vagabanta, legionibus habilem locum, rapidos turmarum procursus hostilium in se ruentium acriter exceperunt inviti, operaque consulta retrocedentes, ne ferro violarent adversorum quemquam primi, et iudicarentur discissi foederis rei, ultima trudente necessitate, congressi sunt, confossisque multis, discessere victores.", "st": "29.1"}, {"sp": "N", "t": "Inter moras tamen utrimque secus temptatis aliquotiens levibus proeliis, varioque finitis eventu, pactis indutiis ex consensu, aestateque consumpta, partium discessere ductores, etiam tum discordes. Et rex quidem Parthus, hiemem Ctesiphonte acturus, redit ad sedes, et Antiochiam imperator Romanus ingressus. Qui, dum ibi moratur securus interim hostium externorum, intestinis paene perierat fraudibus, ut aperiet series delata gestorum.", "st": "29.1"}, {"sp": "N", "t": "Procopius quidam, inquies homo, turbarum cupiditati semper addictus, Anatolium detulerat et Spudasium palatinos, exigi quae de aerario interceperant iussos, insidiari comiti Fortunatiano, molesto illi flagitatori. Qui animi asperitate confestim ad insanum percitus modum, pro potestatis auctoritate, quam regebat, Palladium quendam obscurissime natum ut veneficum a memoratis conductum, et Heliodorum, fatorum per genituras interpretem, adigendos prodere quae scirent, praetorianae iudicio tradidit praefecturae.", "st": "29.1"}, {"sp": "N", "t": "Cumque ad facti vel temptati quaestionem acrius veniretur, exclamabat Palladius confidenter, levia esse haec de quibus agitur, et praetereunda: alia se (si licuerit dicere) monstraturum, metuenda et potiora, quae ingenti molimine iam praestructa (nisi prospectum fuerit) universa confundent. Iussusque docere fidenter quae norat, rudentem explicavit immensum, affirmans Fidustium praesidialem, et cum Irenaeo Pergamium, nomen imperaturi post Valentem detestandis praesagiis didicisse secretim.", "st": "29.1"}, {"sp": "N", "t": "Et correptus Fidustius ilico (namque aderat forte,) occulteque inductus, indice viso, nulla infitiatione obumbrare iam publicata conatus, rei totius calamitosum aperit textum, absolute confessus, se cum Hilario et Patricio vaticinandi peritis, quorum Hilarius militaverat in palatio, de imperio consuluisse futuro: motasque secretis artibus sortes, et nuncupationem principis optimi, et ipsis consultoribus luctuosos exitus praedixisse.", "st": "29.1"}, {"sp": "N", "t": "Atque cunctantibus quisnam ea tempestate omnibus vigore animi antistaret, visus est aliis excellere Theodorus, secundum inter notarios adeptus iam gradum. Et erat re vera ita ut opinati sunt. Namque antiquitus claro genere in Galliis natus, et liberaliter educatus a primis pueritiae rudimentis, modestia prudentia humanitate gratia litteris ornatissimus, semper officio locoque, quem retinebat, superior videbatur, altis humilibusque iuxta acceptus. Solusque paene omnium erat, cuius linguam non infrenem, sed dispicientem quae loqueretur, nullius claudebat periculi metus.", "st": "29.1"}, {"sp": "N", "t": "His addebat idem Fidustius, excarnificatus iam ad interitum, omnia quae praedixit, se indicante Theodorum per Euserium didicisse, virum praestabilem scientia litterarum, abundeque honoratum: Asiam quippe paulo ante rexerat pro praefectis.", "st": "29.1"}, {"sp": "N", "t": "Quo in custodia condito, gestorumque volumine imperatori recitato de more, prodigiosa feritas in modum ardentissimae facis fusius vagabatur, elata turpi adulatione multorum, maximeque omnium praefecti praetorio tunc Modesti.", "st": "29.1"}, {"sp": "N", "t": "Qui dum formidine successoris agitaretur in dies, obumbratis blanditiarum concinnitatibus, cavillando Valentem, subrusticum hominem, sibi varie commulcebat, horridula eius verba et rudia flosculos Tullianos appellans, et ad extollendam eius vanitiem, sidera quoque, si iussisset, exhiberi posse promittens.", "st": "29.1"}, {"sp": "N", "t": "Igitur et Theodorus a Constantinopoli, quam ex negotio familiari petierat, rapi celeri iubetur effectu, et dum ille reducitur, ex praeiudiciis variis, quae diebus exercebantur et noctibus, plures a disiunctissimis regionibus trahebantur, dignitatibus et nobilitate conspicui.", "st": "29.1"}, {"sp": "N", "t": "Cumque nec carceres publici, iam distenti, inclusorum catervas, nec privata domicilia sustinerent, constipatione vaporata confertas, quoniam vinculis maxima pars eorum attinebatur, et suam et proximi cuiusque vicem omnes horrebant.", "st": "29.1"}, {"sp": "N", "t": "Advenit aliquando tamen ipse quoque Theodorus, praemortuus et atratus, quo in devia territorii parte abscondito, paratis omnibus quae indagines futurae poscebant, internarum cladum litui iam sonabant.", "st": "29.1"}, {"sp": "N", "t": "Et quia fallere non minus videtur, qui gesta praeterit sciens, quam ille, qui numquam facta confingit, non abnuimus (neque enim ambigitur) salutem Valentis, et antea saepius per occultas coitiones, et tune in extrema demersam, ferrumque ad iugulum eius prope adactum a militaribus, fato reflectente depulsum, quem lacrimosis in Thracia discriminibus destinarat.", "st": "29.1"}, {"sp": "N", "t": "Namque et in nemoroso quodam inter Antiochiam et Seleuciam loco leni quiete post meridiem consopitus, a Sallustio tune scutario, et saepe alias appetenter insidiantibus multis, vitae terminis a primigenio ortu adscriptis, ausa immania frenantibus evadebat.", "st": "29.1"}, {"sp": "N", "t": "Ut sub principibus Commodo et Severo non numquam accidebat, quorum summa vi salus crebro oppugnabatur, adeo ut post intestina pericula multa et varia alter in amphitheatrali cavea cum affuturus spectaculis introiret, a Quintiano senatore illicitae cupidinis homine, ad debilitatem paene pugione vulneraretur; alter inopinabili impetu, tempore aetatis extremo, a Saturnino centurione, consilio Plautiani praefecti, in cubiculo iacens confoderetur, ni tulisset suppetias filius adulescens.", "st": "29.1"}, {"sp": "N", "t": "Quocirca etiam Valens erat venia dignus, vitam, quam ereptum ire perfidi properabant, omni cautela defendens. Sed inexpiabile illud erat, quod regaliter turgidus, pari eodemque iure, nihil inter se distantibus meritis, nocentes innocentesque maligna insectatione volucriter perurgebat, ut dum adhuc dubitaretur de crimine, imperatore non dubitante de poena, damnatos se quidam prius discerent quam suspectos.", "st": "29.1"}, {"sp": "N", "t": "Adulescebat autem obstinatum eius propositum, admovente stimulos avaritia, et sua et eorum qui tune in regia versabantur, novos hiatus aperientium, et, siqua humanitatis fuisset mentio rara, hanc appellantium tarditatem: qui cruentis adulationibus, institutum hominis mortem in acie linguae portantis, ad partem pessimam depravantes, omnia turbine intempestivo perflabant, eversum ire funditus domus opulentissimas festinantes.", "st": "29.1"}, {"sp": "N", "t": "Erat enim expositus accessu insidiantium et reclusus, vitio gemino perniciose implicitus, quod intoleranter irascebatur, tune magis cum eum puderet irasci, et quae facilitate privati opertis susurris audierat, an vera essent, excutere tumore principis supersedens pro veris accipiebat et certis.", "st": "29.1"}, {"sp": "N", "t": "Inde factum est ut clementiae specie penatibus multi protruderentur insontes, praeceps in exsilium acti, quorum in aerario bona coacta et ipse ad quaestus proprios redigebat, ut damnati cibo precario victitarent, angustiis formidandae paupertatis attriti, cuius metu vel in mare nos ire praecipites suadet Theognis poeta vetus et prudens.", "st": "29.1"}, {"sp": "N", "t": "Quae etiam si recta fuisse concesserit quisquam, erat tamen ipsa nimietas odiosa. Unde animadversum est recte hoc definitum, nullam esse crudeliorem sententiam ea, quae est (cum parcere videtur) asperior.", "st": "29.1"}, {"sp": "N", "t": "Igitur cum praefecto praetorio summatibus quaesitis in unum, quibus cognitiones commissae sunt, intenduntur eculei, expediuntur pondera plumbea, cum fidiculis et verberibus, resultabant omnia truculentae vocis horroribus, inter catenarum sonitus “Tene, claude, comprime, abde” ministris officiorum tristium clamitantibus.", "st": "29.1"}, {"sp": "N", "t": "Et quoniam addici post cruciabiles poenas vidimus multos, ut in tenebrosis rebus confusione cuncta miscente, summatim quia nos penitissima gestorum memoria fugit, quae recolere possumus, expeditius absolvemus.", "st": "29.1"}, {"sp": "N", "t": "Primo intro vocatus post interrogatiunculas leves, Pergamius, a Palladio (ut dictum est) proditus, quaedam imprecationibus praescisse nefariis, sicut erat impendio eloquentior, et in verba periculosa proiectus, inter ambigentes iudices, quid prius quaeri debeat quidve posterius, dicere audacter exorsus, multa hominum milia quasi consciorum sine fine strependo fundebat, modo non ab extremo Atlante magnorum criminum arguendos poscens aliquos exhiberi. Quo (ut consarcinante nimis ardua) morte multato, aliisque gregatim post illum occisis, ad ipsius Theodori causam quasi ad Olympici certaminis pulverem pervenitur.", "st": "29.1"}, {"sp": "N", "t": "Eodem die inter complura alia hoc quoque evenerat triste, quod Salia, thesaurorum paulo ante per Thracias comes, cum de vinculis educitur audiendus, et calceo inserit pedem, quasi ruina incidentis immensi terroris repente perculsus, animam inter retinentium manus efflavit.", "st": "29.1"}, {"sp": "N", "t": "Constituto itaque iudicio, et cognitoribus praescripta ostentantibus legum, sed ex voluntate dominantis moderantibus momenta causarum, horror pervaserat universos. Totus enim devius ab aequitate dilapsus, iamque eruditior ad laedendum, in modum harenariae ferae, si admotus quisquam fabricae diffugisset, ad ultimam rabiem saeviebat.", "st": "29.1"}, {"sp": "N", "t": "Inducti itaque Patricius et Hilarius, ordinemque replicare iussi gestorum, cum inter exordia variarent, fodicatis lateribus, illato tripede quo utebantur, adacti ad summas angustias, aperiunt negotii fidem, ab ipsis exordiis replicatam. Et prius Hilarius:", "st": "29.1"}, {"sp": "N", "t": "“Construximus,” inquit, “magnifici iudices, ad cortinae similitudinem Delphicae, diris auspiciis, de laureis virgulis infaustam hanc mensulam, quam videtis, et imprecationibus carminum secretorum, choragiisque multis ac diuturnis, ritualiter consecratam, movimus tandem: movendi autem quotiens super rebus arcanis consulebatur, erat institutio talis.", "st": "29.1"}, {"sp": "N", "t": "“Collocabatur in medio domus, emaculatae odoribus Arabicis undique, lance rotunda pure superposita, ex diversis metallicis materiis fabrefacta. Cuius in ambitu rotunditatis extremo, elementorum viginti quattuor scriptiles formae incisae perite, diiungebantur spatiis examinate dimensis.", "st": "29.1"}, {"sp": "N", "t": "“Ac linteis quidam indumentis amictus, calceatusque itidem linteis soccis, torulo capiti circumflexo, verbenas felicis arboris gestans, litato conceptis carminibus numine, praescitorum auctore, caerimoniali scientia supersistit cortinulae sacerdos pensilem anulum librans, aptum ex Carphathio filo perquam levi, mysticis disciplinis initiatum: qui per intervalla distincta, retinentibus singulis litteris, incidens saltuatim, heroos efficit versus, interrogationibus consonos, ad numeros et modos plene conclusos, quales leguntur Pythici vel ex oraculis editi Branchidarum.", "st": "29.1"}, {"sp": "N", "t": "“Ibi tum quaerentibus nobis, ‘qui praesenti succedet imperio’?, quoniam omni parte expolitus fore memorabatur, et assiliens anulus, duas perstrinxerat syllabas ΘΕΟ cum adiectione litterae posterae, exclamavit praesentium quidam, Theodorum praescribente fatali necessitate portendi. Nec ultra super negotio est exploratum: satis enim apud nos constabat hunc esse qui poscebatur.”", "st": "29.1"}, {"sp": "N", "t": "Cumque totius rei notitiam ita signate sub oculis iudicum subiecisset, adiecit benivole id Theodorum penitus ignorare. Post haec interrogati an ex fide sortium quas agitabant, ea praescierint quae sustinerent, versus illos notissimos ediderunt clare pronuntiantes capitalem eis hanc operam scrutandi sublimiora cito futuram; nihilo minus tamen ipsi quoque cum cognitoribus principi caedis incendiaque flatantes, furias imminere; quorum tres ponere sufficiet ultimos:<br>οὐ μὰν νηποινί γε σὸν ἔσσεται αἷμα καὶ αὐτοῖς<br>Τισιφόνη βαρύμηνις ἐφοπλίσσει κακὸν οἶτον<br>ἐν πεδίοισι Μίμαντος ἀγαιομένοιο Ἄρηος.<br>Quibus lectis, unguibus male mulcati, separantur exanimes.", "st": "29.1"}, {"sp": "N", "t": "Postea ut cogitati sceleris officina pateret aperte, honoratorum inducitur globus, vertices ipsos continens rerum. Cumque nihil praeter se quisque cernens, ruinam suam impelleret super alium, permisso quaesitorum coeptans dicere Theodorus, primo in precem venialem prostratus, dein artius respondere compulsus, ostendit se cognita per Euserium, ne ad imperatorem referret, ut conatus est aliquotiens, ab eo prohibitum, asserente, non appetitu regni occupandi illicito, sed ratione quadam indeclinabilis fati, id quod sperabatur ultro venturum.", "st": "29.1"}, {"sp": "N", "t": "Deinde haec eadem Euserio sub cruenta quaestione confesso, confutabant Theodorum litterae suae, per ambagis obliquas ad Hilarium scriptae, quibus spe iam firma concepta ex vatibus, de re non cunctabatur, sed tempus patrandae cupidinis quaeritabat.", "st": "29.1"}, {"sp": "N", "t": "Quibus post haec cognita sequestratis, Eutropius Asiam proconsulari tune obtinens potestate, ut factionis conscius arcessitus in crimen, abscessit innocuus, Pasiphilo eximente philosopho, qui ut eum mendacio iniusto perverteret, crudeliter tortus, de statu robustae mentis non potuit deturbari.", "st": "29.1"}, {"sp": "N", "t": "His accessit philosophus Simonides, adulescens ille quidem, verum nostra memoria severissimus. Qui cum audisse negotium per Fidustium deferretur, et causam non ex veritate sed ex unius nutu pensari vidisset, didicisse se dixit praedicta, sed commissa pro firmitate animi tacuisse.", "st": "29.1"}, {"sp": "N", "t": "Quis omnibus perspicaciter inquisitis, imperator cognitorum consultationi respondens, sub uno proloquio cunctos iubet occidi, et vix sine animorum horrore funestum spectaculum multitudine innumera contuente, et onerante questibus caelum (namque singulorum mala omnium esse communia credebantur), ducti universi flebiliter iugulantur praeter Simonidem, quem solum saevus ille sententiae lator, efferatus ob constantiam gravem, iusserat flammis exuri.", "st": "29.1"}, {"sp": "N", "t": "Qui vitam ut dominam fugitans rabidam, ridens subitas momentorum ruinas, immobilis conflagravit, Peregrinum ilium imitatus (Protea cognomine) philosophum clarum, qui cum mundo digredi statuisset, Olympiae quinquennali certamine sub Graeciae conspectu totius, escenso rogo quem ipse construxit, flammis absumptus est.", "st": "29.1"}, {"sp": "N", "t": "Et post hunc diebus secutis, omnium fere ordinum multitudo, quam nominatim recensere est arduum, in plagas calumniarum coniecta, percussorum dexteras fatigavit, tormentis et plumbo et verberibus ante debilitata, sumptumque est de quibusdam sine spiramento vel mora supplicium, dum quaeritur an sumi deberet, et ut pecudum ubique trucidatio cernebatur.", "st": "29.1"}, {"sp": "N", "t": "Deinde congesti innumeri codices, et acervi voluminum multi, sub conspectu iudicum concremati sunt, ex domibus eruti variis ut illiciti, ad leniendam caesorum invidiam, cum essent plerique liberalium disciplinarum indices variarum et iuris.", "st": "29.1"}, {"sp": "N", "t": "Neque ita multo post Maximus ille philosophus, vir ingenti nomine doctrinarum, cuius ex uberrimis sermonibus ad scientiam copiosus Iulianus exstitit imperator, oraculi supra dicti versus audisse insimulatus, seque comperisse assensus, sed reticenda professionis consideratione non effudisse, verum ultro praedixisse consultores ipsos suppliciis poenalibus perituros, Ephesum ad genuinam patriam ductus, ibique capite truncatus, sensit docente periculo postremo quaesitoris iniquitatem omnibus esse criminibus graviorem.", "st": "29.1"}, {"sp": "N", "t": "Constrictus etiam Diogenes laqueis impiae falsitatis, vir nobili prosapia editus, ingenio facundia forti suavitateque praestans, dudum Bithyniae rector, ut opimum patrimonium eius diriperetur, capitali est poena affectus.", "st": "29.1"}, {"sp": "N", "t": "Ecce autem Alypius quoque, ex vicario Britanniarum, placiditatis homo iucundae, post otiosam et repositam vitam (quoniam huc usque iniustitia tetenderat manus) in squalore maximo volutatus, ut veneficus reus citatus est, cum Hierocle filio, adulescente indolis bonae, urgente Diogene quodam et vili et solo, omnique laniena excruciate, ut verba placentia principi, vel potius accersitori, loqueretur: quo cum poenis non sufficerent membra, vivo exusto, ipse quoque Alypius post multationem bonorum exsulare praeceptus, filium miserabiliter ductum ad mortem casu quodam prospero revocatum excepit.", "st": "29.1"}, {"sp": "N", "t": "Per id omne tempus, Palladius ille, coagulum omnium aerumnarum, quem captum a Fortunatiano docuimus primum, ipsa sortis infimitate ad omnia praeceps, clades alias super alias cumulando, lacrimis universa perfuderat luctuosis.", "st": "29.2"}, {"sp": "N", "t": "Nanctus enim copiam nominandi, sine fortunarum distantia, quos voluisset, ut artibus interdictis imbutos, ita ut ferarum occulta vestigia doctus observare venator, multos intra casses lugubres includebat, quosdam veneficiorum notitia pollutos, alios ut appetitoribus imminuendae conscios maiestatis.", "st": "29.2"}, {"sp": "N", "t": "Et ne vel coniugibus maritorum vacaret miserias flere, immittebantur confestim qui signatis domibus inter scrutinia suppellectilis patris addicti, incantamenta quaedam anilia vel ludibriosa subderent amatoria, ad insontium perniciem concinnata: quibus in iudicio recitatis, ubi non lex non religio, non aequitas veritatem a mendaciis dirimebat, indefensi bonis ablatis, nullo contacti delicto, promiscue iuvenes aliique, membris omnibus capti, ad supplicia sellis gestatoriis ducebantur.", "st": "29.2"}, {"sp": "N", "t": "Inde effectum est per orientales provincias, ut a dominis metu similium exurerentur libraria omnia: tantus universos invaserat terror. Namque ut pressius loquar, omnes ea tempestate velut in Cimmeriis tenebris reptabamus, paria convivis Siculi Dionysii pavitantes, qui cum epulis omni tristioribus fame saginarentur, ex summis domorum laqueariis, in quibus discumbebant, saetis nexos equinis, et occipitiis incumbentes, gladios perhorrebant.", "st": "29.2"}, {"sp": "N", "t": "tunc et Bassianus, praeclaro genere natus, notarius militans inter primos, quas praenoscere altiora conatus, licet ipse de qualitate partus uxoris consuluisse firmaret, ambitioso necessitudinum studio, quibus tegebatur, morte ereptus, patrimonio opimo exutus est.", "st": "29.2"}, {"sp": "N", "t": "Inter fragores tot ruinarum Heliodorus, tartareus ille malorum omnium cum Palladio fabricator, mathematicus (ut memorat vulgus) colloquiis ex aula regia praepigneratus abstrusis, iam funebres aculeos exsertabat, omni humanitatis invitamento ad prodenda quae sciret vel fingeret, lacessitus.", "st": "29.2"}, {"sp": "N", "t": "Nam et sollicitius cibo mundissimo fovebatur, et ad largiendum paelicibus, merebat aes collaticium grave, et incedebat passim ac late, os circumferens vultuosum, omnibusque formidatum, ea fiducia sublatior, quod ad lupanar, quo (sicut ipse voluit), liberius versabatur, cubiculariis officiis praepositus, assidue propalam ventitabat, elogia parentis publici praeferens, futura pluribus luctuosa.", "st": "29.2"}, {"sp": "N", "t": "Per quae eum (ut forensium causarum patronum) quid in primis orationis partibus collocaret, ut proficere possit facilius et valere, quibusve figurarum commentis, splendida loca attemptare debeat praemonebat.", "st": "29.2"}, {"sp": "N", "t": "Et quoniam longum est narrare omnia quae cruciarius ille conflavit, hoc unum edisseram, quam praecipiti confidentia patriciatus columina ipsa pulsavit. Qui ex clandestinis (ut dictum est) regiorum confabulationibus immaniter arrogans, et ipsa vilitate ad facinus omne venalis, egregium illud par consulum, Eusebium et Hypatium (germanos fratres) Constanti principis quondam affines, ad cupidinem altioris fortunae erectos et consuluisse et agitasse quaedam super imperio detulit, addens itineri ad mendacium ficte constructo, quod Eusebio etiam principalia indumenta parata sint.", "st": "29.2"}, {"sp": "N", "t": "Quibus haustis aventer, fremebundus et minax, cui nihil licere debuerat, quia omnia sibi licere etiam iniusta existimabat, irremisse ab extremis regionum intervallis exhibitis omnibus, quos solutus legibus accusator perduci debere profunda securitate mandarat, suscipi quaestionem criminose praecepit.", "st": "29.2"}, {"sp": "N", "t": "Cumque nodosis coartationibus aequitate diu calcata, et nexibili asseveratione perditi nebulonis durante, nullam confessionem exprimere tormenta gravia potuissent, ablegatosque ab omni huius modi conscientia ipsa viros ostenderent claros, calumniator quidem ita ut antea honorabiliter colebatur, illi vero exsilio et pecuniariis afflicti dispendiis, paulo postea reddita sibi multa, sunt revocati, dignitatibus integris et splendore.", "st": "29.2"}, {"sp": "N", "t": "Nec tamen post haec tam paenitenda repressius actum est vel pudenter, non reputante alta nimium potestate, quod recte institutis ne cum inimicorum quidem incommodis in delicta convenit ruere voluntaria, nihilque sit tam deforme quam ad ardua imperii supercilia etiam acerbitatem naturae adiungi.", "st": "29.2"}, {"sp": "N", "t": "Sed Heliodoro (incertum morbo an quadam excogitata vi) mortuo (nolim dicere “sero”: utinam nec ipsa res loqueretur!) funus eius per vespillones elatum, pullati praecedere honorati complures, inter quos et fratres iussi sunt consulares.", "st": "29.2"}, {"sp": "N", "t": "Ibi tune rectoris imperil caries tota stoliditatis apertius est profanata, qui cum abstinere inconsolabili malo rogaretur obnixe, inflexibilis mansit, ut videretur aures occlusisse ceris (quasi scopulos Sirenios transgressurus).", "st": "29.2"}, {"sp": "N", "t": "Superatus tamen precibus destinatis, tandem nudatis capitibus, infaustam bustuarii libitinam ad usque sepulcrum incedentes et pedibus, quosdam etiam complicatis articulis, praeire mandavit. Horret mens reminisci, quo iustitio humilitati tot rerum apices visebantur, et praecipue consulares, post scipiones et trabeas et fastorum monumenta mundana.", "st": "29.2"}, {"sp": "N", "t": "Inter quos omnes ab adulescentia virtutum pulchritudine commendabilis, noster Hypatius praeminebat, vir quieti placidique consilii, honestatem lenium morum velut ad perpendiculum librans, qui et maiorum claritudini gloriae fuit, et ipse posteritatem mirandis actibus praefecturae geminae decoravit.", "st": "29.2"}, {"sp": "N", "t": "Accesserat hoc quoque eodem tempore ad Valentis ceteras laudes, quod cum in aliis ita saeviret infeste, ut poenarum maiores aegre ferret finiri cum morte dolores, Numerium tribunum, malitia quendam exsuperantem, eisdem diebus convictum, confessumque quod exsecto vivae mulieris ventre, atque intempestivo partu extracto, infernis manibus excitis, de permutatione imperii consulere ausus est, familiaritatis contuitu, ordine omni mussante, abire iussit, inlaesum, salutem et invidendas opes et militiae statum integrum retenturum.", "st": "29.2"}, {"sp": "N", "t": "O praeclara informatio doctrinarum, munere caelesti indulta felicibus, quae vel vitiosas naturas saepe excoluisti! Quanta in illa caligine temporum correxisses, si Valenti scire per te licuisset, nihil aliud esse imperium, ut sapientes definiunt, nisi curam salutis alienae, bonique esse moderatoris, restringere potestatem, resistere cupiditati omnium rerum, et implacabilibus iracundiis, nosseque (ut Caesar dictator aiebat) miserum esse instrumentum senectuti recordationem crudelitatis, ideoque de vita et spiritu hominis, qui pars mundi est et animantium numerum complet, laturum sententiam diu multumque oportere cunctari, nec praecipiti studio, ubi irrevocabile factum est, agitari, ut exemplum est illud antiquitati admodum notum.", "st": "29.2"}, {"sp": "N", "t": "Apud proconsulem Asiae Dolabellam Smyrnaea mulier subolem propriam et maritum venenis necasse confessa, quod filium e matrimonio priore susceptum occiderint, et comperendinata cum consilium, ad quod res ex more delata est, anceps, quid inter ultionem et scelus statui debeat, haesitaret, ad Areopagitas missa est (Athenienses iudices tristiores), quorum aequitas deorum quoque iurgia dicitur distinxisse. Hi causa cognita centesimo post anno cum accusatore mulierem adesse iusserunt, ne aut absolverent veneficam, aut ultrix necessitudinum puniretur. Ita numquam tardum existimatur, quod est omnium ultimum.", "st": "29.2"}, {"sp": "N", "t": "Post commissa iniquitatibus variis ante dicta, et impressas foede corporibus liberis, quae supervixerant, notas, inconivus Iustitiae oculus, arbiter et vindex perpetuus rerum vigilavit attente. Namque caesorum ultimae dirae, perpetuum numen ratione querellarum iustissima commoventes, Bellonae accenderant faces, ut fides oraculi firmaretur, quod nihil impune praedixerat perpetrari.", "st": "29.2"}, {"sp": "N", "t": "Dum haec quae supra digesta sunt Antiochiae Parthico fragore cessante, per intestinas dilatantur aerumnas, coetus furiarum horrificus, post convolutos multiplices casus, ab eadem urbe digressus, cervicibus Asiae totius insedit hoc modo.", "st": "29.2"}, {"sp": "N", "t": "Festinus quidam Tridentinus ultimi sanguinis et ignoti, in nexum germanitatis a Maximino dilectus, ut sodalis et contogatus, decernentibus fatis, ad orientem transgressus est, ibique administrata Syria magisterioque memoriae peracto, bona lenitudinis et reverentiae reliquit exempla, unde regere Asiam proconsulari potestate exorsus, velificatione tranquilla, ut aiunt, ferebatur ad gloriam.", "st": "29.2"}, {"sp": "N", "t": "Audiens autem Maximinum optimo cuique exitialem, obtrectabat subinde actibus eius, ut perniciosis et foedis. Sed cum impie peremptorum exsequiis suffragantibus, ad praefecturam venisse hominem comperisset immeritum, exarsit ad agenda sperandaque similia, et histrionis ritu mutata repente persona, studio nocendi concepto, incedebat oculis intentis ac diris, praefecturam autumans affore prope diem, si ipse quoque se contaminasset insontium poenis.", "st": "29.2"}, {"sp": "N", "t": "Et quamquam sint multa et varia, quae (ut levius interpretemur) egit asperrime: pauca tamen dici sufficiet, quae sunt nota ac pervulgata, ad aemulationem eorum commissa, quae facta sunt Romae. Ratio enim eadem est ubique recte secusve gestorum, etiam si magnitudo sit dissimilis rerum.", "st": "29.2"}, {"sp": "N", "t": "Philosophum quendam Coeranium, haut exilis meriti virum, ea causa tormentorum immanitate invictum occidit, quod ad coniugem suam familiariter scribens, id sermone addiderat Graeco: σὺ δὲ νόει καὶ στέφε τὴν πύλην, quod dici proverbialiter solet, ut audiens altius aliquid agendum agnoscat.", "st": "29.2"}, {"sp": "N", "t": "Anum quandam simplicem intervallatis febribus mederi leni carmine consuetam, occidit ut noxiam, postquam filiam suam ipso conscio curavit adscita.", "st": "29.2"}, {"sp": "N", "t": "In chartis cuiusdam municipis clari, scrutari ex negotio iussis, genitura Valentis cuiusdam inventa est, repellensque calumnias is cuius intererat, cum obiectaretur ei quam ob rem constellationem principis collegisset, fratrem suum fuisse Valentem, dudumque obisse, documentorum plena fide monstrare pollicitus, inexspectato veritatis indicio, laniatis lateribus, trucidatus est.", "st": "29.2"}, {"sp": "N", "t": "Visus adulescens in balneis admovere marmori manus utriusque digitos alternatim et pectori, septemque vocales litteras numerasse, ad stomachi remedium prodesse id arbitratus: in iudicium tractus, percussus est gladio post tormenta.", "st": "29.2"}, {"sp": "N", "t": "Hic et mihi vertenti stilum in Gallias, confunditur ordo seriesque gestorum, inter multa et saeva Maximinum reperiens iam praefectum, qui potestate late diffusa, scaevum imperatori accesserat incentivum, maiestati fortunae miscenti licentiam gravem. Quisquis igitur dicta considerat, perpendat etiam cetera, quae tacentur, veniam daturus, ut prudens, si non cuncta complectimur, quae consiliorum pravitas crimina in maius exaggerando commisit.", "st": "29.3"}, {"sp": "N", "t": "Adulescente enim acerbitate, rationum inimica rectarum, trux suopte ingenio Valentinianus, post eiusdem Maximini adventum, nec meliora monente ullo nec retentante, per asperos actus velut aestu quodam fluctuum ferebatur et procellarum, adeo ut irascentis saepe vox et vultus et incessus mutaretur et color. Quam rem indicia varia testantur et certa, e quibus pauca sufficiet poni.", "st": "29.3"}, {"sp": "N", "t": "Adultus quidam ex his quos paedagogianos appellant, ad observandam venaticiam praedam, Spartanum canem retinere dispositus, ante praedictum tempus absolvit, adsultu eius evadere conantis appetitus et morsu: ideoque necatus ad exitium fustibus, eadem humatus est die.", "st": "29.3"}, {"sp": "N", "t": "Praepositum fabricae oblato thorace polito faberrime, praemiumque ideo exspectantem, ea re praecepit occidi diritate pari quod pondus paulo minus habuit species ferrea, quam ille firmarat. Epiroten aliquem ritus Christiani presbyterum acceptum Octaviano ex proconsule … offensarum auctore licet tardius ad sua remisso.", "st": "29.3"}, {"sp": "N", "t": "Constantianus strator paucos militares equos ex his ausus mutare, ad quos probandos missus est in Sardiniam, eodem iubente lapidum ictibus oppetit crebris. Athanasius favorabilis tunc auriga, ita suspectus ei vulgari levitate, ut vivus incendi iuberetur, si quid temptasset huius modi, non multo postea veneficiis usus incessebatur; nulla delata voluptatum artifici venia, ignibus aboleri praeceptus est.", "st": "29.3"}, {"sp": "N", "t": "Africanus causarum in urbe defensor assiduus, post administratam provinciam, ad regendam aliam adspiravit, cuius suffragatori magistro equitum Theodosio, id petenti, subagresti verbo pius responderat imperator: “Abi,” inquit, “comes, et muta ei caput, qui sibi mutari provinciam cupit”: et hoc elogio perit homo disertus, ad potiora festinans, ut multi.", "st": "29.3"}, {"sp": "N", "t": "Claudium et Sallustium, ex Iovianorum numero ad usque tribunatus dignitates progressos, accusabat quidam vilitate ipsa despectus, quod cum imperium Procopius affectasset, aliqua pro eo locuti sunt bona. Cumque nihil quaestiones reperirent assiduae, mandare magistris equitum auditoribus princeps, ut agerent in exsilium Claudium et Sallustium pronuntiarent capitis reum, pollicitus quod eum revocabit ad supplicium raptum; hocque ita (ut statutum est) observato, nec Sallustius morte exemptus est, nec Claudius nisi post eiusdem Valentiniani obitum deportationis maestitia liberatus … longe recusaverit, cum illi saepissime torquerentur.", "st": "29.3"}, {"sp": "N", "t": "Replicatis igitur quaestionibus dense, et quibusdam vi nimia tormentorum absumptis, ne vestigia quidem ulla delatorum reperta sunt criminum. In hoc negotio protectores, ad exhibendas missi personas, de … fustibus praeter solitum caesi.", "st": "29.3"}, {"sp": "N", "t": "Horrescit animus omnia recensere, simulque reformidat, ne ex professo quaesisse videamur in vitia principis, alia commodissimi. Illud tamen nec praeteriri est aequum nec sileri, quod cum duas haberet ursas saevas hominum ambestrices, Micam auream et Innocentiam, cultu ita curabat enixo, ut earum caveas prope cubiculum suum locaret, custodesque adderet fidos, visuros sollicite, nequo casu ferarum deleretur luctificus calor. Innocentiam denique, post multas quas eius laniatu cadaverum viderat sepulturas, ut bene meritam in silvas abire dimisit innoxiam, exoptans similes edituram. …", "st": "29.3"}, {"sp": "N", "t": "Et haec quidem morum eius et propositi cruenti sunt documenta verissima. Sollertiae vero circa rem publicam usquam digredientis, nemo eum vel obtrectator pervicax incusabit, illud contemplans, quod maius pretium operae foret in coercendis verius limite barbaris quam pellendis. Et cum dedisset … e speculis, siquis hostium se commovisset, desuper visus obruebatur.", "st": "29.4"}, {"sp": "N", "t": "Agitabatur autem inter multiplices curas id omnium primum atque potissimum, ut Macrianum regem auctum inter mutationes crebras sententiarum, iamque in nostros adultis viribus exsurgentem, vi superstitem raperet vel insidiis, ut multo ante Vadomarium Iulianus: et praevisis quae negotium poscebat et tempus, cognitoque transfugarum indiciis, ubi comprehendi nihil hostile operiens poterit ante dictus, tacite quantum concessit facultas, nequi conserendo officeret ponti, iunxit navibus Rhenum.", "st": "29.4"}, {"sp": "N", "t": "Et antegressus contra Mattiacas aquas, primus Severus, qui pedestrem curabat exercitum, perpensa militum paucitate, territus stetit, timens ne resistere nequiens, irruentium opprimeretur hostilium agminum mole.", "st": "29.4"}, {"sp": "N", "t": "Et quia suspicabatur venalia ducentes mancipia scurras, casu illic repertos, id quod viderant, excursu celeri nuntiare, cunctos mercibus direptis occidit.", "st": "29.4"}, {"sp": "N", "t": "Adventu itaque plurium copiarum animati indices, castrisque ad tempus brevissimum fixis, quia nec sarcinale iumentum quisquam nec tabernaculum habuit, praeter principem, cui tapete et sisyra suffecerant pro tentorio, parumper ob tenebras morati nocturnas, exsiliente Lucifero, urgente procinctu pergebant ulterius, itinerum gnaris ducentibus, frequenti equitatu cum Theodosio rectore praeire disposito, ne quid lateret … tempore iaceat, extento strepitu suorum est impeditus quibus assidue mandans, ut rapinis et incendiis abstinerent, impetrare non potuit. Ignium enim crepitu dissonisque clamoribus satellites exciti, idque quod acciderat suspicati, carpento veloci impositum regem angusto aditu circumfractis collibus abdiderunt.", "st": "29.4"}, {"sp": "N", "t": "Hac Valentinianus gloria defraudatus nec sua culpa nec ducum, sed intemperantia militis, quae dispendiis gravibus saepe rem Romanam afflixit, ad usque quinquagesimum lapidem terris hostilibus inflammatis, redit Treveros maestus.", "st": "29.4"}, {"sp": "N", "t": "Ubi tamquam leo ob cervum amissum vel capream morsus vacuos concrepans tum cum hostium disiecta frangeret timor, in Macriani locum Bucinobantibus, quae contra Mogontiacum gens est Alamannica, regem Fraomarium ordinavit, quem paulo postea quoniam recens excursus eundem penitus vastaverat pagum, in Britannias translatum, potestate tribuni, Alamannorum praefecerat numero, multitudine viribusque ea tempestate florenti: Bitheridum vero et Hortarium (nationis eiusdem primates), item regere milites iussit, e quibus Hortarius, proditus relatione Florenti, Germaniae ducis, contra rem publicam quaedam ad Macrianum scripsisse, barbarosque optimates, veritate tormentis expressa, conflagravit flamma poenali.", "st": "29.4"}, {"sp": "N", "t": "Abhinc inter … proximo haec narratione disseri continua placuit, ne dum negotiis longe discretis et locis alia subseruntur, cognitio multiplex necessario confundatur.", "st": "29.5"}, {"sp": "N", "t": "Nubel velut regulus per nationes Mauricas potentissimus, vita digrediens, et legitimos et natos e concubinis reliquit filios, e quibus Zammac comiti nomine Romano acceptus, latenter a fratre Firmo peremptus, discordias excitavit et bella. Eius enim necem ulcisci, impensiore studio properans comes, ad insidiatoris perniciem multa ciebat et formidanda. Utque rumores distulerunt assidui, navabatur opera diligens in palatio, Romani quidem relationes, multa et aspera congerentes in Firmum, libenter suscipi recitarique principi, in earum favorem concinentibus multis: ea vero, quae contra Firmus salutis tuendae gratia docebat crebro per suos, accepta, diutius occultari, Remigio tunc officiorum magistro, affine amicoque Romani, inter potiores imperatoris necessitates haec velut minima et superflua, non nisi opportune legi posse adseverante.", "st": "29.5"}, {"sp": "N", "t": "Quae cum ad obruendam defensionem suam agitari adverteret Maurus, ultimorum metu iam trepidans, ne amendatis, quae praetendebat, ut perniciosus et contumax indemnatus occideretur, ab imperii dicione descivit et adiumenta conquirebat vicinarum gentium … ad vastandum …", "st": "29.5"}, {"sp": "N", "t": "Ad hoc periculum antequam hostis implacabilis incrementis virium adulescerent, abolendum cum comitatensis auxilio militis pauci Theodosius magister equitum mittitur, cuius virtutes (ut impetrabilis) ea tempestate prae ceteris enitebant: Domitii Corbulonis et Lusii simillimi veterum, quorum prior sub Nerone, alter Traiano rem regente Romanam pluribus inclaruere fortibus factis.", "st": "29.5"}, {"sp": "N", "t": "Proinde ab Arelate secundis egressus auspiciis, emeatoque mari cum classe, quam ductabat, nullo de se rumore praegresso, defertur ad Sitifensis Mauritaniae litus, quod appellant accolae Igilgitanum. Ibique inventum casu Romanum leniter allocutus, misit ad vigilias ordinandas et praetenturas, parum super his quae verebatur increpitum.", "st": "29.5"}, {"sp": "N", "t": "Quo ad Caesariensem digresso Gildonem Firmi fratrem et Maximum misit correpturos Vincentium, qui curans Romani vicem, incivilitatis eius erat particeps et furtorum.", "st": "29.5"}, {"sp": "N", "t": "Recepto itaque tardius milite, quem amplitudo maris morabatur, Sitifim properans, Romanum cum domesticis custodiendum, protectoribus committi mandavit, agensque in oppido sollicitudine diducebatur ancipiti, multa cum animo versans, qua via quibusve commentis, per exustas caloribus terras pruinis assuetum duceret militem, vel hostem caperet discursatorem et repentinum, insidiisque potius clandestinis, quam proeliorum stabilitate confisum.", "st": "29.5"}, {"sp": "N", "t": "Quod ubi Firmo levi rumore, dein apertis est indiciis cognitum, spectatissimi ducis adventu praestrictus, veniam cum concessione praeteritorum, missis oratoribus poscebat et scriptis, docentibus eum non sponte sua ad id erupisse, quod norat scelestum, sed Romani iniquitate grassante licentius, ut monstrare pollicebatur.", "st": "29.5"}, {"sp": "N", "t": "Quibus lectis, paceque obsidibus acceptis promissa, dux ad recensendas legiones quae Africam tuebantur, ire pergebat ad Pancharianam stationem, quo convenire praeceptae sunt. Ibi magnificis verbis atque prudentibus spe cunctorum erecta, reversus Sitifim, consociato indigena milite cum eo quem ipse perduxerat, aegre perpetiens moras, ad procinctus ire ocius festinabat.", "st": "29.5"}, {"sp": "N", "t": "Inter residua autem multa et clara, id amorem eius auxerat in immensum, quod a provincialibus commeatum exercitui prohibuit dari, messes et condita hostium virtutis nostrorum horrea esse, fiducia memorans speciosa.", "st": "29.5"}, {"sp": "N", "t": "His ita cum laetitia possessorum dispositis, ad Tubusuptum progressus, oppidum Ferrato contiguum monti, legationem secundam Firmi repudiavit, quae obsides (ut ante statutum est) non duxerat secum. Unde omnibus pro loco et tempore cautius exploratis, concito gradu Tyndensium gentem et Masinissensium petit, levibus armis instructas, quas Mascizel et Dius fratres Firmi ductabant.", "st": "29.5"}, {"sp": "N", "t": "Cum essent hostes iam in contuitu, membris omnibus celeres, post missilia hinc inde crebrius iacta, committitur certamen asperrimum, interque gemitus mortis et vulnerum, audiebantur barbarorum ululabiles fletus captorum et caesorum, pugnaque dirempta plures agri populati sunt et incensi.", "st": "29.5"}, {"sp": "N", "t": "Inter quas clades eminuere fundi Petrensis, excisi radicitus, quem Salmaces dominus (Firmi frater) in modum urbis exstruxit. Hoc successu victor elatus, mira velocitate Lamfoctense oppidum occupavit, inter gentes positum ante dictas, ubi abunde rei cibariae copiam condi effecit, ut si pergens interius alimentorum offendisset penuriam, iuberet e propinquo convectari.", "st": "29.5"}, {"sp": "N", "t": "Quae dum ita procedunt, Mascizel reparatis viribus nationum confinium adminicula ductans, conserta manu cum nostris, fusis e parte suorum compluribus, ipse equi pernicitate aegre discrimine mortis exemptus est.", "st": "29.5"}, {"sp": "N", "t": "Fessus aerumnis gemini proelii Firmus, imoque aestuans corde, nequid ultimae rationis omitteret, Christiani ritus antistites oraturos pacem cum obsidibus misit. Qui quoniam suscepti lenius pollicitique victui congrua militibus (ut praeceptum est), laeta rettulere responsa et pacem, missis muneribus, Maurus ipse fidentius ad Romanum perrexerat ducem, equo insidens apto ad ancipitis casus, cumque prope venisset, fulgore signorum et terribili vultu Theodosi praestrictus, iumento desiluit, curvataque cervice humi paene affixus, temeritatem suam flebiliter incusabat, pacem obsecrando cum venia.", "st": "29.5"}, {"sp": "N", "t": "susceptusque cum osculo, quoniam id rei publicae conducebat, bonae spei iam plenus, sufficientia praebuit alimenta, et quibusdam propinquis suis ad obsidum vicem relictis, abscessit, captivos (ut spoponderat) redditurus, quos primis turbarum exordiis rapuit: biduoque post, Icosium oppidum, cuius supra docuimus conditores, militaria signa et coronam sacerdotalem, cum ceteris quae interceperat, nihil cunctatus restituit, ut praeceptum est.", "st": "29.5"}, {"sp": "N", "t": "Exinde cum discursis itineribus magnis, Tipasam noster dux introiret, legatis Mazicum, qui se consociaverant Firmo, suppliciter obsecrantibus veniam, animo elato respondit, se in eos ut perfidos arma protinus commoturum.", "st": "29.5"}, {"sp": "N", "t": "Quibus imminentis periculi metu defixis, revertique iussis ad sua, Caesaream ire tendebat, urbem opulentam quondam et nobilem, cuius itidem originem in Africae situ digessimus plene, eamque ingressus, cum omnem paene incendiis late dispersis vidisset exustam, horridasque canitie silices, primam et secundam legionem ad tempus ibi locari disposuit, ut favillarum egerentes acervos, agitarent ibi praesidium, ne repetito barbarorum impetu vastaretur.", "st": "29.5"}, {"sp": "N", "t": "Quae cum rumores crebri distulissent et veri, provinciae rectores, tribunusque Vincentius, e latibulis quibus sese commiserant, egressi tandem intrepidi ad ducem ocius pervenerunt. Quibus ille gratanter visis atque susceptis, agens etiam tum apud Caesaream, fide rerum diligentius explorata, comperit Firmum per speciem paventis et supplicis, tectiore consilio id moliri, ut nihil hostile metuentem exercitum in modum tempestatis subitae conturbaret.", "st": "29.5"}, {"sp": "N", "t": "Quam ob rem conversus hinc venit ad municipium Sugabarritanum, Transcellensi monti accline, ubi inventos equites quartae sagittariorum cohortis, quae ad rebellem defecerat, ut contentum se supplicio leniori monstraret, omnes contrusit ad infimum militiae gradum, eosque et Constantianorum peditum partem Tigavias venire iusserat cum tribunis, e quibus unus torquem pro diademate capiti imposuit Firmi.", "st": "29.5"}, {"sp": "N", "t": "Quae dum aguntur, reverterunt Gildo et Maximus, Bellen e principibus Mazicum et Fericium gentis praefectum ducentes, qui factionem iuverant quietis publicae turbatoris … producerent vinctos.", "st": "29.5"}, {"sp": "N", "t": "Quo ita ut statutum est facto, lucis primo exortu, ipse egressus, cum invenisset eos in exercitu circumsaeptos: “Quid de istis nefariis” inquit “proditoribus fieri oportere, contubernales devoti, censetis?” Secutusque acclamationem rogantium, sanguine vindicari, eos qui inter Constantianos merebant, prisco more militibus dedidit occidendos, sagittariorum vero primoribus manus incidit, residuos supplicio capitali multavit, ad aemulationem Curionis, acerrimi illius ducis, qui Dardanorum ferociam, in modum Lernaeae serpentis aliquotiens renascentem, hoc genere poenarum extinxit.", "st": "29.5"}, {"sp": "N", "t": "Sed obtrectatores malivoli vetus factum laudantes, hoc ut dirum vituperant et asperrimum, Dardanos hostes memorantes internecivos, et iuste quae sustinuere perpessos, hos vero subsignanos milites debuisse lenius corrigi, ad unum prolapsos errorem. Quos nescientes forsitan admonemus, hanc cohortem et facto fuisse et exemplo adversam.", "st": "29.5"}, {"sp": "N", "t": "Ante dictos Bellen et Fericium, quos duxerat Gildo, tribunumque sagittariorum Curandium, ea re iussit occidi, quod nec ipse umquam cum hostibus congredi voluit, nec suos ut pugnarent hortari. Agebat autem haec Tullianum illud advertens, quod “salutaris vigor vincit inanem speciem clementiae.”", "st": "29.5"}, {"sp": "N", "t": "Exin profectus, fundum nomine Gaionatis, muro circumdatum valido, receptaculum Maurorum tutissimum, arietibus admotis evertit, et caesis omnibus incolis, moenibusque complanatis, ad Tingitanum castellum progressus, per Ancorarium montem, Mazicas in unum collectos invasit, iam tela reciprocantes, volitantia grandinis ritu.", "st": "29.5"}, {"sp": "N", "t": "Et cum esset utrimque discursum, agmina viribus armisque incitata nostrorum non perferentes Mazices licet bellicosum genus et durum, diversis stragibus implicati, foedo diffluxere terrore, ruentesque in fugam, caesi sunt absque his qui reperta copia discedendi supplici prece veniam (quam dari tempus flagitaverat) impetrarunt.", "st": "29.5"}, {"sp": "N", "t": "Suggen eorum ductorem … Romano successerat, in Sitifensem Mauritaniam ire disposito, ad agitanda praesidia, ne provincia pervaderetur, ipse praeteritis elatior casibus, gentem petit Musonum, quam conscientia rapinarum et caedum actibus congregaverat Firmi, ut sperabatur maiora mox adepturi.", "st": "29.5"}, {"sp": "N", "t": "Progressusque aliquantum, iuxta Addense municipium comperit, dissonas cultu et sermonum varietate, nationes plurimas unum spirantibus animis, immanium exordia concitare bellorum, adigente hortanteque maxima spe praemiorum, sorore Firmi nomine Cyria, quae abundans divitiis, et destinatione feminea, nisibus magnis instituit iuvare germanum.", "st": "29.5"}, {"sp": "N", "t": "Quocirca Theodosius veritus, ne Marti sese committeret impari, congressusque multitudini immensae cum paucis—tria enim armatorum milia ductabat atque quingentos—amitteret universos, inter pudorem cedendi, pugnandique ardorem, gradiens retro paulatim, trudente pondere plebis abscessit.", "st": "29.5"}, {"sp": "N", "t": "Hocque eventu barbari nimium quantum elati, sequentesque pertinaciter … certare necessitate compulsus semet ipsum et ad internecionem perdiderat cunctos, ni gentium turbulenta concussio, procul Mazicum visis auxiliis, quos anteibant quidam Romani, arbitrata in se impetum agminum ferri complurium, versa in pedes aperuisset nostris exitus antehac intersaeptos.", "st": "29.5"}, {"sp": "N", "t": "Exinde cum militem ducens incolumem Theodosius ad fundum venisset nomine Mazucanum, exustis desertoribus paucis, aliisque ad sagittariorum exemplum, quibus manus ademptae sunt, contruncatis, Tipasam mense Februario venit.", "st": "29.5"}, {"sp": "N", "t": "Ubi diutius agens, ut antiquus ille Cunctator pro negotio consultabat, commentis potius et prudentia quam periculosis congressibus, hostem pugnacem et impetrabilem iactu telorum, si fors copiam dederit, oppressurus.", "st": "29.5"}, {"sp": "N", "t": "Mittebat tamen assidue suadendi quosdam peritos, ad gentes circumsitas, Baiuras Cantaurianos Avastomates Cafaves Davaresque et finitimos alios, nunc timore nunc praemiis eos ad societatem alliciens, veniamque petulantiae interdum promittendo cum … t ulterius per ambages et moras hostem frangentem suos impetus oppressurus, ut quondam Pompeius Mithridatem.", "st": "29.5"}, {"sp": "N", "t": "Qua causa declinans perniciem proximam Firmus, licet praesidiorum magnitudine communitus, relicta plebe, quam coegerat magna mercede, quoniam latendi copiam nocturna quies dedit, Caprarienses montes longe remotos penetravit, et diruptis rupibus inaccessos.", "st": "29.5"}, {"sp": "N", "t": "Cuius abitu clandestine multitudo dispersa sine rectore particulatimque diffluens, invadendi eius castra nostris copiam dedit. Hisque direptis, et interfectis qui resistebant, vel in deditionem acceptis, regionum maxima parte vastata, gentibus per quas transibat dux consultissimus apposuit fidei compertae praefectos.", "st": "29.5"}, {"sp": "N", "t": "Hac inopina sequendi confidentia territus perduellis, servis comitantibus paucis, digressu celeri consulturus saluti, nequo praepediretur obstaculo, abiecit pretiosarum sarcinas specierum, quas avexerat secum. Uxorem namque fessam labore continuo et per ancipitis di …", "st": "29.5"}, {"sp": "N", "t": "Theodosius nullique adeuntium parcens, mundiore victu stipendioque milite recreato, Caprariensibus Abannisque eorum vicinis proelio levi sublatis, ad municipium properavit … ense: sed veris nuntiis doctus, barbaros occupasse iam tumulos, per anfracta undique spatia in sublime porrectos, nullique pervios nisi indigenis locorum perquam gnaris, repedando dedit hostibus facultatem, per indutias (licet breves) Aethiopum iuxta agentium adminiculis augeri vel maximis.", "st": "29.5"}, {"sp": "N", "t": "Qui concatervatis copiis fremituque minaci, sine sui respectu ruentes in pugnam, averterunt eum inaestimabilium turmarum specie dira perterrefactum, statimque redintegratis animis, commeatus vehens abunde, revertit, et conglobatis suis scutaque in formidabilem moventibus gestum, controversas eisdem opposuit manus.", "st": "29.5"}, {"sp": "N", "t": "Quamquam igitur immite quiddam barbaricis concrepantibus tubis, manipuli furentium imminebant, ipsi quoque parmas genibus illidentes, tamen ut pugnator ille cautus et prudens, militis paucitate diffisus, audacter agmine quadrato incedens, ad civitatem nomine Contensem flexit iter intrepidus, ubi captivos nostros Firmus ut in munimento abstruso locarat et celso; cunctisque receptis, in proditores satellitesque memorati animadvertit acriter (ut solebat).", "st": "29.5"}, {"sp": "N", "t": "Hoc ei magni numinis adiumento gerenti prosperrime, verus indicat explorator confugisse ad Isaflensium populum Firmum: ad quem reposcendum una cum fratre Mazuca, ceterisque necessitudinibus illuc ingressus, cum adipisci non posset, genti bellum indixit.", "st": "29.5"}, {"sp": "N", "t": "Et proelio atroci commisso, ferocientibus barbaris ultra modum, aciem rotundo habitu figuratam opponit, adeoque Isaflenses pondere catervarum urgentium inclinati sunt, ut plurimi caderent, et ipse Firmus ferox et saepe in suam perniciem praeceps equo auferretur in fugam, per saxa et rupes discurrere citius assueto, Mazuca vero frater eius caperetur letaliter saucius.", "st": "29.5"}, {"sp": "N", "t": "Qui Caesaream mitti dispositus, ubi saeva inusserat monumenta facinorum pessimorum, dilatato vulneris hiatu discessit. Caput tamen eius avulsum residue integro corpore, cum magno visentium gaudio urbi illatum est ante dictae.", "st": "29.5"}, {"sp": "N", "t": "Post haec Isaflensium gentem, quae obstitit, superatam dux nobilis incommodis multis (ut aequitas poscebat) afflixit. Ibi Evasium potentem municipem, Florumque eius filium, et quosdam alios per secretiora consilia temeratorem quietis iuvisse confutatos aperte, flammis absumpsit.", "st": "29.5"}, {"sp": "N", "t": "Exindeque pergens interius, nationem Iubalenam spiritu aggressus ingenti, ubi natum Nubelem patrem didicerat Firmi, repulsus altitudine montium et flexuosis angustiis, stetit. Et quamlibet facto in hostem impetu pluribusque peremptis aperuerit viam, formidans tamen sublimia collium ad insidiandum aptissima, ducens suos incolumes, revertit ad Audiense castellum: ubi Iesalensium gens fera semet dedidit voluntaria, auxilia praestare spondens et commeatus.", "st": "29.5"}, {"sp": "N", "t": "His et eius modi gloriosis actibus exsultans amplissimus ductor, ipsum otii turbatorem petebat valido virium nisu, ideoque prope munimentum nomine Medianum diu consistens, per multas prudentesque sententiarum vias eundem sibi prodi posse sperabat.", "st": "29.5"}, {"sp": "N", "t": "Haecque cogitationibus anxiis, altioreque prospiciens cura, rursus ad Isaflenses hostem comperit revertisse; quos nihil moratus, ut antea, agminibus adoritur incitatis. Cui rex Igmazen nomine spectatus per eos tractus opibusque insignis, progressus obviam confidenter: “Cuius loci es tu” inquit “vel quid acturus huc venisti? responde.” Quem Theodosius fundata mente intuens torvum: “Comes,” ait, “Valentiniani sum (orbis terrarum domini) ad opprimendum latronem funereum missus; quem nisi statim reddideris, ut invictus statuit imperator, peribis funditus cum gente quam regis.” Quo audito Igmazen post convicia multa, quae congessit in ducem, ira doloreque perculsus abscessit.", "st": "29.5"}, {"sp": "N", "t": "Et secutae principio lucis, utrimque occursurae sibi ad confligendum processerunt acies minacissimae, et barbarorum viginti paene milia in ipsis locata sunt frontibus, occultatis pone terga subsidialibus globis, ut assurgentes paulatim nostros multitudine clauderent insperata: hisque Iesalenses auxiliares accessere quam plures, quos adiumenta et commeatus nostris docuimus promisisse.", "st": "29.5"}, {"sp": "N", "t": "Contra Romani, quamvis admodum pauci, tamen fortibus animis, victoriisque antegressis elati, densetis lateribus, scutisque in testudinis formam cohaerenter aptatis, restiterunt gradibus fixis, et a sole orto usque ad diei extimum pugna protenta, paulo ante vesperam visus est Firmus, equo celsiori insidens, sago puniceo porrectius panso, milites clamoribus magnis hortari, ut dedant Theodosium opportune, truculentum eum appellans et dirum, et suppliciorum saevum repertorem, si discriminibus eximi vellent, quae perferebant.", "st": "29.5"}, {"sp": "N", "t": "Hae insperatae voces ad dimicandum quosdam acrius incitarunt, alios deserere proelium illexerunt. Proinde ubi noctis advenit quies prima, partibus tenebrarum obvolutis horrore, dux reversus ad Duodiense castellum, militesque recognoscens, eos quos a pugnandi proposito pavor et verba detorserant Firmi, diverso genere poenarum exstinxit: alios ademptis dexteris quosdam vivos combustos.", "st": "29.5"}, {"sp": "N", "t": "Excubiasque agens cura pervigili, barbarorum aliquos ausos, cum apparere non possent, post occasum lunae castra sua temptare effudit, vel irruentes audentius capit. Digressus exinde passibus citis, Iesalenses ut ambiguae fidei per tramites adortus obliquos undere parum sperari potuit) ad penuriam vastavit extremam, perque Caesariensis Mauritaniae oppida reversus Sitifim, Castorem et Martinianum rapinarum flagitiorumque Romani participes, ad interitum tortos incendit.", "st": "29.5"}, {"sp": "N", "t": "Redintegratur post haec cum Isaflensibus bellum, primoque conflictu barbarorum pluribus pulsis et interfectis, rex eorum Igmazen, vincere antehac assuetus, terrore fluctuans mali praesentis, nihilque commerciis vetitis ad vitam spei sibi restare, si obstinatius egerit, arbitratus, quantum caute fieri potuit et occulte, prorupit ex acie solus, visumque Theodosium suppliciter petit, ut Masillam Mazicum optimatem ad se venire iuberet.", "st": "29.5"}, {"sp": "N", "t": "Per quem (ut rogaverat) missum, clandestinis colloquiis monuit, ducem suopte ingenio pertinacem, ut ad praebendam sibi copiam agendi quae vellet, popularibus suis acriter immineret, eosque assiduitate pugnandi mutaret in metum, promptos quidem ad perduellis favorem sed iacturis multiplicibus fessos.", "st": "29.5"}, {"sp": "N", "t": "Paruit Theodosius dictis, et crebritate certaminum Isaflenses ita protrivit, ut eisdem labentibus pecudum ritu, Firmus ipse latenter evaderet, et aviis et diuturnis latebris amendandus, inibi dum de fuga consultat, tentus ab Igmazene custodiretur.", "st": "29.5"}, {"sp": "N", "t": "Et quoniam obscurius gesta didicerat per Masillam, in extremis rebus unum remedium superesse contemplans, calcare vivendi cupiditatem voluntaria statuit morte: vinoque consulto distentis et crapulatis, silenti nocte oppressis altiore somno custodibus, pervigil ipse impendentis aerumnae terrore, insonis gradibus relicto cubili, manibus repens et pedibus, longius sese discrevit, repertumque funiculum, quem ad finiendae vitae paraverat casus, de clavo parieti affixo suspendit, ubi collo inserto, animam absque mortis cruciabilibus exhalavit.", "st": "29.5"}, {"sp": "N", "t": "Quod dolenter ferens Igmazen, ereptamque sibi gloriam gemens, quia non contigerat ad castra Romana vivum ducere perduellem, interposita fide publica per Masillam, ipse camelo necati cadaver impositum ferens, cum tentoria exercitus adventaret, ad Subicarense castellum locata, in iumentum transtulit sarcinale, et Theodosio obtulit exultanti.", "st": "29.5"}, {"sp": "N", "t": "Qui convocatis armatis simul atque plebeiis, interrogatisque an agnoscerent vultum, cum eiusdem esse sine ulla didicisset ambage, ibi paulisper moratus, Sitifim triumphanti similis redit, aetatum ordinumque omnium celebrabili favore susceptus.", "st": "29.5"}, {"sp": "N", "t": "Dum hoc pulvere per Mauritaniam dux ante dictus anhelat et Africam, Quadorum natio mota est diu inexcita repentino, parum nunc formidanda, sed immensum quantum antehac bellatrix et potens, ut indicant properata quondam raptim proclivia, obsessaque ab eisdem Marcomannisque Aquileia, Opitergiumque excisum, et cruenta complura perceleri acta procinctu, vix resistente perruptis Alpibus Iuliis principe Pio, quem ante docuimus, Marco. Et erat (ut barbaris) ratio iusta querellarum.", "st": "29.6"}, {"sp": "N", "t": "Valentinianus enim studio muniendorum limitum glorioso quidem sed nimio, ab ipso principatus initio flagrans, trans flumen Histrum in ipsis Quadorum terris quasi Romano iuri iam vindicatis, aedificari praesidiaria castra mandavit: quod accolae ferentes indigne, suique cautiores, legatione tenus interim et susurris arcebant.", "st": "29.6"}, {"sp": "N", "t": "Sed Maximinus in omne avidus nefas, et genuinos mitigare nequiens flatus, quibus praefecturae accesserat tumor, increpabat Aequitium, per Illyricum eo tempore magistrum armorum, ut pervicacem et desidem, necdum opere, quod maturari dispositum est, consummate: addebatque ut consulens in commune, quod, si parvo suo Marcelliano deferretur potestas per Valeriam ducis, munimentum absque ulla causatione consurgeret.", "st": "29.6"}, {"sp": "N", "t": "Utrumque mox est impetratum. Qui promotus profectusque cum venisset ad loca, intempestive turgens ut filius, nullis affatibus delenitis his quos numquam temptatae cupiditatis figmenta regionum suarum faciebant extorres, opus paulo ante inchoatum aggreditur, admissa copia refragandi suspensum.", "st": "29.6"}, {"sp": "N", "t": "Denique Gabinium regem, nequid novaretur modeste poscentem, ut assensurus humanitate simulata cum aliis ad convivium corrogavit, quem digredientem post epulas, hospitalis officii sanctitate nefarie violata, trucidari securum fecit.", "st": "29.6"}, {"sp": "N", "t": "Cuius rei tam atrocis disseminatus rumor ilico per diversa et Quados et gentes circumsitas efferavit, regisque flentes interitum, in unum coactas misere vastatorias manus, quae Danubium transgressae, cum nihil exspectaretur hostile, occupatam circa messem agrestem, adortae sunt plebem, maioreque parte truncata, quicquid superfuit, domum cum multitudine varii pecoris abduxerunt.", "st": "29.6"}, {"sp": "N", "t": "Evenisset profecto tunc inexpiabile scelus, numerandum inter probrosas rei Romanae iacturas; paulo enim afuit, quin filia caperetur Constanti, cibum sumens in publica villa, quam appellant Pistrensem, cum duceretur Gratiano nuptura, ni favore propitii numinis, praesens Messalla, provinciae rector, eam iudiciali carpento impositam, ad Sirmium vicensimo sexto lapide disparatam, cursu reduxisset effuso.", "st": "29.6"}, {"sp": "N", "t": "Hoc casu prospero regia virgine periculo miserae servitutis exempta, cuius ni potuisset impetrari redemptio captae, magnas inussisset rei publicae clades, latius se cum Sarmatis Quadi pandentes, ad raptus et latrocinia gentes aptissimae, praedas hominum virile et muliebre secus agebant et pecorum, villarum cineribus exustarum, caesorumque incolentium exsultantes aerumnis, quos necopinantes sine ulla parsimonia deleverunt.", "st": "29.6"}, {"sp": "N", "t": "Per omnia itaque propinqua malorum similium dispersa formidine, praefectus praetorio agens tunc apud Sirmium Probus, nullis bellorum terroribus assuetus, rerum novarum lugubri visu praestrictus, oculosque vix attollens, haerebat, diu quid capesseret ambigens: et cum, paratis velocibus equis, noctem proximam destinasset in fugam, monitus tutiore consilio, mansit immobilis.", "st": "29.6"}, {"sp": "N", "t": "Didicerat enim omnes secuturos confestim, qui moenibus claudebantur, tegendos latebris opportunis: quod si contigisset, impropugnata civitas venisset in manus hostiles.", "st": "29.6"}, {"sp": "N", "t": "Proinde parumper lenito pavore, ad arripienda quae urgebant acri nisu adsurgens, retersit obrutas ruderibus fossas, murorumque maximam partem, pacis diuturnitate contemptam et subversam, ad usque celsarum turrium minas expediit, studio aedificandi coalitus: hac ratione opere velociter absolute, quod impensas aedificandi causa theatri, dudum congestas, sufficientis ad id quod efficere maturabat, invenit. Atque huic spectato consilio salutare addidit aliud, et sagittariorum cohortem e statione proxima, adfuturam obsidio (si venisset), accivit.", "st": "29.6"}, {"sp": "N", "t": "His velut obicibus, barbari ab oppugnanda urbe depulsi, parum ad has calliditates dimicandi sollertes, sarcinisque impediti praedarum, ad Aequitii vertuntur indaginem. Et cum ad Valeriae spatia longe remota secessisse raptorum didicissent indiciis, illuc properato petierant gradu, frendentes, hacque ex causa iugulo eius intenti, quod per ipsum circumventum regem existimabant insontem.", "st": "29.6"}, {"sp": "N", "t": "Quibus cognitis, cursu ruenti, infestius obviam legiones motae sunt duae, Pannonica et Moesiaca, valida proeliis manus: quae si conspirasset, abierat procul dubio victrix. Sed dum discretim grassatores adoriri festinant, ortis inter se discordiis impediti, de honore certabant et dignitate.", "st": "29.6"}, {"sp": "N", "t": "Quo intellecto, Sarmatae sagacissimi, non exspectato certandi signo sollemni, Moesiacam primam incessunt, dumque militias arma tardius per tumultum expediuntur, interfectis plurimis, aucti fiducia aciem perrupere Pannonicam, disiectaque agminis mole, geminatis ictibus omnem paene delessent, ni periculo mortis aliquos citum extraxisset effugium.", "st": "29.6"}, {"sp": "N", "t": "Inter haec fortunae dispendia tristioris, dux Moesiae Theodosius iunior, prima etiam tum lanugine iuvenis, princeps postea perspectissimus, Sarmatas Liberos ad discretionem servorum rebellium appellatos, collimitia nostra, ex alio latere invadentes, aliquotiens expulit et afflixit, congressibus densis attritos, adeoque obsistentes fortissime turbas confluentes oppressit, ut caesorum plurium alites iusta sagina satiaret et feras.", "st": "29.6"}, {"sp": "N", "t": "Unde residui, tumore iam deflagrante, metuentes ne idem dux virtutis (ut apparuit) expeditae, in primo finium aditu, incursantes cuneos sterneret aut fugaret, vel insidias per silvarum locaret occulta, post multos perrumpendi conatus subinde temptatos in cassum, abiecta pugnandi fiducia, concessionem petivere praeteritorum et veniam, victique ad tempus, indultae foederibus pacis nihil egere contrarium, eo maxime timore perculsi, quod ad tutelam Illyrici Gallicani militis validum accesserat robur.", "st": "29.6"}, {"sp": "N", "t": "Dum haec tot ac talia per turbines agitantur assiduos, Claudio regente urbem aeternam, Tiberis qui media intersecans moenia, cloacis et fluviis abundantibus multis, Tyrreno mari miscetur, effusione imbrium exuberans nimia, et supra amnis speciem pansus, omnia paene contexit.", "st": "29.6"}, {"sp": "N", "t": "Et stagnantibus civitatis residuis membris, quae tenduntur in planitiem molliorem, montes soli et quicquid insularum celsius eminebat, a praesenti metu defendebatur: et ne multi inedia contabescerent, undarum magnitudine nusquam progredi permittente, lembis et scaphis copia suggerebatur abunde ciborum. At vero ubi tempestas mollivit, et flumen retinaculis ruptis redit ad solitum cursum, absterso metu nihil postea molestius exspectabatur.", "st": "29.6"}, {"sp": "N", "t": "Hic ipse praefectus egit admodum quiete, nullam seditionem super querella iusta perpessus, et instauravit vetera plurima. Inter quae porticum excitavit ingentem, lavacro Agrippae contiguam, Eventus Boni cognominatam ea re quod huius numinis prope visitur templum.", "st": "29.6"}, {"sp": "HDR", "t": "Liber XXX", "st": "30"}, {"sp": "N", "t": "Inter has turbarum difficultates, quas perfidia ducis rege Quadorum excitavit occiso per scelus, dirum in Oriente committitur facinus, Papa Armeniorum rege clandestinis insidiis obtruncato: cuius materiae impio conceptae consilio hanc primordialem fuisse novimus causam.", "st": "30.1"}, {"sp": "N", "t": "Consarcinabant in hunc etiam tum adultum crimina quaedam apud Valentem exaggerentes male sollertes homines, dispendiis saepe communibus pasti. Inter quos erat Terentius dux demisse ambulans semperque submaestus, sed, quoad vixerat, acer dissensionum instinctor.", "st": "30.1"}, {"sp": "N", "t": "Qui adscitis in societatem gentilibus paucis, ob flagitia sua suspensis in metum, scribendo ad comitatum assidue, Cylacis necem replicabat et Artabanis, addens eundem iuvenem, ad superbos actus elatum, nimis esse in subiectos immanem.", "st": "30.1"}, {"sp": "N", "t": "Unde quasi futurus particeps suscipiendi tunc pro instantium rerum ratione tractatus, idem Papa regaliter vocatus, et apud Tarsum Ciliciae obsequiorum specie custoditus, cum neque ad imperatoris castra accipi nec urgentis adventus causam scire cunctis reticentibus posset, tandem secretiore indicio comperit, per litteras Romano rectori suadere Terentium, mittere prope diem alterum Armeniae regem, ne odio Papae, speque quod revertetur, natio nobis opportuna deficeret ad iura Persarum, eam rapere vi vel metu vel adulatione flagrantium.", "st": "30.1"}, {"sp": "N", "t": "Quae reputans ille, impendere sibi praesagibat exitium grave. Et doli iam prudens, neque aliam nisi cito discessu salutis reperiens viam, suadentibus his quibus fidebat, conglobatis trecentis comitibus, secutis eum e patria, cum equis velocissimis, ut in magnis solet dubiisque terroribus, audacter magis quam considerate pleraque diei parte emensa, egressus cuneatim, properabat intrepidus.", "st": "30.1"}, {"sp": "N", "t": "Cumque eum provinciae moderator, apparitoris qui portam tuebatur indicio percitus, festinato studio repperisset in suburbanis, ut remaneret enixius obsecrabat, et parum hoc impetrato, mortis aversus est metu.", "st": "30.1"}, {"sp": "N", "t": "Nec minus paulo postea legionem secutam, iamque adventantem ipse cum promptissimis retrorsus excurrens, fundensque in modum scintillarum sagittas, sed voluntate deerrans, ita in fugam compulit ut cum tribuno milites universi perterrefacti, vividius quam venerant remearent ad muros.", "st": "30.1"}, {"sp": "N", "t": "Exin solutus omni formidine, biduo et binoctio exanclatis itinerum laboribus magnis, cum ad flumen venisset Euphraten, et inopia navium, voraginosum amnem vado transire non posset, nandi imprudentia paventibus multis, ipse omnium maxime cunctabatur: et remansisset ni cunctis versantibus varia, id reperire potuisset effugium, in necessitatis abrupto tutissimum.", "st": "30.1"}, {"sp": "N", "t": "Lectulos in villis repertos binis utribus suffulserunt, quorum erat abundans prope in agris vinariis copia, quibus singulis proceres insidentes, et regulus ipse, iumenta trahentes, praeruptos undarum occursantium fluctus obliquatis meatibus declinabant: hocque commento tandem ad ulteriorem ripam post extrema discrimina pervenerunt.", "st": "30.1"}, {"sp": "N", "t": "Residui omnes, equis invecti natantibus, et circumluente flumine saepe demersi iactatique, infirmati periculoso madore, expelluntur ad contrarias margines, ubi paulisper refecti, expeditius quam diebus praeteritis incedebant.", "st": "30.1"}, {"sp": "N", "t": "Hoc nuntiato, princeps ante dicti fuga perculsus, quem elaqueatum fidem rupturum existimabat, cum sagittariis mille succinctis et levibus, Danielum mittit et Barzimerem, revocaturos eum -comitem unum, alterum scutariorum tribunum.", "st": "30.1"}, {"sp": "N", "t": "Hi locorum gnaritate confisi, quia ille properans ut peregrinus et insuetus, maeandros faciebat et gyros, compendiosis vallibus eius itinera praevenerunt, et divisis inter se copiis, clausere vias proximas duas, trium milium intervallo distinctas, ut transiturus per utramvis caperetur improvidus: sed evanuit cogitatum hoc casu.", "st": "30.1"}, {"sp": "N", "t": "Viator quidam ad citeriora festinans, cum clivum armato milite vidisset oppletum, per posterulam tramitem medium, squalentem frutectis et sentibus, vitabundus excedens, in Armenios incidit fessos, et ductus ad regem, arcano sermone solum quae viderat docet, ac retinetur intactus.", "st": "30.1"}, {"sp": "N", "t": "Moxque metu dissimulato, eques mittitur clandestinus ad dextrum itineris latus, diversoria paraturus et cibum, quo paulum progresso, in laevum tractum item alius talia facturus ire iubetur ocissime, alterum aliorsum nesciens missum.", "st": "30.1"}, {"sp": "N", "t": "Quibus ita utiliter ordinatis, rex ipse cum suis, dumeta per quae venerat viatore relegente retrorsus, monstranteque hispidam et iumento onusto exiguam callem, post terga relictis militibus evolavit, qui captis eius ministris, missis ad mentes observantium praestringendas, quasi venaticiam praedam, modo non porrectis brachiis exspectabant. Dumque hi venturum operiuntur, ille regno incolumis restitutus, et cum gaudio popularium summo susceptus, fide pari deinde mansit immobilis, iniuriis quas pertulerat omnibus demussatis.", "st": "30.1"}, {"sp": "N", "t": "Danielus post haec et Barzimeres, cum lusi iam revertissent, probrosis lacerati conviciis, ac si inertes et desides, ut hebetatae primo appetitu venenatae serpentes, ora exacuere letalia, cum primum potuissent, lapso pro virium copia nocituri.", "st": "30.1"}, {"sp": "N", "t": "Et leniendi causa flagitii sui vel fraudis, quam meliore consilio pertulerunt, apud imperatoris aures (rumorum omnium tenacissimas) incessebant falsis criminibus Papam, incentiones Circeas, in vertendis debilitandisque corporibus, miris modis eum callere fingentes: addentesque quod huius modi artibus, offusa sibi caligine, mutata sua suorumque forma transgressus, tristes sollicitudines (si huic irrisioni superfuerit) excitabit.", "st": "30.1"}, {"sp": "N", "t": "Hinc in illum inexpiabile auctum principis odium, et doli struebantur in dies, ut per vim ei vel clam vita adimeretur: agentique tune in Armenia Traiano, et rem militarem curanti, id secretis committitur scriptis.", "st": "30.1"}, {"sp": "N", "t": "Qui illecebrosis regem insidiis ambiens, et modo serenae mentis Valentis indices litteras tradens, modo ipse sese eius conviviis ingerens, ad ultimum composita fraude, ad prandium verecundius invitavit: qui nihil adversum metuens venit, concessoque honoratiore discubuit loco.", "st": "30.1"}, {"sp": "N", "t": "Cumque apponerentur exquisitae cuppediae, et aedes amplae nervorum et articulate flatilique sonitu resultarent, iam vino incalescente ipso convivii domino, per simulationem naturalis cuiusdam urgentis egresso, gladium destrictum intentans, torvo lumine ferociens quidam immittitur barbarus asper, ex his quos scurras appellant, confossurus iuvenem, ne exsilire posset etiam tum praepeditum.", "st": "30.1"}, {"sp": "N", "t": "Quo viso regulus forte prominens ultra torum, expedito dolone, adsurgens ut vitam omni ratione defenderet, perforato pectore deformis procubuit victima, multiplicatis ictibus foede concisa.", "st": "30.1"}, {"sp": "N", "t": "Hocque figmento nefarie decepta credulitate, inter epulas quae reverendae sunt vel in Euxino ponto, hospitali numine contuente, peregrinus cruor in ambitiosa lintea conspersus spumante sanie satietati superfuit convivarum, horrore maximo dispersorum. Ingemiscat, siquis vita digressis est dolor, huius arrogantiam facti Fabricius ille Luscinus, sciens qua animi magnitudine Democharen, vel (ut quidam scribunt) Niciam, ministrum reppulerit regium, colloquio occultiore pollicitum, quod Pyrrum Italiam tune bellis saevissimis exurentem, veneno poculis necabit infectis, scripseritque ad regem, ut a citeriore caveret obsequio. Tantum reverentiae locum apud priscam illam iustitiam vel hostilis mensae genialitas obtinebat.", "st": "30.1"}, {"sp": "N", "t": "Verum excusabatur recens inusitatum facinus et pudendum, necis exemplo Sertorianae, adulatoribus forsitan ignorantibus, quod (ut Demosthenes, perpetuum Graeciae decus, affirmat) numquam similitudine aut impunitate alterius criminis diluitur id quod contra ac liceat arguitur factum.", "st": "30.1"}, {"sp": "N", "t": "Haec per Armeniam notabiliter gesta sunt. Sapor vero post suorum pristinam cladem, comperto interitu Papae, quem sociare sibi impendio conabatur, maerore gravi perculsus, augenteque nostri exercitus alacritate formidinem, maiora sibi praeseminans,", "st": "30.2"}, {"sp": "N", "t": "Arsace legato ad principem misso, perpetuam aerumnarum causam deseri penitus suadebat Armeniam: si id displicuisset, aliud poscens, ut Hiberiae divisione cessante, remotisque inde partis Romanae praesidiis, Aspacures solus regnare permitteretur, quem ipse praefecerat genti.", "st": "30.2"}, {"sp": "N", "t": "Ad quae Valens in hanc respondit sententiam, nihil derogare se posse placitis ex consensu firmatis, sed ea studio curatiore defendere. Glorioso proposito contrariae regis litterae hieme iam extrema perlatae sunt, vana causantis et tumida. adseverabat enim non posse semina radicitus amputari discordiarum, nisi intervenissent conscii pacis foederatae cum Ioviano, quorum aliquos vita didicerat abscessisse.", "st": "30.2"}, {"sp": "N", "t": "Ingravescente post haec altius cura, imperator eligere consilia quam invenire sufficiens, id conducere rebus existimans, Victorem magistrum equitum et Urbicium, Mesopotamiae ducem, ire propere iussit in Persas, responsum absolutum et unius modi perferentes: quod rex iustus et suo contentus, ut iactitabat, sceleste concupiscat Armeniam, ad arbitrium suum vivere cultoribus eius permissis: et ni Sauromaci praesidia militum impertita principio sequentis anni (ut dispositum est) impraepedita reverterint, invitus ea complebit, quae sponte sua facere supersedit.", "st": "30.2"}, {"sp": "N", "t": "Quae legatio recta quidem et libera, ni deviasset in eo, quod absque mandatis, oblatas sibi regiones in eadem Armenia suscepit exiguas.", "st": "30.2"}, {"sp": "N", "t": "Qua regressa advenit Surena potestatis secundae post regem, has easdem imperatori offerens partes, quas audacter nostri sumpsere legati.", "st": "30.2"}, {"sp": "N", "t": "Quo suscepto liberaliter et magnifice, sed parum impetrato, quod poscebat, remisso, parabantur magna instrumenta bellorum, ut mollita hieme imperatore trinis agminibus perrupturo Persidem, ideoque Scytharum auxilia festina celeritate mercante.", "st": "30.2"}, {"sp": "N", "t": "Proinde parum adeptus ea quae spe vana conceperat, Sapor, ultraque solitum asperatus, quod ad expeditionem accingi rectorem compererat nostrum: iram eius conculcans Surenae dedit negotium, ut ea, quae Victor comes susceperat et Urbicius, armis repeteret, si quisquam repugnaret, et milites Sauromacis praesidio destinati malis affligerentur extremis.", "st": "30.2"}, {"sp": "N", "t": "Haecque (ut statuerat) maturata confestim, nec emendari potuerunt nec vindicari, quia rem Romanam alius circumsteterat metus, totius Gothiae Thracias licentius perrumpentis: quae funera tunc explicari poterunt carptim, si ad ea quoque venerimus.", "st": "30.2"}, {"sp": "N", "t": "Haec per eoos agitata sunt tractus. Quorum inter seriem Africanas clades et legatorum Tripoleos manes, inultos etiam tum et errantes, sempiternus vindicavit Iustitiae vigor, aliquotiens serus, sed scrupulosus quaesitor gestorum recte vel secius, hoc modo.", "st": "30.2"}, {"sp": "N", "t": "Remigius (quem populanti provincias rettulimus comiti favisse Romano), postquam Leo in eius locum magister esse coepit officiorum, a muneribus rei publicae iam quiescens, negotiis se ruralibus dedit prope Mogontiacum in genitalibus locis.", "st": "30.2"}, {"sp": "N", "t": "Quem ibi morantem securius, praefectus praetorio Maximinus reversum ad otium spernens, ut solebat dirae luis ritu grassari per omnia, laedere modis quibus poterat affectabat: utque rimaretur plura quae latebant, Caesarium antehac eius domesticum, postea notarium principis, raptum, quae Remigius egerit, vel quantum acceperit, ut Romani iuvaret actus infandos, per quaestionem cruentam interrogabat.", "st": "30.2"}, {"sp": "N", "t": "Quibus ille cognitis, cum esset (ut dictum est) in secessu, conscientia malorum urgente, vel rationem formidine superante calumniarum, innodato gutture laquei nexibus interiit.", "st": "30.2"}, {"sp": "N", "t": "Secuto post haec anno Gratiano asscito in trabeae societatem Aequitio consule, Valentiniano post vastatos aliquos Alamanniae pagos, munimentum aedificanti prope Basiliam, quod appellant accolae Robur, offertur praefecti relatio Probi, docentis Illyrici clades.", "st": "30.3"}, {"sp": "N", "t": "Quibus ille ut cunctatorem decuerat ducem, examinatius lectis, attonitus cogitationibus anxiis, Paterniano notario misso, negotium scrupulosa quaesivit indagine, moxque veris per eum nuntiis gestorum acceptis, evolare protinus festinarat, ausos temerare limitem barbaros, primo fragore (ut mente conceperat), oppressurus armorum.", "st": "30.3"}, {"sp": "N", "t": "Quia igitur abeunte autumno multa impediebant et aspera, annitebantur omnes per regiam optimates, ut ad usque veris principium oratum retinerent et exoratum: primum durata pruinis itinera, ubi nec adultae in pastum herbae reperirentur, nec cetera usui congrua, penetrari non posse firmantes: dein vicinorum Galliis regum immanitatem, maximeque omnium Macriani, ut formidati, tunc praetendentes, quem constabat impacatum relictum etiam ipsa urbium moenia temptaturum.", "st": "30.3"}, {"sp": "N", "t": "Haec memorantes, addentesque utilia, reduxere eum in meliorem sententiam, statimque (ut conducebat rei communi), prope Mogontiacum blandius rex ante dictus accitur, proclivis ipse quoque ad excipiendum foedus (ut apparebat). Et venit immane quo quantoque flatu distentus, ut futurus arbiter superior pacis, dieque praedicto colloquii ad ipsam marginem Rheni, caput altius erigens, stetit hinc inde sonitu scutorum intonante gentilium.", "st": "30.3"}, {"sp": "N", "t": "Contra Augustus escensis amnicis lembis, saeptus ipse quoque multitudine castrensium ordinum, tutius prope ripas accessit, signorum fulgentium nitore conspicuus, et immodestis gestibus murmureque barbarico tandem sedato, post dicta et audita ultro citroque versus, amicitia media sacramenti fide firmatur.", "st": "30.3"}, {"sp": "N", "t": "Hisque perfectis, discessit turbarum rex artifex delenitus, futurus nobis deinceps socius, et dedit postea ad usque vitae tempus extremum, constantis in concordiam animi facinorum documentum pulchrorum.", "st": "30.3"}, {"sp": "N", "t": "Periit autem in Francia postea, quam dum internecive vastando perrupit avidius, oppetit, Mallobaudis bellicosi regis insidiis circumventus. Post foedus tamen sollemni ritu impletum, Treveros Valentinianus ad hiberna discessit.", "st": "30.3"}, {"sp": "N", "t": "Haec per Gallias et latus agebantur arctoum. At in eois partibus alto externorum silentio, intestina pernicies augebatur, per Valentis amicos et proximos, apud quos honestate utilitas erat antiquior. Navabatur enim opera diligens, ut homo rigidus audire cupiens lites, a studio iudicandi revocaretur, metu ne ita ut Iuliani temporibus, defensione innocentiae respirante, frangeretur potentium tumor, assumpta licentia latius solitus evagari.", "st": "30.4"}, {"sp": "N", "t": "Ob haec et similia, concordi consensu dehortantibus multis, maximeque Modesto, praefecto praetorio, regiorum arbitrio spadonum exposito, et subagreste ingenium, nullis vetustatis lectionibus expolitum, coacto vultu fallente, et asserente, quod infra imperiale columen causarum essent minutiae privatarum; ille ad humilitandam celsitudinem potestatis negotiorum examina spectanda instituta esse arbitratus (ut monebat), abstinuit penitus, laxavitque rapinarum fores quae roborabantur in dies, iudicum advocatorumque pravitate sentientium paria, qui tenuiorum negotia militaris rei rectoribus, vel intra palatium validis venditantes, aut opes aut honores quaesivere praeclaros.", "st": "30.4"}, {"sp": "N", "t": "Hanc professionem oratorum forensium, πολιτικῆς μορίου εἴδωλον (id est civilitatis particulae umbram) vel adulationis partem quartam esse definit amplitudo Platonis, Epicurus autem κακοτεχνίαν nominans inter artes numerat malas. Tisias suasionis opificem esse memorat assentiente Leontino Gorgia.", "st": "30.4"}, {"sp": "N", "t": "Quam a veteribus ita determinatam, orientalium quorundam versutia ad usque bonorum extulit odium, unde etiam retinaculis temporis praestituti frenatur. Ergo absolutis super eius indignitate perpaucis, quam in illis partibus agens expertus sum, ad coeptorum cursum regrediar institutum.", "st": "30.4"}, {"sp": "N", "t": "Florebant elegantiae priscae patrociniis tribunalia, cum oratores concitae facundiae, attenti studiis doctrinarum, ingenio fide copiis ornamentisque dicendi pluribus eminebant, ut Demosthenes, quo dicturo concursus audiendi causa ex tota Graecia fieri solitos monumentis Atticis continetur, et Callistratus, quem nobilem illam super Oropo causam (qui locus in Euboea est) perorantem, idem Demosthenes, Academia cum Platone relicta, sectatus est: ut Hyperides et Aeschines et Andocides et Dinarchus et Antiphon ille Rhamnusius, quem ob defensum negotium omnium primum antiquitas prodidit accepisse mercedem.", "st": "30.4"}, {"sp": "N", "t": "Nec minus apud Romanos, Rutilii et Galbae et Scauri vita moribus frugalitateque spectati, et postea per varias aevi sequentis aetates, censorii et consulares multi et triumphales, Crassi et Antonii et cum Philippis Scaevolae aliique numerosi, post exercitus prosperrime ductos, post victorias et tropaea, civilibus stipendiorum officiis floruerunt, laureasque fori speciosis certaminibus occupantes, summis gloriae honoribus fruebantur.", "st": "30.4"}, {"sp": "N", "t": "Post quos excellentissimus omnium Cicero, orationis imperiosae fluminibus saepe depresses aliquos iudiciorum eripiens flammis, “Non defendi homines sine vituperatione fortasse posse, neglegenter defendi sine scelere non posse” firmabat.", "st": "30.4"}, {"sp": "N", "t": "At nunc videre est per eoos omnes tractus violenta et rapacissima genera hominum, per fora omnia volitantium, et subsidentium divites domus, ut Spartanos canes aut Cretas, vestigia sagacius colligendo, ad ipsa cubilia pervenire causarum.", "st": "30.4"}, {"sp": "N", "t": "In his primus est coetus eorum, qui seminando diversa iurgia per vadimonia mille iactantur, viduarum postes et orborum limina deterentes, et aut inter discordantes amicos, aut propinquantes, vel affines, si simultatum levia senserint receptacula, odia struentes infesta: in quibus aetatis progressu non ut aliorum vitia intepescunt, sed magis magisque roborantur: inter rapinas insatiabiles inopes, ad capiendam versutis orationibus iudicum fidem, quorum nomen ex iustitia natum est, sicam ingenii destringentes.", "st": "30.4"}, {"sp": "N", "t": "Horum obstinatione libertatem temeritas, constantiam audacia praeceps, eloquentiam inanis quaedam imitatur affluentia loquendi: quarum artium scaevitate, ut Tullius asseverat, nefas est religionem decipi iudicantis. Ait enim “Cumque nihil tam incorruptum esse debeat in re publica quam suffragium, quam sententia, non intellego cur qui ea pecunia corruperit, poena dignus sit: qui eloquentia, laudem etiam ferat. Mihi quidem hoc plus mali facere videtur, qui oratione, quam qui pretio iudicem corrumpit: quod pecunia corrumpere prudentem nemo potest, dicendo potest.”", "st": "30.4"}, {"sp": "N", "t": "Secundum est genus eorum, qui iuris professi scientiam, quam repugnantium sibi legum abolevere discidia, velut vinculis ori impositis reticentes, iugi silentio umbrarum sunt similes propriarum. Hi velut fata natalicia praemonstrantes, aut Sibyllae oraculorum interpretes, vultus gravitate ad habitum composita tristiorem, ipsum quoque venditant, quod oscitantur.", "st": "30.4"}, {"sp": "N", "t": "Hi ut altius videantur iura callere, Trebatium loquuntur et Cascellium et Alfenum, et Auruncorum Sicanorumque iam diu leges ignotas, cum Evandri matre abhinc saeculis obrutas multis. Et si voluntate matrem tuam finxeris occidisse, multas tibi suffragari absolutionem lectiones reconditas pollicentur, si te senserint esse nummatum.", "st": "30.4"}, {"sp": "N", "t": "Tertius eorum est ordo, qui ut in professione turbulenta clarescant, ad expugnandam veritatem ora mercenaria procudentes, per prostitutas frontes vilesque latratus, quo velint aditus sibi patefaciunt crebros: qui inter sollicitudines iudicum per multa distentas, irresolubili nexu vincientes negotia, laborant, ut omnis quies litibus implicetur, et nodosis quaestionibus de industria iudicia circumscribunt, quae cum recte procedunt, delubra sunt aequitatis: cum depravantur, foveae fallaces et caecae: in quas si captus ceciderit quisquam, non nisi per multa exsiliet lustra, ad usque ipsas medullas exsuctus.", "st": "30.4"}, {"sp": "N", "t": "Quartum atque postremum est genus impudens, pervicax et indoctum, eorum qui cum immature a litterariis eruperint ludis, per angulos civitatum discurrunt, mimiambos non causarum remediis congrua commentantes, fores divitum deterendo, cenarum ciborumque aucupantes delicias exquisitas.", "st": "30.4"}, {"sp": "N", "t": "Qui cum semel umbraticis lucris, et inhiandae undique pecuniae sese dediderint, litigare frustra quoslibet innocentes hortantur, et ad defendendam causam admissi, quod raro contingit, suscepti nomen et vim negotii sub ore disceptatoris inter ipsos conflictuum articulos instruuntur, circumlocutionibus indigestis ita scatentes, ut in colluvione taeterrima audire existimes ululabili clamore Thersiten.", "st": "30.4"}, {"sp": "N", "t": "Cum autem ad inopiam muniendarum venerint allegationum, ad effrenatam deflectunt conviciandi licentiam: quo nomine ob assidua in personas honorabiles probra, diebus dictis aliquotiens sunt damnati, e quibus ita sunt rudes non nulli, ut numquam se codices habuisse meminerint.", "st": "30.4"}, {"sp": "N", "t": "Et si in circulo doctorum auctoris veteris inciderit nomen, piscis aut edulii peregrinum esse vocabulum arbitrantur: si vero advena quisquam inusitatum sibi antea Marcianum (verbo tenus) quaesierit oratorem, omnes confestim Marcianos appellari se fingunt.", "st": "30.4"}, {"sp": "N", "t": "Nec iam fas ullum prae oculis habent, sed tamquam avaritiae venundati et usucapti, nihil praeter interminatam petendi licentiam norunt. Et siquem semel intra retia ceperint, cassibus mille impedicant, per morborum simulationem vicissim consulto cessantes: utque pervulgati iuris proferatur lectio vana, septem vendibiles introitus praeparant, dilationum examina longissima contexentes.", "st": "30.4"}, {"sp": "N", "t": "Et cum nudatis litigatoribus dies cesserint et menses et anni, tandem obtrita vetustate controversia intromissa, ipsa capita splendoris ingressa, alia secum advocatorum simulacra inducunt. Cumque intra cancellorum venerint saepta, et agi coeperint alicuius fortunae vel salus, atque laborari debeat ut ab insonte gladius vel calamitosa detrimenta pellantur, corrugatis hinc inde frontibus brachiisque histrionico gestu formatis, ut contionaria Gracchi fistula sola post occipitium desit, consistitur altrinsecus diu: tandemque ex praemeditato colludio, per eum qui est in verba fidentior, suave quoddam principium dicendi exoritur, Cluentianae vel pro Ctesiphonte orationum aemula ornamenta promittens: et in eam conclusionem cunctis finem cupientibus desinit, ut nondum se patroni post speciem litis triennium editam causentur instructos, spatioque prorogati temporis impetrato, quasi cum Antaeo vetere colluctati, perseveranter flagitant pulveris periculosi mercedes.", "st": "30.4"}, {"sp": "N", "t": "Verum tamen haec cum ita sint, non desunt advocatis incommoda plurima, parum sustinenda recte victuro. Namque sellulariis quaestibus inescati, inter se hostiliter dissident, et abrupta maledicendi ferocia (ut dictum est) multos offendunt: quam tunc effutiunt, cum commissarum sibi causarum infirmitatem rationibus validis convallare non possunt.", "st": "30.4"}, {"sp": "N", "t": "Et iudices patiuntur interdum doctos ex Philistionis aut Aesopi cavillationibus, quam ex Aristidis illius Iusti vel Catonis disciplina productos: qui aere gravi mercati publicas potestates, ut creditores molesti, opes cuiusque modi fortunae rimantes, alienis gremiis excutiunt praedas.", "st": "30.4"}, {"sp": "N", "t": "Ad ultimum id habet causidicina cum ceteris metuendum et grave, quod hoc ingenitum est paene litigantibus cunctis, ut cum iurgia mille casibus cadant, accidentia secus in potestate esse existiment patronorum, et omnem certaminum exitum eisdem soleant assignare, et non vitiis rerum, aut iniquitati aliquotiens disceptantium, sed solis defensantibus irascantur. Verum unde huc declinavimus, revertamur.", "st": "30.4"}, {"sp": "N", "t": "Pubescente iam vere, Valentinianus a Treveris motus, per nota itinera gradu celeri contendebat, eique regiones adventanti quas petebat, legatio Sarmatarum offertur: pedibusque eius prostrata, orabat pacifica prece, ut propitius veniret et lenis, nullius diri facinoris participes popularis suos inventurus aut conscios.", "st": "30.5"}, {"sp": "N", "t": "Quibus saepe eadem iterantibus, hactenus perpensa deliberatione respondit, haec in locis ubi dicuntur admissa, quaerenda verissimis documentis et vindicanda. Cumque exinde Carnuntum Illyriorum oppidum introisset, desertum quidem nunc et squalens, sed ductori exercitus perquam opportunum, ubi fors copiam dedisset aut ratio, e statione proxima reprimebat barbaricos appetitus.", "st": "30.5"}, {"sp": "N", "t": "Et quamquam terrori cunctis erat dum sperabatur, ut acer et vehemens, mox iudices damnari iussurus, quorum perfidia vel secessione Pannoniarum nudatum est latus: cum illuc venisset, ita intepuit, ut neque in Gabinii regis inquireret necem, necque inusta rei publicae vulnera, quo sinente vel agente segnius evenissent, curatius vestigaret: eo videlicet more, quo erat severus in gregariis corrigendis, remissior erga maiores fortunas vel verbis asperioribus incessendas.", "st": "30.5"}, {"sp": "N", "t": "Solum tamen incitato petebat odio Probum, numquam ex quo eum viderat minari desinens vel mitescens: cuius rei causae nec obscurae fuerunt nec leves. Hic praefecturam praetorio non tunc primitus nanctus, eamque multis atque utinam probabilibus modis, in longum proferre gestiens, non ut prosapiae suae claritudo monebat, plus adulationi quam verecundiae dedit.", "st": "30.5"}, {"sp": "N", "t": "Contemplatus enim propositum principis, quaerendae undique pecuniae vias absque iustorum iniustorumque discretione scrutantis, errantem non reducebat ad aequitatis tramitem (ut saepe moderatores fecere tranquilli) sed ipse quoque flexibilem sequebatur atque transversum.", "st": "30.5"}, {"sp": "N", "t": "Unde graves oboedientium casus, et exitialia provisorum nomina titulorum, iuxta opulentas et tenues enervatas succidere fortunas, argumentis aliis post alia validioribus, usu laedendi reperiente longaevo. Denique per tributorum onera vectigaliumque augmenta multiplicata, optimatum quosdam ultimorum metu exagitatos, mutare compulit sedes, et flagitantium ministrorum amaritudine quidam expressi, cum non suppeteret quod daretur, erant perpetui carcerum inquilini: e quibus aliquos, cum vitae iam taederet et lucis, suspendiorum exoptata remedia consumpserunt.", "st": "30.5"}, {"sp": "N", "t": "Haec ita illecebrosius atque inhumanius agi loquebatur quidem pertinax rumor; Valentinianus vero tamquam auribus cera illitis ignorabat, indifferenter quidem lucrandi vel ex rebus minimis avidus, idque tantum cogitans quod offerebatur, parsurus tamen fortasse Pannoniis, si haec ante ingemiscenda compendia comperisset, quae nimium sero tali didicit casu.", "st": "30.5"}, {"sp": "N", "t": "Ad provincialium residuorum exemplum, etiam Epirotae acturos sibi gratias a praefecto mittere compulsi legatos, Iphiclem quendam philosophum, spectatum robore pectoris hominem, adegere (non sponte propria) pergere ad id munus implendum.", "st": "30.5"}, {"sp": "N", "t": "Qui cum imperatorem vidisset, agnitus adventusque sui causam interrogatus, Graece respondit, atque ut philosophus veritatis professor, quaerente curatius principe, si hi qui misere ex animo bene sentiunt de praefecto, “gementes,” inquit, “et inviti.”", "st": "30.5"}, {"sp": "N", "t": "Quo ille verbo tamquam telo perculsus, actus eius ut sagax bestia rimabatur, genuino percunctando sermone quos noscitabat, ubinam ille esset (verbi gratia) honore suos antecellens et nomine, vel ille dives, aut alius ordinis primus. Cumque disceret perisse aliquem laqueo, abisse alium trans mare, conscivisse sibi alium mortem aut plumbo vita erepta exstinctum, in immensum excanduit, urente irarum nutrimenta tunc officiorum magistro Leone (pro nefas!) ipso quoque praefecturam, ut e celsiore scopulo caderet, affectante: quam si adeptus rexisset, prae his quae erat ausurus, administratio Probi ferebatur in caelum.", "st": "30.5"}, {"sp": "N", "t": "Agens itaque apud Carnuntum imperator per continuos tres menses aestivos arma parabat et alimenta, siqua fors secundasset, pervasurus opportune Quados, tumultus atrocis auctores; in quo oppido Faustinus, filius sororis Viventii praefecti praetorio, notarius militans, Probo spectante negotium, carnificis manu peremptus est post tormenta, vocatus in crimen, quod asinum occidisse dicebatur ad usum artium secretarum, ut asserebant quidam urgentes; ut autem aiebat ille ad imbecillitatem firmandam fluentium capillorum.", "st": "30.5"}, {"sp": "N", "t": "Alio quoque in eum perniciose composito, quod petenti per iocum cuidam Nigrino, ut eum notarium faceret, exclamavit ille hominem ridens: “Fac me imperatorem, si id volueris impetrare.” Hocque ludibrio inique interpretato, et Faustinus ipse et Nigrinus et alii sunt interfecti.", "st": "30.5"}, {"sp": "N", "t": "Praemisso igitur Merobaude cum militari peditum manu, quam regebat, ad vastandos cremandosque barbaricos pagos, comite adiuncto Sebastiano, Valentinianus Acincum propere castra commovit, navigiisque ad repentinum casum coniunctis, et contabulato celeri studio ponte, per partem aliam transiit in Quados, speculantes quidem ex diruptis montibus eius adventum, quo plerique ancipites, incertique accidentium, cum suis caritatibus secesserunt: sed stupore defixos, cum in regionibus suis, contra quam opinabantur, augusta cernerent signa.", "st": "30.5"}, {"sp": "N", "t": "Progressus ergo coacto gradu in quantum res tulit, iugulataque aetate promiscua, quam etiam tum palantem subitus occupavit excursus, et tectis combustis, redit cum incolumibus cunctis, quos duxerat secum, itidemque apud Acincum moratus, autumno praecipiti, per tractus conglaciari frigoribus assuetos, commoda quaerebat hiberna, nullaque sedes idonea reperiri praeter Savariam poterat, quamvis eo invalidam tempore, assiduisque malis afflictam.", "st": "30.5"}, {"sp": "N", "t": "Unde hoc, etiam si magni intererat, paulisper sequestrate, impigre motus, peragrata fluminis ripa, castrisque praesidio competenti munitis atque castellis, Bregitionem pervenit, ibique diu compositum ad quietem principis fatum sortem denuntiabat ei supremam, prodigiis ingerentibus multis.", "st": "30.5"}, {"sp": "N", "t": "Namque diebus ante paucissimis, ruinas fortunarum indicantia celsarum, arsere crinita sidera cometarum, quorum originem supra docuimus. Ante apud Sirmium repentino fragore nubium fulmen excussum, palatii et curiae partem incendit et fori, et apud Savariam eodem adhuc constitute, bubo culminibus regii lavacri insidens, occentansque funebria, nulla iacientium sagittas et lapides contemplabili dextera cadere potuit, certatim licet ardenti studio petebatur.", "st": "30.5"}, {"sp": "N", "t": "Item cum ab urbe praedicta tenderet ad procinctum, per portam voluit unde introiit exire, ut omen colligeret, quod cite remeabit ad Gallias. Dumque locus aggestis ruderibus neglectus purgatur, lapsam forem ferratam, quae exitum obseravit, multitudo removere non potuit, viribus magnis enisa, et ille ne frustra tereret diem, coactus per aliam egressus est portam.", "st": "30.5"}, {"sp": "N", "t": "Nocteque quam lux ereptura eum vita secuta est (ut per quietem solet) videbat coniugem suam absentem, sedere passis capillis, amictu squalenti contectam: quam aestimari dabatur Fortunam eius esse, cum taetro habitu iam discessuram.", "st": "30.5"}, {"sp": "N", "t": "Progressus deinde matutinus, contractiore vultu subtristis, cum eum oblatus non susciperet equus, anteriores pedes praeter morem erigens in sublime, innata feritate concitus, ut erat immanis, dexteram stratoris militis iussit abscidi, quae eum insilientem iumento fulserat consuete: perissetque cruciabiliter innocens iuvenis, ni tribunus stabuli Cerealis dirum nefas cum sui periculo distulisset.", "st": "30.5"}, {"sp": "N", "t": "Post haec Quadorum venere legati, pacem cum praeteritorum oblitteratione, suppliciter obsecrantes, quam ut adipisci sine obstaculo possent, et tirocinium et quaedam utilia rei Romanae pollicebantur.", "st": "30.6"}, {"sp": "N", "t": "Quos quoniam suscipi placuit, et redire indutiis, quae poscebantur, indultis, quippe eos vexari diutius, nec ciborum inopia, nec alienum tempus anni patiebantur, in consistorium, Aequitio suadente, sunt intromissi. Cumque membris incurvatis starent metu debiles et praestricti, docere iussi quae ferebant, usitatas illas causationum species iurandi fidem addendo firmabant; nihil ex communi mente procerum gentis delictum asseverantes in nostros, sed per extimos quosdam latrones, amnique confines evenisse, quae inciviliter gesta sunt, etiam id quoque addendo, ut sufficiens ad facta purganda firmantes, quod munimentum extrui coeptum nec iuste nec opportune ad ferociam animos agrestes accendit.", "st": "30.6"}, {"sp": "N", "t": "Ad haec imperator, ira vehementi perculsus, et inter exordia respondendi tumidior, increpabat verborum obiurgatorio sonu nationem omnem ut beneficiorum immemorem et ingratam. Paulatimque lenitus, et ad molliora propensior, tamquam ictus e caelo, vitalique via voceque simul obstructa, suffectus igneo lumine cernebatur; et repente cohibito sanguine, letali sudore perfusus, ne laberetur spectantibus multis et vilibus, concursu ministrorum vitae secretioris ad conclave ductus est intimum.", "st": "30.6"}, {"sp": "N", "t": "Ubi locatus in lecto, exiguas spiritus reliquias trahens, nondum intellegendi minuto vigore, cunctos agnoscebat adstantes, quos cubicularii, nequis eum necatum suspicaretur, celeritate maxima corrogarant. Et quoniam viscerum flagrante compage, laxanda erat necessario vena, nullus inveniri potuit medicus, hanc ob causam quod eos per varia sparserat, curaturos militem pestilentiae morbo temptatum.", "st": "30.6"}, {"sp": "N", "t": "Unus tamen repertus, venam eius iterum saepiusque pungendo, ne guttam quidem cruoris elicere potuit, internis nimietate calorum ambustis, vel (ut quidam existimabant), arefactis ideo membris, quod meatus aliqui (quos haemorrhoidas nunc appellamus), obserati sunt gelidis frigoribus concrustati.", "st": "30.6"}, {"sp": "N", "t": "Sensit immensa vi quadam urgente morborum, ultimae necessitatis adesse praescripta, dicereque conatus aliqua vel mandare, ut singultus ilia crebrius pulsans, stridorque dentium et brachiorum motus velut caestibus dimicantium indicabat, iam superatus, liventibusque maculis interfusus, animam diu colluctatam efflavit, aetatis quinquagesimo anno et quinto, imperii (minus centum dies) secundo et decimo.", "st": "30.6"}, {"sp": "N", "t": "Replicare nunc est opportunum (ut aliquotiens fecimus), et ab ortu primigenio patris huius principis ad usque ipsius obitum, actus eius discurrere per epilogos brevis, nec vitiorum praetermisso discrimine, vel bonorum, quae potestatis amplitudo monstravit, nudare solita semper animorum interna.", "st": "30.7"}, {"sp": "N", "t": "Natus apud Cibalas, Pannoniae oppidum, Gratianus maior ignobili stirpe, cognominatus est a pueritia prima Funarius, ea re quod nondum adultus, venalem circumferens funem, quinque militibus eum rapere studio magno conatis, nequaquam cessit: aemulatus Crotoniaten Milonem, cui mala saepe cohaerenter laeva manu retinenti vel dextra, nulla umquam virium fortitudo abstraxit.", "st": "30.7"}, {"sp": "N", "t": "Ob ergo validi corporis robur, et peritiam militum more luctandi, notior multis, post dignitatem protectoris atque tribuni, comes praefuit rei castrensi per Africam, unde furtorum suspicione contactus, digressusque multo postea pari potestate Brittannum rexit exercitum, tandemque honeste sacramento solutus, revertit ad larem, et agens procul a strepitu, multatione bonorum afflictus est a Constantio, hoc nomine, quod civili flagrante discordia, hospitio dicebatur suscepisse Magnentium, per agrum suum ad proposita festinantem.", "st": "30.7"}, {"sp": "N", "t": "Cuius meritis Valentinianus ab ineunte adulescentia commendabilis, contextu suarum quoque suffragante virtutum, indutibus imperatoriae maiestatis apud Nicaeam ornatus, in Augustum collegium fratrem Valentem adscivit, ut germanitate ita concordia sibi iunctissimum, inter probra medium et praecipua, quae loco docebimus competenti.", "st": "30.7"}, {"sp": "N", "t": "Igitur Valentinianus post periculorum molestias plures, dum esset privatus, emensas, imperitare exorsus, ut arces prope flumina sitas et urbes muniret, Gallias petit, Alamannicis patentes excursibus, reviviscentibus erectius cognito principis Iuliani interitu, quem post Constantem solum omnium formidabant.", "st": "30.7"}, {"sp": "N", "t": "Ideo autem etiam Valentinianus merito timebatur, quod auxit et exercitus valido supplemento, et utrubique Rhenum celsioribus castris munivit atque castellis, ne latere usquam hostis ad nostra se proripiens possit.", "st": "30.7"}, {"sp": "N", "t": "Utque multa praetereamus, quae egit moderatoris auctoritate fundati, quaeque per se vel duces correxit industrios, post Gratianum filium in societatem suae potestatis assumptum, Vithicabium regem Alamannorum, Vadomario genitum, adulescentem in flore primo genarum, nationes ad tumultus cientem et bella, clam (quia non potuit aperte) confodit; et Alamannis congressus, prope Solicinium locum, ubi insidiis paene perierat, circumventus, ad exitium ultimum delere potuit universos, ni paucos velox effugium tenebris amendasset.", "st": "30.7"}, {"sp": "N", "t": "Inter haec tamen caute gesta, iam conversos ad metuendam rabiem Saxonas, semper quolibet inexplorato ruentes, delatosque tunc ad maritimos tractus, quorum spoliis paene redierant locupletes, malefido quidem sed utili commento peremit, praeda raptoribus vi fractis excussa.", "st": "30.7"}, {"sp": "N", "t": "Itidemque Britannos, catervas superfusorum hostium non ferentes, spe meliorum assumpta, in libertatem et quietem restituit placidam, nullo paene redire permisso grassatorum ad sua.", "st": "30.7"}, {"sp": "N", "t": "Efficacia pari Valentinum quoque, Pannonium exsulem, per has provincias molientem otium turbare commune, antequam negotium effervescat, oppressit.", "st": "30.7"}, {"sp": "N", "t": "Africam deinde malo repentino perculsam, discriminibus magnis exemit, cum voracis militarium fastus ferre nequiens Firmus, ad omnes dissensionum motus perflabiles gentes Mauricas concitasset.", "st": "30.7"}, {"sp": "N", "t": "Similique fortitudine clades ingemiscendas Illyrici vindicasset, ni morte praeventus reliquisset rem seriam imperfectam.", "st": "30.7"}, {"sp": "N", "t": "Ac licet opera praestabilium ducum haec quae rettulimus consummata sunt, tamen ipsum quoque satis constat, ut erat expeditae mentis usuque castrensis negotii diuturno firmatus, egisse complura; inter quae illud elucere clarius potuit, si Macrianum regem ea tempestate terribilem, vivum capere potuisset, ut industria magna temptarat, postquam eum evasisse Burgundios, quos ipse admoverat Alamannis, maerens didicisset et tristis.", "st": "30.7"}, {"sp": "N", "t": "Haec super actibus principis brevi sunt textu percursa: nunc confisi quod nec metu nec adulandi foeditate constricta posteritas, incorrupta praeteritorum solet esse spectatrix, summatim eius numerabimus vitia, post et praecipua narraturi.", "st": "30.8"}, {"sp": "N", "t": "Adsimulavit non numquam clementiae speciem, cum esset in acerbitatem naturae calore propensior, oblitus profecto quod regenti imperium omnia nimia, velut praecipites scopuli, sunt evitanda.", "st": "30.8"}, {"sp": "N", "t": "Nec enim usquam reperitur miti cohercitione contentus, sed aliquotiens quaestiones multiplicari iussisse cruentas, per interrogationes funestas, non nullis ad usque discrimina vitae vexatis: et ita erat effusior ad nocendum ut nullum aliquando damnatorum capitis eriperet morte, subscriptionis elogio leni, cum id etiam principes interdum fecere saevissimi.", "st": "30.8"}, {"sp": "N", "t": "Atquin potuit exempla multa contueri maiorum, et imitari peregrina atque interna humanitatis et pietatis, quas sapientes consanguineas virtutum esse definiunt bonas. E quibus haec sufficiet poni. Artaxerxes Persarum ille rex potentissimus, quem Macrochira membri unius longitudo commemoravit, suppliciorum varietates, quas natio semper exercuit cruda, lenitate genuina castigans, tiaras ad vicem capitum quibusdam noxiis amputabat: et ne secaret aures more regio pro delictis, ex galeris fila pendentia praecidebat: quae temperantia morum ita tolerabilem eum fecit et verecundum, ut annitentibus cunctis, multos et mirabiles actus impleret, Graecis scriptoribus celebratos.", "st": "30.8"}, {"sp": "N", "t": "Praenestino praetore, qui bello quodam Samnitico properare iussus ad praesidium venerat segnius, ad crimen diluendum exhibito, Papirius Cursor, ea tempestate dictator, securem per lictorem expediri homineque abiecta purgandi se fiducia stupefacto, visum prope fruticem iussit abscidi: hocque ioci genere castigatum, cum eum absolveret, non ideo contemptus, bella diuturna patrum superavit et gravia, solus ad resistendum aptus Alexandro Magno, si calcasset Italiam, aestimatus.", "st": "30.8"}, {"sp": "N", "t": "Haec forsitan Valentinianus ignorans, minimeque reputans, afflicti solacium status semper esse lenitudinem principum, poenas per ignes augebat et gladios: quod ultimum in adversis rebus remedium pietas reperit animorum, ut Isocratis memorat pulchritudo: cuius vox est perpetua docentis, ignosci debere interdum armis superato rectori, quam iustum quid sit ignoranti.", "st": "30.8"}, {"sp": "N", "t": "Unde motum existimo Tullium praeclare pronuntiasse, cum defenderet Oppium: “Et enim multum posse ad salutem alterius, honori multis; parum potuisse ad exitium, probro nemini umquam fuit.”", "st": "30.8"}, {"sp": "N", "t": "Aviditas plus habendi, sine honesti pravique differentia, et indagandi quaestus varios per alienae vitae naufragia, exundavit in hoc principe flagrantius adulescens, Quam quidam praetendentes imperatorem Aurelianum purgare temptabant, id affirmando quod ut ille post Gallienum, et lamentabilis rei publicae casus, exinanito aerario, torrentis ritu ferebatur in divites, ita hic quoque post procinctus Parthici clades, magnitudine indigens impensarum, ut militi supplementa suppeterent et stipendium, crudelitati cupiditatem opes nimias congerendi miscebat: dissimulans scire, quod sunt aliqua quae fieri non oportet, etiam si licet, Themistoclis illius vere dissimilis, qui cum post pugnam agminaque deleta Persarum, licenter obambulans, armillas aureas vidisset humi proiectas, et torquem, “Tolle” inquit “haec,” ad comitum quendam prope adstantem versus, “quia Themistocles non es,” quodlibet spernens in duce magnanimo lucrum.", "st": "30.8"}, {"sp": "N", "t": "Huius exempla continentiae similia plurima in Romanis exuberant ducibus: quibus omissis, quoniam non sunt perfectae virtutis indicia, (nec enim aliena non rapere laudis est), unum ex multis constans innocentiae vulgi veteris specimen ponam. Cum proscriptorum locupletes domus diripiendas Romanae plebei Marius dedisset et Cinna, ita vulgi rudes animi sed humana soliti respectare, alienis laboribus pepercerunt, ut nullus egens reperiretur aut infimus, qui de civili luctu fructum contrectare pateretur sibi concessum.", "st": "30.8"}, {"sp": "N", "t": "Invidia praeter haec ante dictus medullitus urebatur, et sciens pleraque vitiorum imitari solere virtutes, memorabat assidue, livorem severitatis rectae potestatis esse individuam sociam. Utque sunt dignitatum apices maximi, licere sibi cuncta existimantes, et ad suspicandum contrarios, exturbandosque meliores pronius inclinati, bene vestitos oderat et eruditos et opulentos et nobiles, et fortibus detrahebat, ut solus videretur bonis artibus eminere, quo vitio exarsisse principem legimus Hadrianum.", "st": "30.8"}, {"sp": "N", "t": "Arguebat hic idem princeps timidos saepius, maculosos tales appellans et sordidos, et infra sortem humilem amendandos, ipse ad pavores irritos aliquotiens abiectius pallens, et quod nusquam erat, ima mente formidans.", "st": "30.8"}, {"sp": "N", "t": "Quo intellecto, magister officiorum Remigius, cum eum ex incidentibus ira fervere sentiret, fieri motus quosdam barbaricos, inter alia subserebat: hocque ille audito, quia timore mox frangebatur, ut Antoninus Pius erat serenus et clemens.", "st": "30.8"}, {"sp": "N", "t": "Iudices numquam consulto malignos elegit, sed si semel promotos agere didicisset immaniter, Lycurgos invenisse praedicabat et Cassios, columina iustitiae prisca, scribensque hortabatur assidue, ut noxas vel leves acerbius vindicarent.", "st": "30.8"}, {"sp": "N", "t": "nec afflictis (si fors ingruisset inferior) erat ullum in principis benignitate perfugium, quod semper, ut agitato mari iactatis, portus patuit exoptatus. Finis enim iusti imperii (ut sapientes docent) utilitas oboedientium aestimatur et salus.", "st": "30.8"}, {"sp": "N", "t": "Consentaneum est venire post haec ad eius actus, sequendos recte sentientibus et probandos: ad quos si reliqua temperasset, vixerat ut Traianus et Marcus. In provinciales admodum parcus, tributorum ubique molliens sarcinas: oppidorum et limitum conditor tempestivus: militaris disciplinae censor eximius, in hoc tantum deerrans, quod cum gregariorum etiam levia puniret errata, potiorum ducum flagitia progredi sinebat in maius, ad querellas in eos motas aliquotiens obsurdescens: unde Britannici strepitus et Africanae clades et vastitas emersit Illyrici.", "st": "30.9"}, {"sp": "N", "t": "Omni pudicitiae cultu domi castus et foris, nullo contagio conscientiae violatus obscenae, nihil incestum: hancque ob causam tamquam retinaculis petulantiam frenarat aulae regalis, quod custodire facile potuit, necessitudinibus suis nihil indulgens, quas aut in otio reprimebat, aut mediocriter honoravit absque fratre, quem temporis compulsus angustiis, in amplitudinis suae societatem assumpsit.", "st": "30.9"}, {"sp": "N", "t": "Scrupulosus in deferendis potestatibus celsis nec imperante eo provinciam nummularius rexit, aut administratio venundata, nisi inter imperandi exordia, ut solent occupationis spe impune quaedam sceleste committi.", "st": "30.9"}, {"sp": "N", "t": "Ad inferenda propulsandaque bella sollertissime cautus, aestu Martii pulveris induratus, boni pravique suasor et desuasor admodum prudens, militaris rei ordinum scrutantissimus: scribens decore, venusteque pingens et fingens, et novorum inventor armorum: memoria sermoneque incitato quidem sed raro, facundiae proximo vigens, amator munditiarum, laetusque non profusis epulis sed excultis.", "st": "30.9"}, {"sp": "N", "t": "Postremo hoc moderamine principatus inclaruit, quod inter religionum diversitates medius stetit, nec quemquam inquietavit, neque ut hoc coleretur, imperavit aut illud: nec interdictis minacibus subiectorum cervicem ad id, quod ipse coluit, inclinabat, sed intemeratas reliquit has partes ut repperit.", "st": "30.9"}, {"sp": "N", "t": "Corpus eius lacertosum et validum, capilli fulgor colorisque nitor cum oculis caesiis, semper obliquum intuentibus et torvum, atque pulchritudo staturae, liniamentorumque recta compago, maiestatis regiae decus implebat.", "st": "30.9"}, {"sp": "N", "t": "Post conclamata imperatoris suprema, corpusque curatum ad sepulturam, ut missum Constantinopolim inter divorum reliquias humaretur, suspenso instante procinctu, anceps rei timebatur eventus cohortibus Gallicanis, quae non semper dicatae legitimorum principum fidei, velut imperiorum arbitri, ausurae novum quoddam in tempore sperabantur: hoc temptandae novitatis spes adiciente, quod gestorum ignarus etiam tum Gratianus agebat tum apud Treveros, ubi profecturus eum morari disposuerat pater.", "st": "30.10"}, {"sp": "N", "t": "Cum negotium in his esset angustiis, et tamquam in eadem navi futuri periculorum (si accidissent) participes, omnes eadem formidarent: sedit summatum consilio, avulso ponte quem compaginarat ante necessitas, invadens terras hostilis, ut superstitis Valentiniani mandatu Merobaudes protinus acciretur.", "st": "30.10"}, {"sp": "N", "t": "Hocque ille ut erat sollertis ingenii, quod evenerat ratus, aut forte doctus ab eo per quem vocabatur, rupturum concordiae iura Gallicanum militem suspicatus, missam ad se tesseram finxit redeundi cum eo, ad observandas Rheni ripas quasi furore barbarico crudescente: utque erat secrete mandatum, Sebastianum principis adhuc ignorantem excessum, longius amendavit, quietum quidem virum et placidum, sed militari favore sublatum, ideo maxime tunc cavendum.", "st": "30.10"}, {"sp": "N", "t": "Reverso itaque Merobaude, altiore cura prospectum, expedite consilio, Valentinianus puer defuncti filius tum quadrimus, vocaretur in imperium cooptandus, centesimo lapide disparatus, degensque cum Iustina matre in villa, quam Murocinctam appellant.", "st": "30.10"}, {"sp": "N", "t": "Hocque concinenti omnium sententia confirmato, Cerealis avunculus eius ocius missus, eundem puerum lecticae impositum, duxit in castra sextoque die post parentis obitum imperator legitime declaratus, Augustus nuncupatur more sollemni.", "st": "30.10"}, {"sp": "N", "t": "Et licet cum haec agerentur, Gratianum indigne laturum existimantes, absque sui permissu principem alium institutum, postea tamen sollicitudine discussa vixere securius, quod ille (ut erat benivolus et pius) consanguineum pietate nimia dilexit et educavit.", "st": "30.10"}, {"sp": "HDR", "t": "Liber XXXI", "st": "31"}, {"sp": "N", "t": "Inter haec Fortunae volucris rota, adversa prosperis semper alternans, Bellonam furiis in societatem adscitis, armabat, maestosque transtulit ad Orientem eventus, quos adventare praesagiorum fides clara monebat, et portentorum.", "st": "31.1"}, {"sp": "N", "t": "Post multa enim quae vates auguresque praedixere veridice, resultabant canes ululantibus lupis, et querulum quoddam nocturnae volucres tinniebant et flebile, et squalidi solis exortus hebetabant matutinos diei candores, et Antiochiae per rixas tumultusque vulgares id in consuetudinem venerat, ut quisquis vim se pati existimaret, “Vivus ardeat Valens” licentius clamitaret, vocesque praeconum audiebantur, assidue mandantium congeri ligna ad Valentini lavacri succensionem, studio ipsius principis conditi.", "st": "31.1"}, {"sp": "N", "t": "Quae hunc illi impendere exitum vitae modo non aperte loquendo monstrabant. Super his larvale simulacrum Armeniae regis, et miserabiles umbrae paulo ante in negotio Theodori caesorum, per quietem stridendo carmina quaedam neniarum horrenda, multos diris terroribus agitabant.", "st": "31.1"}, {"sp": "N", "t": "Vaccula gurgulione consecto, exanimis visa est iacens, cuius mors publicorum funerum aerumnas indicabat amplas et pervulgatas. Denique cum Chalcedonos subverterentur veteres muri, ut apud Constantinopolim aedificaretur lavacrum, ordine resoluto saxorum, in quadrato lapide qui structura latebat in media, hi Graeci versus incisi reperti sunt, futura plene pandentes:", "st": "31.1"}, {"sp": "N", "t": "ἀλλ’ ὁπόταν νύμφαι δροσεραὶ κατὰ ἄστυ χορείῃ<br>τερπόμεναι στρωφῶνται ἐυστεφέας κατ’ ἀγυιάς,<br>καὶ τεῖχος λουτροῖο πολύστονον ἔσσεται ἄλκαρ,<br>δὴ τότε μυρία φῦλα πολυσπερέων ἀνθρώπων<br>Ἴστρον καλλιρόοιο πόρον περάοντα σὺν αἰχμῇ,<br>καὶ Σκυθικὴν ὀλέσει χώρην καὶ Μυσίδα γαῖαν,<br>Παιονίης δ’ ἐπιβάντα σὺν ἐλπίσι μαινομένῃσιν<br>αὐτοῦ καὶ βιότοιο τέλος καὶ δῆρις ἐφέξει.", "st": "31.1"}, {"sp": "N", "t": "Totius autem sementem exitii et cladum originem diversarum, quas Martius furor incendio insolito miscendo cuncta concivit, hanc comperimus causam. Hunorum gens monumentis veteribus leviter nota, ultra paludes Maeoticas glacialem oceanum accolens, omnem modum feritatis excedit.", "st": "31.2"}, {"sp": "N", "t": "Ubi quoniam ab ipsis nascendi primitiis infantum ferro sulcantur altius genae, ut pilorum vigor tempestivus emergens, corrugatis cicatricibus hebetetur, senescunt imberbes absque ulla venustate, spadonibus similes, compactis omnes firmisque membris et opimis cervicibus, prodigiose deformes et pandi, ut bipedes existimes bestias, vel quales in commarginandis pontibus effigiati stipites dolantur incompte.", "st": "31.2"}, {"sp": "N", "t": "In hominum autem figura, licet insuavi, ita victu sunt asperi, ut neque igni neque saporatis indigeant cibis, sed radicibus herbarum agrestium, et semicruda cuiusvis pecoris carne vescantur, quam inter femora sua equorumque terga subsertam, fotu calefaciunt brevi.", "st": "31.2"}, {"sp": "N", "t": "Aedificiis nullis umquam tecti, sed haec velut ab usu communi discreta sepulcra declinant. Nec enim apud eos vel arundine fastigatum reperiri tugurium potest. Sed vagi montes peragrantes et silvas, pruinas famem sitimque perferre ab incunabulis adsuescunt. Peregre tecta (nisi adigente maxima necessitate) non subeunt: nec enim se tutos existimant esse sub tectis morantes.", "st": "31.2"}, {"sp": "N", "t": "Indumentis operiuntur linteis vel ex pellibus silvestrium murum consarcinatis; nec alia illis domestica vestis est, alia forensis. Sed semel obsoleti coloris tunica collo inserta, non ante deponitur aut mutatur, quam diuturna carie in pannulos diffluxerit defrustata.", "st": "31.2"}, {"sp": "N", "t": "Galeris incurvis capita tegunt, hirsuta crura coriis munientes haedinis, eorumque calcei formulis nullis aptati, vetant incedere gressibus liberis. Qua causa ad pedestres parum adcommodati sunt pugnas, verum equis prope affixi, duris quidem sed deformibus, et muliebriter eisdem non numquam insidentes, funguntur muneribus consuetis. Ex ipsis quivis in hac natione pernox et perdius emit et vendit, cibumque sumit et potum, et inclinatus cervici angustae iumenti, in altum soporem ad usque varietatem effunditur somniorum.", "st": "31.2"}, {"sp": "N", "t": "Et deliberatione super rebus proposita seriis, hoc habitu omnes in commune consultant. Aguntur autem nulla severitate regali, sed tumultuario primatum ductu contenti, perrumpunt quicquid incident.", "st": "31.2"}, {"sp": "N", "t": "Et pugnant non numquam lacessiti, ineuntes proelia cuneatim, variis vocibus sonantibus torvum. Utque ad pernicitatem sunt leves et repentini, ita subito de industria dispersi incessunt, et incomposita acie, cum caede vasta discurrunt, nec invadentes vallum, nec castra inimica pilantes, prae nimia rapiditate cernuntur.", "st": "31.2"}, {"sp": "N", "t": "Eoque omnium acerrimos facile dixeris bellatores, quod procul missilibus telis, acutis ossibus pro spiculorum acumine, arte mira coagmentatis, et distantiis decursis comminus ferro sine sui respectu confligunt, hostisque dum mucronum noxias observant, contortis laciniis illigant, ut laqueatis resistentium membris, equitandi vel gradiendi adimant facultatem.", "st": "31.2"}, {"sp": "N", "t": "Nemo apud eos arat nec stivam aliquando contingit. Omnes enim sine sedibus fixis, absque lare vel lege aut victu stabili dispalantur, semper fugientium similes, cum carpentis in quibus habitant: ubi coniuges taetra illis vestimenta contexunt, et coeunt cum maritis, et pariunt, et ad usque pubertatem nutriunt pueros. Nullusque apud eos interrogatus respondere unde oritur potest, alibi conceptus natusque procul, et longius educatus.", "st": "31.2"}, {"sp": "N", "t": "Per indutias infidi et inconstantes, ad omnem auram incidentis spei novae perquam mobiles, totum furori incitatissimo tribuentes. Inconsultorum animalium ritu, quid honestum inhonestumve sit, penitus ignorantes, flexiloqui et obscuri, nullius religionis vel superstitionis reverentia aliquando districti, auri cupidine immensa flagrantes, adeo permutabiles et irasci faciles ut eodem aliquotiens die a sociis nullo irritante saepe desciscant, itidemque propitientur, nemine leniente.", "st": "31.2"}, {"sp": "N", "t": "Hoc expeditum indomitumque hominum genus, externa praedandi aviditate flagrans immani, per rapinas finitimorum grassatum et caedes, ad usque Halanos pervenit, veteres Massagetas, qui unde sint vel quas incolant terras (quoniam huc res prolapsa est), consentaneum est demonstrare, geographica perplexitate monstrata, quae diu multimoda tractans et varia, tandem repperit veritatis interna.", "st": "31.2"}, {"sp": "N", "t": "Abundans aquarum Hister advenarum magnitudine fluenti Sauromatas praetermeat, ad usque amnem Tanaim pertinentes, qui Asiam terminat ab Europa. Hoc transito in immensum extentas Scythiae solitudines Halani inhabitant, ex montium appellatione cognominati, paulatimque nationes conterminas crebritate victoriarum attritas ad gentilitatem sui vocabuli traxerunt (ut Persae).", "st": "31.2"}, {"sp": "N", "t": "Inter hos Nervi mediterranea incolunt loca, vicini verticibus celsis, quos praeruptos geluque torpentes, aquilones adstringunt. Post quos Vidini sunt et Geloni, perquam feri, qui detractis peremptorum hostium cutibus, indumenta sibi equisque tegmina conficiunt bellatoria. Gelonis Agathyrsi collimitant, interstincti colore caeruleo corpora simul et crines, et humiles quidem minutis atque raris, nobiles vero latius fucatis et densioribus notis.", "st": "31.2"}, {"sp": "N", "t": "Post hos Melanchlaenas et Anthropophagos palari accepimus per diversa, humanis corporibus victitantes, quibus ob haec alimenta nefanda desertis, finitimi omnes longa petiere terrarum. Ideoque plaga omnis orienti aestivo obiecta, usque dum venitur ad Seras, inhabitabilis mansit.", "st": "31.2"}, {"sp": "N", "t": "Parte alia prope Amazonum sedes, Halani sunt orienti acclines, diffusi per populosas gentes et amplas, Asiaticos vergentes in tractus, quas dilatari ad usque Gangen accepi, fluvium intersecantem terras Indorum, mareque inundantem australe.", "st": "31.2"}, {"sp": "N", "t": "Hi bipertiti per utramque mundi plagam Halani, quorum gentes varias nunc recensere non refert, licet dirempti spatiis longis, per pagos (ut Nomades) vagantur immensos, aevi tamen progressu, ad unum concessere vocabulum, et summatim omnes Halani cognominantur, ob mores et modum efferatum vivendi, eandemque armaturam.", "st": "31.2"}, {"sp": "N", "t": "Nec enim ulla sunt illis vel tuguria, aut versandi vomeris cura, sed carne et copia victitant lactis, plaustris supersidentes, quae operimentis curvatis corticum per solitudines conferunt sine fine distentas. Cumque ad graminea venerint, in orbiculatam figuram locatis sarracis, ferino ritu vescuntur, absumptisque pabulis velut carpentis civitates impositas vehunt, maresque supra cum feminis coeunt, et nascuntur in his et educantur infantes, et habitacula sunt haec illis perpetua, et quocumque ierint, illic genuinum existimant larem.", "st": "31.2"}, {"sp": "N", "t": "Armenta prae se agentes, cum gregibus pascunt, maximeque equini pecoris est eis sollicitior cura. Ibi campi semper herbescunt, intersitis pomiferis locis: atque ideo transeuntes quolibet, nec alimentis nec pabulis indigent, quod efficit umectum solum et crebri fluminum praetermeantium cursus.", "st": "31.2"}, {"sp": "N", "t": "Omnis igitur aetas et sexus imbellis, circa vehicula ipsa versatur, muniisque distringitur mollibus: iuventus vero equitandi usu a prima pueritia coalescens, incedere pedibus existimat vile, et omnes multiplici disciplina prudentes sunt bellatores. Unde etiam Persae, qui sunt originitus Scythae, pugnandi sunt peritissimi.", "st": "31.2"}, {"sp": "N", "t": "Proceri autem Halani paene sunt omnes et pulchri, crinibus mediocriter flavis, oculorum temperata torvitate terribiles, et armorum levitate veloces, Hunisque per omnia suppares, verum victu mitiores et cultu, latrocinando et venando ad usque Maeotica stagna, et Cimmerium Bosporum, itidemque Armenios discurrentes, et Mediam.", "st": "31.2"}, {"sp": "N", "t": "Utque hominibus quietis et placidis otium est voluptabile, ita illos pericula iuvant et bella. Iudicatur ibi beatus, qui in proelio profuderit animam, senescentes enim et fortuitis mortibus mundo digressos, ut degeneres et ignavos conviciis atrocibus insectantur, nec quicquam est quod elatius iactent, quam homine quolibet occiso, proque exuviis gloriosis interfectorum, avulsis capitibus, detractas pelles pro phaleris iumentis accommodant bellatoriis.", "st": "31.2"}, {"sp": "N", "t": "Nec templum apud eos visitur aut delubrum, ne tugurium quidem culmo tectum cerni usquam potest, sed gladius barbarico ritu humi figitur nudus, eumque ut Martem, regionum quas circumcolunt praesulem, verecundius colunt.", "st": "31.2"}, {"sp": "N", "t": "Futura mire praesagiunt mode. Nam rectiores virgas vimineas colligentes, easque cum incantamentis quibusdam secretis, praestituto tempore discernentes, aperte quid portenditur norunt.", "st": "31.2"}, {"sp": "N", "t": "Servitus quid sit ignorant, omnes generoso semine procreati, iudicesque etiam nunc eligunt diuturno bellandi usu spectatos. Sed ad reliqua textus propositi revertamur.", "st": "31.2"}, {"sp": "N", "t": "Igitur Huni pervasis Halanorum regionibus, quos Greuthungis confines Tanaitas consuetudo cognominavit, interfectisque multis et spoliatis, reliquos sibi concordandi fide pacta iunxerunt, eisque adhibitis confidentius Ermenrichi late patentes et uberes pagos repentino impetu perruperunt, bellicosissimi regis, et per multa variaque fortiter facta, vicinis nationibus formidati.", "st": "31.3"}, {"sp": "N", "t": "Qui vi subitae procellae perculsus, quamvis manere fundatus et stabilis diu conatus est, impendentium tamen diritatem augente vulgatius fama, magnorum discriminum metum voluntaria morte sedavit.", "st": "31.3"}, {"sp": "N", "t": "Cuius post obitum, rex Vithimiris creatus, restitit aliquantisper Halanis, Hunis aliis fretus, quos mercede sociaverat partibus suis. Verum post multas quas pertulit clades, animam effudit in proelio, vi superatus armorum. Cuius parvi filii Viderichi nomine curam susceptam Alatheus tuebatur et Saphrax, duces exerciti et firmitate pectorum noti, qui cum tempore arto praeventi, abiecissent fiduciam repugnandi, cautius discedentes, ad amnem Danastium pervenerunt, inter Histrum et Borysthenem, per camporum ampla spatia diffluentem.", "st": "31.3"}, {"sp": "N", "t": "Haec ita praeter spem accidisse doctus Athanarichus, Theruingorum iudex (in quem ut ante relatum est, ob auxilia missa Procopio, dudum Valens commoverat signa) stare gradu fixo temptabat, surrecturus in vires, si ipse quoque lacesseretur, ut ceteri.", "st": "31.3"}, {"sp": "N", "t": "Castris denique prope Danasti margines a Greuthungorum vallo longius opportune metatis, Munderichum ducem postea limitis per Arabiam, cum Lagarimano et optimatibus aliis, ad usque vicensimmn lapidem misit, hostium speculaturos adventum, ipse aciem nullo turbante, interim struens.", "st": "31.3"}, {"sp": "N", "t": "Verum longe aliter quam rebatur evenit. Huni enim (ut sunt in coniectura sagaces), multitudinem esse longius aliquam suspicati, praetermissis quos viderant, in quietem tamquam nullo obstante compositis, rumpente noctis tenebras luna, vado fluminis penetrate, id quod erat potissimum elegerunt, et veriti ne praecursorius index procul agentes absterreat, Athanaricum ipsum ictu petivere veloci.", "st": "31.3"}, {"sp": "N", "t": "Eumque stupentem ad impetum primum, amissis quibusdam suorum, coegerunt ad effugia properare montium praeruptorum. Qua rei novitate, maioreque venturi pavore constrictus, a superciliis Gerasi fluminis ad usque Danubium, Taifalorum terras praestringens, muros altius erigebat: hac lorica diligentia celeri consummata, in tuto locandam securitatem suam existimans et salutem.", "st": "31.3"}, {"sp": "N", "t": "Dumque efficax opera suscitatur, Huni passibus eum citis urgebant, et iam oppresserant adventantes, ni gravati praedarum onere destitissent.", "st": "31.3"}, {"sp": "N", "t": "Fama tamen late serpente per Gothorum reliquas gentes, quod invisitatum antehac hominum genus, modo, nivium ut turbo montibus celsis, ex abdito sinu coortum apposita quaeque convellit et corrumpit: populi pars maior, quae Athanaricum attenuata necessariorum penuria deseruerat, quaeritabat domicilium remotum ab omni notitia barbarorum, diuque deliberans, quas eligeret sedes, cogitavit Thraciae receptaculum gemina ratione sibi conveniens, quod et caespitis est feracissimi, et amplitudine fluentorum Histri distinguitur ab arvis patentibus iam peregrini fulminibus Martis: hoc quoque idem residui velut mente cogitavere communi.", "st": "31.3"}, {"sp": "N", "t": "Itaque duce Alavivo ripas occupavere Danubii, missisque oratoribus ad Valentem, suscipi se humili prece poscebant, et quiete victuros se pollicentes, et daturos (si res flagitasset) auxilia.", "st": "31.4"}, {"sp": "N", "t": "Dum aguntur haec in externis, novos maioresque solitis casus versare gentes arctoas, rumores terribiles diffuderunt: per omne quicquid ad Pontum a Marcomannis praetenditur et Quadis, multitudinem barbaram abditarum nationum, vi subita sedibus pulsam, circa flumen Histrum, vagari cum caritatibus suis disseminantes.", "st": "31.4"}, {"sp": "N", "t": "Quae res aspernanter a nostris inter initia ipsa accepta est, hanc ob causam, quod illis tractibus non nisi peracta aut sopita audiri procul agentibus consueverant bella.", "st": "31.4"}, {"sp": "N", "t": "Verum pubescente fide gestorum, cui robur adventus gentilium addiderat legatorum, precibus et obtestatione petentium, citra flumen suscipi plebem extorrem: negotium laetitiae fuit potius quam timori, eruditis adulatoribus in maius fortunam principis extollentibus, quae ex ultimis terris tot tirocinia trahens, ei nec opinanti offerret, ut collatis in unum suis et alienigenis viribus, invictum haberet exercitum, et pro militari supplemento, quod provinciatim annuum pendebatur, thesauris accederet auri cumulus magnus.", "st": "31.4"}, {"sp": "N", "t": "Hacque spe mittuntur diversi, qui cum vehiculis plebem transferant truculentam. Et navabatur opera diligens, nequi Romanam rem eversurus relinqueretur, vel quassatus morbo letali. Proinde permissu imperatoris transeundi Danubium copiam, colendique adepti Thraciae partes, transfretabantur in dies et noctes, navibus ratibusque et cavatis arborum alveis agminatim impositi, atque per amnem longe omnium difficillimum, imbriumque crebritate tunc auctum, ob densitatem nimiam contra ictus aquarum nitentes quidam, et natare conati, hausti sunt plures.", "st": "31.4"}, {"sp": "N", "t": "Ita turbido instantium studio orbis Romani pernicies ducebatur. Illud sane neque obscurum est neque incertum, infaustos transvehendi barbaram plebem ministros, numerum eius comprehendere calculo saepe temptantes, conquievisse frustratos, ut eminentissimus memorat vates,<br>Quem qui scire velit, Libyci velit aequoris idem<br>Discere, quam multae zephyro truduntur harenae.", "st": "31.4"}, {"sp": "N", "t": "Resipiscant tandem memoriae veteres, Medicas acies ductantes ad Graeciam: quae dum Hellespontiacos pontes, et discidio quodam fabrili, mare sub imo Athonis pede quaesitum exponunt et turmatim apud Doriscum exercitus recensitos, concordante omni posteritate, ut fabulosae sunt lectae.", "st": "31.4"}, {"sp": "N", "t": "Nam postquam innumerae gentium multitudines, per provincias circumfusae, pandentesque se in spatia ampla camporum, regiones omnes et cuncta opplevere montium iuga, fides quoque vetustatis recenti documento firmata est. Et primus cum Alavivo suscipitur Fritigernus, quibus et alimenta pro tempore, et subigendos agros tribui statuerat imperator.", "st": "31.4"}, {"sp": "N", "t": "Per id tempus nostri limitis reseratis obicibus, atque (ut Aetnaeas favillas armatorum agmina diffundente barbaria), cum difficiles necessitatum articuli correctores rei militaris poscerent aliquos claritudine gestarum rerum notissimos: quasi laevo quodam numine deligente, in unum quaesiti potestatibus praefuere castrensibus homines maculosi: quibus Lupicinus antistabat et Maximus, alter per Thracias comes, dux alter exitiosus, aemulae ambo temeritatis.", "st": "31.4"}, {"sp": "N", "t": "Quorum insidiatrix aviditas materia malorum omnium fuit. Nam (ut alia omittamus, quae memorati vel certe, sinentibus eisdem, alii perditis rationibus in commeantes peregrinos adhuc innoxios deliquerunt) illud dicetur, quod nec apud sui periculi iudices absolvere ulla poterat venia, triste et inauditum.", "st": "31.4"}, {"sp": "N", "t": "Cum traducti barbari victus inopia vexarentur, turpe commercium duces invisissimi cogitarunt, et quantos undique insatiabilitas colligere potuit canes, pro singulis dederunt mancipiis, inter quae et filii ducti sunt optimatum.", "st": "31.4"}, {"sp": "N", "t": "Per hos dies interea etiam Vithericus Greuthungorum rex cum Alatheo et Saphrace, quorum arbitrio regebatur, itemque Farnobio, propinquans Histri marginibus, ut simili susciperetur humanitate, obsecravit imperatorem legatis propere missis.", "st": "31.4"}, {"sp": "N", "t": "Quibus (ut communi rei conducere videbatur) repudiatis, et quid capesserent anxiis, Athanarichus paria pertimescens abscessit, memor Valentem dudum cum foederaretur concordia despexisse, affirmantem se religione devinctum, ne calcaret solum aliquando Romanum, hacque causatione, principem firmare pacem in medio flumine coegisse: quam simultatem veritus, ut adhuc durantem, ad Caucalandensem locum altitudine silvarum inaccessum et montium, cum suis omnibus declinavit, Sarmatis inde extrusis.", "st": "31.4"}, {"sp": "N", "t": "At vero Theruingi, iam dudum transire permissi, prope ripas etiam tum vagabantur, duplici impedimento adstricti, quod ducum dissimulatione perniciosa, nec victui congruis sunt adiuti, et tenebantur consulto nefandis nundinandi commerciis.", "st": "31.5"}, {"sp": "N", "t": "Quo intellecto, ad perfidiam instantium malorum subsidium verti mussabant, et Lupicinus ne iam deficerent pertimescens, eos admotis militibus adigebat ocius proficisci.", "st": "31.5"}, {"sp": "N", "t": "Id tempus opportunum nancti Greuthungi, cum alibi militibus occupatis, navigia ultro citroque discurrere solita, transgressum eorum prohibentia, quiescere perspexissent, ratibus transiere male contextis, castraque a Fritigerno locavere longissime.", "st": "31.5"}, {"sp": "N", "t": "At ille genuina praevidendi sollertia, venturos muniens casus, ut et imperiis oboediret, et regibus validis iungeretur, incedens segnius, Marcianopolim tarde pervenit itineribus lentis. Ubi aliud accessit atrocius, quod arsuras in commune exitium faces furiales accendit.", "st": "31.5"}, {"sp": "N", "t": "Alavivo et Fritigerno ad convivium corrogatis, Lupicinus ab oppidi moenibus barbaram plebem, opposito milite, procul arcebat, introire ad comparanda victui necessaria, ut dicioni nostrae obnoxiam et concordem, per preces assidue postulantem, ortisque maioribus iurgiis inter habitatores et vetitos, ad usque necessitatem pugnandi est ventum. Efferatique acrius barbari, cum necessitudines hostiliter rapi sentirent, spoliarunt interfectam militum magnam manum.", "st": "31.5"}, {"sp": "N", "t": "Quae accidisse idem Lupicinus, latenti nuntio doctus, dum in nepotali mensa ludicris concrepantibus, diu discumbens vino marcebat et somno, futuri coniciens exitum, satellites omnes, qui pro praetorio (honoris et tutelae causa) duces praestolabantur, occidit.", "st": "31.5"}, {"sp": "N", "t": "Hocque populus qui muros obsidebat dolenter accepto, ad vindictam detentorum regum (ut opinabatur) paulatim augescens, multa minabatur et saeva. Utque erat Fritigernus expediti consilii, veritus ne teneretur obsidis vice cum ceteris, exclamavit, graviore pugnandum exitio, ni ipse ad leniendum vulgus sineretur exire cum sociis, quod arbitratum humanitatis specie ductores suos occisos, in tumultum exarsit. Hocque impetrato, egressi omnes exceptique cum plausu et gaudiis, ascensis equis evolarunt, moturi incitamenta diversa bellorum.", "st": "31.5"}, {"sp": "N", "t": "Haec ubi fama rumorum nutrix maligna dispersit, urebatur dimicandi studio Theruingorum natio omnis, et inter metuenda multa periculorumque praevia maximorum, vexillis de more sublatis, auditisque triste sonantibus classicis, iam turmae praedatoriae concursabant, pilando villas et incendendo, vastisque cladibus quicquid inveniri poterat permiscentes.", "st": "31.5"}, {"sp": "N", "t": "Adversus quos Lupicinus properatione tumultuaria coactis militibus, temere magis quam consulte progressus, in nono ab urbe miliario stetit, paratus ad decernendum. Barbarique hoc contemplate, globos irrupere nostrorum incauti, et parmas oppositis corporibus illidendo, obvios hastis perforabant et gladiis, furoreque urgente cruento, et tribuni et pleraque pars armatorum periere, signis ereptis, praeter ducem infaustum, qui ad id solum intentus, ut confligentibus aliis, proriperet ipse semet in fugam, urbem cursu concito petit. Post quae hostes armis induti Romanis, nullo vetante per varia grassabantur.", "st": "31.5"}, {"sp": "N", "t": "Et quoniam ad has partes post multiplices ventum est actus, id lecturos (siqui erunt unquam), obtestamur, nequis a nobis scrupulose gesta vel numerum exigat peremptorum, qui comprehendi nullo genere potuit. Sufficiet enim, veritate nullo velata mendacio, ipsas rerum digerere summitates: cum explicandae rerum memoriae ubique debeatur integritas fida.", "st": "31.5"}, {"sp": "N", "t": "Negant antiquitatum ignari, tantis malorum tenebris offusam aliquando fuisse rem publicam, sed falluntur malorum recentium stupore confixi. Namque si superiores vel recens praeteritae revolvantur aetates, tales tamque tristes rerum motus saepe contigisse monstrabunt.", "st": "31.5"}, {"sp": "N", "t": "Inundarunt Italiam ex abditis oceani partibus Teutones repente cum Cimbris, sed post inflictas rei Romanae clades immensas, ultimis proeliis per duces amplissimos superati, quid potestas Martia adhibita prudentia valeat, radicitus extirpati discriminibus didicere supremis.", "st": "31.5"}, {"sp": "N", "t": "Marco itidem moderante imperium, unum spirando vesania gentium dissonarum, post bellorum fragores immensos, post aerumnas urbium captarum et direptarum, et pessum datas copias, concitas probi rectoris interitu, partes earum exiguas reliquisset intactas.", "st": "31.5"}, {"sp": "N", "t": "Verum mox post calamitosa dispendia res in integrum sunt restitutae, hac gratia, quod nondum solutioris vitae mollitie sobria vetustas infecta nec ambitiosis mensis nec flagitiosis quaestibus inhiabat, sed unanimanti ardore, summi et infimi inter se congruentes, ad speciosam pro re publica mortem tamquam ad portum aliquem tranquillum properabant et placidum.", "st": "31.5"}, {"sp": "N", "t": "Duobus navium milibus, perrupto Bosporo et litoribus Propontidis, Scythicarum gentium catervae transgressae, ediderunt quidem acerbas terra marique strages; sed amissa suorum parte maxima reverterunt.", "st": "31.5"}, {"sp": "N", "t": "Ceciderunt dimicando cum barbaris imperatores Decii pater et filius. Obsessae Pamphyliae civitates, insulae populatae complures, inflammata Macedonia omnis; diu multitudo Thessalonicam circumsedit itidemque Cyzicum. Anchialos capta et tempore eodem Nicopolis, quam indicium victoriae contra Dacos Traianus condidit imperator.", "st": "31.5"}, {"sp": "N", "t": "Post clades acceptas, illatasque multas et saevas, excisa est Philippopolis, centum hominum milibus, nisi fingunt annales, intra moenia iugulatis. Vagati per Epirum Thessaliamque et omnem Graeciam licentius hostes externi, sed assumpto in imperium Claudio, glorioso ductore, et eodem honesta morte praerepto, per Aurelianum, acrem virum, et severissimum noxarum ultorem, pulsi per longa saecula siluerunt immobiles, nisi quod postea latrocinales globi vicina cum sui exitio rarius incursabant. Verum ea persequar unde deverti.", "st": "31.5"}, {"sp": "N", "t": "Hoc gestorum textu circumlato nuntiis densis, Sueridus et Colias (Gothorum optimates) cum populis suis longe ante suscepti, et curare apud Hadrianopolim hiberna dispositi, salutem suam ducentes antiquissimam omnium, otiosis animis accidentia cuncta contuebantur.", "st": "31.6"}, {"sp": "N", "t": "Verum imperatoris litteris repente perlatis, quibus transire iussi sunt in Hellespontum, viaticum cibos biduique dilationem tribui sibi sine tumore poscebant. Quod civitatis magistratus ferens indigne (succensebat enim eisdem ob rem suam in suburbano vastatam) imam plebem omnem cum Fabricensibus, quorum illic ampla est multitudo, productam, in eorum armavit exitium, iussisque bellicum canere bucinis, ni abirent ocius (ut statutum est) pericula omnibus minabatur extrema.", "st": "31.6"}, {"sp": "N", "t": "Quo malo praeter spem Gothi perculsi, et concito quam considerato civium assultu perterriti, steterunt immobiles, laceratique ad ultimum detestatione atque conviciis, et temptati missilium iactibus raris, ad defectionem erupere confessam, et caesis plurimis, quos impetus deceperat petulantior, aversisque residuis, et telorum varietate confixis, habitu iam Romano cadaveribus spoliatis armati, viso propius Fritigerno, iunxerunt semet ut morigeri socii, urbemque clausam obsidionalibus aerumnis urgebant. In qua difficultate diutius positi, passim et promiscue ruebant, eminensque aliquorum audacia peribat inulta, multique sagittis et rotatis per fundas lapidibus interibant.", "st": "31.6"}, {"sp": "N", "t": "tunc Fritigernus frustra cum tot cladibus colluctari homines ignaros obsidendi contemplans, relicta ibi manu sufficiente, abire negotio imperfecto suasit, pacem sibi esse cum parietibus memorans, suadensque ut populandas opimas regiones et uberes, absque discrimine ullo, vacuas praesidiis etiamtum adorerentur.", "st": "31.6"}, {"sp": "N", "t": "Laudato regis consilio, quem cogitatorum norant fore socium efficacem, per Thraciarum latus omne dispersi caute gradiebantur, dediticiis vel captivis vices uberes ostendentibus, eos praecipue, ubi alimentorum reperiri satias dicebatur, eo maxime adiumento, praeter genuinam erecti fiduciam, quod confluebat ad eos in dies ex eadem gente multitude, dudum a mercatoribus venundati, adiectis plurimis quos primo transgressu necati inedia vino exili vel panis frustis mutavere vilissimis.", "st": "31.6"}, {"sp": "N", "t": "Quibus accessere sequendarum auri venarum periti non pauci, vectigalium perferre posse non sufficientes sarcinas graves, susceptique libenti consensione cunctorum, magno usui eisdem fuere ignota peragrantibus loca, conditoria frugum occulta, et latebras hominum et receptacula secretiora monstrando.", "st": "31.6"}, {"sp": "N", "t": "Nec quicquam nisi inaccessum et devium praeeuntibus eisdem mansit intactum. Sine distantia enim aetatis vel sexus, caedibus incendiorumque magnitudine cuncta flagrabant, abstractisque ab ipso uberum suctu parvulis et necatis, raptae sunt matres et viduatae maritis coniuges ante oculos caesis, et puberes adultique pueri per parentum cadavera tracti sunt.", "st": "31.6"}, {"sp": "N", "t": "Senes denique multi, ad satietatem vixisse clamantes, post amissas opes cum speciosis feminis, manibus post terga contortis, defletisque gentilium favillis aedium ducebantur extorres.", "st": "31.6"}, {"sp": "N", "t": "Haec ex Thraciis magno maerore accepta Valentem principem in sollicitudines varias distraxerunt. Et confestim Victore magistro equitum misso ad Persas, ut super Armeniae statu pro captu rerum componeret impendentium, ipse Antiochia protinus egressurus, ut Constantinopolim interim peteret, Profuturum praemisit et Traianum, ambo rectores, anhelantes quidem altius sed imbellis.", "st": "31.7"}, {"sp": "N", "t": "Qui cum ad loca venissent, ubi particulatim perque furta magis et latrocinia multitudo minui deberet hostilis, ad id quod erat perniciosum intempestive conversi, legiones ab Armenia ductas opposuere vesanum adhuc spirantibus barbaris, opere quidem Martio saepe recte compertas, sed impares plebi immensae, quae celsorum iuga montium occuparat et campos.", "st": "31.7"}, {"sp": "N", "t": "Hi numeri nondum experti, quid cum desperatione rabies valeret indomita, trusos hostes ultra Haemi montis abscisos scopulos faucibus impegere praeruptis, ut in locis desertis et solis inclusos, nusquam reperientes exitum, diuturna consumeret fames, et opperirentur ipsi Frigeridum ducem, cum Pannonicis et transalpinis auxiliis adventantem, quem petitu Valentis Gratianus ire disposuit in procinctum, laturum suppetias his qui ad ultimum vexabantur exitium.", "st": "31.7"}, {"sp": "N", "t": "Post quem Richomeres, domesticorum tunc comes, imperatu eiusdem Gratiani motus e Galliis, properavit ad Thracias, ductans cohortes aliquas nomine tenus, quarum pars pleraque deseruerat, ut iactavere quidam, Merobaudis suasu, veriti ne destitutae adminiculis Galliae vastarentur licenter, Rheno perrupto.", "st": "31.7"}, {"sp": "N", "t": "Verum articulorum dolore Frigerido praepedito, vel certe (ut obtrectatores finxere malivoli), morbum causante, ne ferventibus proeliis interesset, universos regens ex communi sententia, Richomeres Profuturo sociatur et Traiano, tendentibus prope oppidum Salices: unde haut longo spatio separatum, vulgus inaestimabile barbarorum, ad orbis rotundi figuram multitudine digesta plaustrorum, tamquam intramuranis cohibitum spatiis, otio fruebatur, et ubertate praedarum.", "st": "31.7"}, {"sp": "N", "t": "Praevia igitur spe meliorum, Romani duces (si fors copiam attulisset), ausuri aliquid gloriosum, Gothos quicquid molirentur, sagaciter observabant: id scilicet praestruentes, ut si aliorsum castra movissent, quod fecere creberrime, terga ultimorum adorti, plures perfoderent contis, magnamque spoliorum averterent partem.", "st": "31.7"}, {"sp": "N", "t": "Hoc intellecto hostes vel transfugarum indiciis docti, per quos nihil latebat incognitum, in eodem loco diu manserunt: sed oppositi exercitus metu praestricti, aliorumque militum, quos affluere iam sperabant, tessera data gentili, per diversa prope diffusas accivere vastatorias manus, quae iussis optimatum acceptis, statim ut incensi malleoli, ad carraginem (quam ita ipsi appellant), aliti velocitate regressae, incentivum audendi maiora popularibus addiderunt.", "st": "31.7"}, {"sp": "N", "t": "Nihil post haec inter partes praeter indutias laxatum est breves. Reversis enim his quos necessitas evocarat, plebs omnis intra saeptorum ambitum etiam tum contrusa, immaniter fremens, animisque concita truculentis, experiri postrema discrimina, nec principibus gentis, qui aderant, renuentibus, cupiditate raecipiti festinabat. Et quoniam haec sole agebantur extremo, noxque adventans ad quietem invitos retinebat et maestos, capto per otium cibo, somni manserunt expertes.", "st": "31.7"}, {"sp": "N", "t": "Contra Romani, his cognitis, ipsi quoque exsomnes, verebantur hostes et male sanos eorum ductores, ut rabidas feras: eventum licet ancipitem, ut numero satis inferiores, prosperum tamen ob iustiorem sui causam, mentibus exspectantes impavidis.", "st": "31.7"}, {"sp": "N", "t": "Candente itaque protinus die, signo ad arma capienda ex utraque parte per lituos dato, barbari postquam inter eos ex more iuratum est, tumulosos locos appetere temptaverunt, quo exinde per proclive rotarum modo obvios impetu convolverent acriore. Hocque viso, ad suos quisque manipulos properans miles, stabili gradu consistens, nec vagabatur nec relictis ordinibus procursabat.", "st": "31.7"}, {"sp": "N", "t": "Ergo ubi utrimque acies cautius incedentes, gressu steterunt immobili, torvitate mutua bellatores luminibus se contuebantur obliquis. Et Romani quidem voce undique Martia concinentes, a minore solita ad maiorem protolli, quam gentilitate appellant barritum, vires validas erigebant. Barbari vero maiorum laudes clamoribus stridebant inconditis, interque varios sermonis dissoni strepitus, leviora proelia temptabantur.", "st": "31.7"}, {"sp": "N", "t": "Iamque verrutis et missilibus aliis, utrimque semet eminus lacessentes, ad conferendas coiere minaciter manus, et scutis in testudinum formam coagmentatis, pes cum pede collatus est. Barbarique ut reparabiles semper et celeres, ingentes clavas in nostros conicientes ambustas, mucronesque acrius resistentium pectoribus illidentes, sinistrum cornu perrumpunt: quod inclinatum subsidialis robustissimus globus, e propinquo latere fortiter excitus, haerente iam morte cervicibus sustentavit.", "st": "31.7"}, {"sp": "N", "t": "Fervente igitur densis caedibus proelio, in confertos quisque promptior ruens, ritu grandinis undique volitantibus telis oppetebat et gladiis; et sequebantur equites hinc inde fugientium occipitia lacertis ingentibus praecidentes et terga, itidemque altrinsecus pedites, lapsorum timore impeditorum secando suffragines.", "st": "31.7"}, {"sp": "N", "t": "Et cum omnia caesorum corporibus opplerentur, iacebant inter eos quidam semianimes, spem vitae inaniter usurpando, alii glande fundis excussa, vel harundinibus armatis ferro confixi, quorundam capita per medium frontis et verticis mucrone distincta, in utrumque humerum magno cum horrore pendebant.", "st": "31.7"}, {"sp": "N", "t": "Et pertinaci concertatione nondum lassatae, aequo Marte partes semet altrinsecus afflictabant, nec de rigore genuine quidquam remittebant, dum vires animorum alacritas excitaret. Diremit tamen interneciva certamina cedens vespero dies, et cunctis, qua quisque potuit, incomposite discedentibus, residui omnes repetunt tentoria tristiores.", "st": "31.7"}, {"sp": "N", "t": "Humatis denique, pro locorum et temporis ratione, honoratis quibusdam inter defunctos, reliqua peremptorum corpora dirae volucres consumpserunt, assuetae illo tempore cadaveribus pasci, ut indicant nunc usque albentes ossibus campi. Constat tamen in numero longe minores Romanos, cum copiosa multitudine colluctatos, funerea multa perpessos: non tamen sine deflendis aerumnis exagitasse barbaram plebem.", "st": "31.7"}, {"sp": "N", "t": "His casibus proeliorum ita luctuose finitis, nostri proximos Marcianopoleos petivere secessus. Gothi intra vehiculorum anfractus sponte sua contrusi, numquam exinde per dies septem egredi vel videri sunt ausi, ideoque opportunitatem milites nancti, immensas alias barbarorum catervas inter Haemimontanas angustias clauserunt, aggerum obiectu celsorum, hac spe nimirum ut inter Histrum et solitudines perniciosa hostium multitudo compacta, nullosque reperiens exitus, periret inedia, cunctis utilibus ad vivendum in civitates validas comportatis, quarum nullam etiam tum circumsedere conati sunt, haec et similia machinari penitus ignorantes.", "st": "31.8"}, {"sp": "N", "t": "Post quae repetivit Gallias Richomeres, ob maiorem proeliorum fremitum, qui sperabatur, inde adminicula perducturus. Haec Gratiano quater et Merobaude consulibus agebantur, anno in autumnum vergente.", "st": "31.8"}, {"sp": "N", "t": "Inter quae Valens audito lugubri bellorum direptionumque eventu, Saturninum equestris exercitus ad tempus cura commissa, suppetias Traiano ferentem misit et Profuturo.", "st": "31.8"}, {"sp": "N", "t": "Forteque eisdem diebus, per Scythiae regiones et Moesiae omnibus quae poterant mandi consumptis, feritate urgente pariter et inopia erumpere barbari molibus magnis ardebant. Hocque saepe temptato, cum obruerentur vigore nostrorum, per asperitates scruposas valide resistentium, adacti necessitate postrema, Hunorum et Halanorum aliquos ad societatem spe praedarum ingentium adsciverunt.", "st": "31.8"}, {"sp": "N", "t": "Quo cognito Saturninus (iam enim aderat, et praetenturas stationesque disponebat agrarias), paulatim colligens suos, digredi parabat consilio non absurdo: ne subita multitudo, ut amnis immani pulsu undarum obicibus ruptis emissus, convelleret levi negotio cunctos, suspecta loca acutius observantes.", "st": "31.8"}, {"sp": "N", "t": "Deinde post reseratas angustias abitumque militis tempestivum, incomposite, qua quisque clausorum potuit (nullo vetante), turbandis incubuit rebus: et vastabundi omnes per latitudines Thraciae pandebantur impune, ab ipsis tractibus, quos praetermeat Hister, exorsi, ad usque Rhodopen et fretum, quod immensa disterminat maria, rapinis et caedibus, sanguineque et incendiis et liberorum corporum corruptelis, omnia foedissime permiscentes.", "st": "31.8"}, {"sp": "N", "t": "tunc erat spectare cum gemitu facta dictu visuque praedira, attonitas metu feminas flagris concrepantibus agitari, fetibus gravidas adhuc immaturis, antequam prodirent in lucem, impia tolerantibus multa, implicatos alios matribus parvulos, et puberum audire lamenta, puellarumque nobilium, quarum stringebat fera captivitas manus.", "st": "31.8"}, {"sp": "N", "t": "Post quae adulta virginitas, castitasque nuptarum, ore abiecto, flens ultima ducebatur, mox profanandum pudorem optans morte (licet cruciabili) praevenire. Inter quae cum beluae ritu traheretur ingenuus paulo ante dives et liber, de te, Fortuna, ut inclementi querebatur et caeca, quae eum puncto temporis brevi opibus exutum et dulcedine caritatum, domoque extorrem, quam concidisse vidit in cinerem et ruinas, aut lacerandum membratim, aut serviturum sub verberibus et tormentis crudo devovisti victori.", "st": "31.8"}, {"sp": "N", "t": "Barbari tamen, velut diffractis caveis bestiae, per Thraciarum amplitudines fusius incitati, oppidum petivere nomine Dibaltum, ubi tribunum scutariorum Barzimeren inventum cum suis Cornutisque et aliis peditum numeris castra ponentem assiliunt, eruditum pulvere militari rectorem.", "st": "31.8"}, {"sp": "N", "t": "Qui confestim (ut adigebat necessitas instantis exitii) iussa canere bellicum tuba, lateribus firmatis prorupit, cum promptis accinctis ad proelium: fortiterque resistendo pari pugnandi sorte discesserat, ni eum equitum accursus complurium anhelum circumvenisset et fessum. Et ita cecidit interfectis barbarorum non paucis, quorum clades copiarum magnitudo celabat.", "st": "31.8"}, {"sp": "N", "t": "Re in hunc modum peracta, Gothi quid postea molirentur incerti, quaeritabant Frigeridum, tamquam obicem validum, ubi reppererint excisuri: et cultiore victu somnoque parumper assumpto, eum sequebantur ut ferae: docti quod Gratiani monitu reversus in Thracias, et prope Beroeam vallo metato, eventus rerum speculabatur ancipites.", "st": "31.9"}, {"sp": "N", "t": "Et hi quidem ad patrandum propositum discursione rapida maturabant. Ille vero regendi conservandique militis non ignarus, id quod cogitatum est suspicatus, vel exploratorum relatione, quos miserat, aperte instructus, per montium celsa silvarumque densitates ad Illyricum redit, erectus prosperitate nimia, quam ei fors obtulit insperata.", "st": "31.9"}, {"sp": "N", "t": "Repedando enim congregatusque in cuneos sensim progrediens, Gothorum optimatem Farnobium cum vastatoriis globis vagantem licentius occupavit, ducentemque Taifalos, nuper in societatem adhibitos: qui (si dignum est dici), nostris ignotarum gentium terrore dispersis, transiere flumen direpturi vacua defensoribus loca.", "st": "31.9"}, {"sp": "N", "t": "Eorum catervis subito visis, certare comminus dux cautissimus parans, adortusque nationis utriusque grassatores, minantes etiam tum acerbas strages multos occidit, trucidassetque omnes ad unum, ut ne nuntius quidem cladis post appareret, ni cum aliis multis perempto Farnobio, metuendo antehac incensore turbarum, obtestatus prece impensa superstitibus pepercisset, vivosque omnes circa Mutinam, Regiumque et Parmam, Italica oppida, rura culturos exterminavit.", "st": "31.9"}, {"sp": "N", "t": "Hanc Taifalorum gentem turpem ac obscenae vitae flagitiis ita accepimus mersam, ut apud eos nefandi concubitus foedere copulentur maribus puberes, aetatis viriditatem in eorum pollutis usibus consumpturi. Porro siqui iam adultus aprum exceperit solus, vel interemerit ursum immanem, colluvione liberatur incesti.", "st": "31.9"}, {"sp": "N", "t": "Haec autumno vergente in hiemem funesti per Thracias turbines converrebant. Quae temporum rabies, velut cuncta cientibus Furiis, ad regiones quoque longinquas progrediens, late serpebat.", "st": "31.10"}, {"sp": "N", "t": "Et iam Lentiensis Alamannicus populus, tractibus Raetiarum confinis, per fallaces discursus, violato foedere dudum concepto, collimitia nostra temptabat, quae clades hinc exitiale primordium sumpsit.", "st": "31.10"}, {"sp": "N", "t": "Ex hac natione quidam inter principis armigeros militans, poscente negotio reversus in larem, ut erat in loquendo effusior, interrogantes multos quid ageretur in palatio, docet arcessitu Valentis patrui Gratianum Orientem versus mox signa moturum, ut duplicatis viribus repellantur plagarum terminalium accolae, ad Romanarum rerum excidium coniurati.", "st": "31.10"}, {"sp": "N", "t": "Quibus avide Lentienses acceptis, ipsi quoque haec quasi vicini cernentes, ut sunt veloces et rapidi, conferti in praedatorios globos, Rhenum gelu pervium pruinis Februario mense transire tentarunt; quos tendentes prope cum Petulantibus Celtae, non sine sui iactura, afflictos graviter adultis viribus averterunt.", "st": "31.10"}, {"sp": "N", "t": "Verum retrocedere coacti Germani, atque noscentes exercitus pleramque partem in Illyricum (ut imperatore mox adfuturo) praegressam, exarsere flagrantius: maioraque coeptantes, pagorum omnium incolis in unum collectis, cum quadraginta armorum milibus vel septuaginta, ut quidam laudes extollendo principis iactitarunt, sublati in superbiam nostra confidentius irruperunt.", "st": "31.10"}, {"sp": "N", "t": "Quibus Gratianus cum formidine magna compertis, revocatis cohortibus, quas praemiserat in Pannonias, convocatisque aliis, quas in Galliis retinuerat dispositio prudens, Nannieno negotium dedit, virtutis sobriae duci: eique Mallobauden iunxit pari potestate collegam, domesticorum comitem, regemque Francorum, virum bellicosum et fortem.", "st": "31.10"}, {"sp": "N", "t": "Nannieno igitur pensante fortunarum versabiles casus, ideoque cunctandum esse censente, Mallobaudes alta pugnandi cupiditate raptatus (ut consueverat), ire in hostem, differendi impatiens, angebatur.", "st": "31.10"}, {"sp": "N", "t": "Proinde horrifico adversum fragore terrente, ubi primum apud Argentariam signo per cornicines dato, concurri est coeptum, sagittarum verrutorumque missilium pulsibus crebriores hinc indeque sternebantur.", "st": "31.10"}, {"sp": "N", "t": "Sed in ipso proeliorum ardore, infinita hostium multitudine milites visa, vitantesque aperta discrimina, per calles consitas arboribus et angustas, ut quisque potuit, dispersi, paulo postea stetere fidentius, et splendore consimili, proculque nitore fulgentes armorum, imperatorii adventus iniecere barbaris metum.", "st": "31.10"}, {"sp": "N", "t": "Qui repente versi in terga, resistentesque interdum, nequid ultimae rationis omitterent, ita sunt caesi, ut ex praedicto numero non plus quam quinque milia, ut aestimabatur, evaderent, densitate nemorum tecta, inter complures alios audaces et fortes, rege quoque Priario interfecto, exitialium concitore pugnarum.", "st": "31.10"}, {"sp": "N", "t": "Hac laeti successus fiducia Gratianus erectus, iamque ad partes tendens eoas, laevorsus flexo itinere, latenter Rheno transito, spe incitatior bona, universam, si id temptanti fors adfuisset, delere statuit malefidam et turbarum avidam gentem.", "st": "31.10"}, {"sp": "N", "t": "Hocque urgentibus aliis super alios nuntiis cognito, Lentienses aerumnis populi sui ad internecionem paene deleti, et repentino principis adventu defixi, quid capesserent ambigentes, cum neque repugnandi neque agendi aliquid aut moliendi laxamentum possent invenire vel breve, impetu celeri obsessos petiverunt inviis cautibus colles, abruptisque per ambitum rupibus insistentes, rebus caritatibusque suis, quas secum conduxerant, omni virium robore propugnabant.", "st": "31.10"}, {"sp": "N", "t": "Qua difficultate perpensa, velut murorum obicibus opponendi, per legiones singulas quingenteni leguntur armati, usu prudenter bellandi comperti. Qui ea re animorum aucta fiducia, quod versari inter antesignanos visebatur acriter princeps, montes scandere nitebantur, tamquam venaticias praedas, si calcassent editiora, confestim sine certamine ullo rapturi: exorsumque proelium vergente in meridiem die, tenebrae quoque occupavere nocturnae.", "st": "31.10"}, {"sp": "N", "t": "Quippe magno utriusque partis pugnabatur exitio: caedebant cadebantque nostrorum non pauci, simul arma imperatorii comitatus auro colorumque micantia claritudine, iaculatione ponderum densa confringebantur.", "st": "31.10"}, {"sp": "N", "t": "Exinde diu reputante Gratiano cum optimatibus, perniciosum apparebat et irritum, contra asperitates aggerum prominentium intempestiva contendere pertinacia, multis (ut in tali negotio), variatis sententiis, otioso milite circumvallari placuit barbaros, inedia fatigatos, quia locorum iniquitate defenderentur.", "st": "31.10"}, {"sp": "N", "t": "Verum cum obstinatione simili renitentes Germani, peritique regionum, petissent alios montes, his quos ante insederant, altiores: conversus illuc cum exercitu imperator, eadem qua antea fortitudine, semitas ducentes ad ardua quaeritabat.", "st": "31.10"}, {"sp": "N", "t": "Quem Lentienses intentum iugulis suis omni perseverandi studio contemplantes, post deditionem, quam impetravere supplici prece, oblata (ut praeceptum est) iuventute valida nostris tirociniis permiscenda, ad genitales terras innoxii ire permissi sunt.", "st": "31.10"}, {"sp": "N", "t": "Hanc victoriam, opportunam et fructuosam, quae gentes hebetavit occiduas, sempiterni numinis nutu, Gratianus incredibile dictu est, quo quantoque vigore exserta celeritate aliorsum properans expedivit: praeclarae indolis adulescens, facundus et moderatus et bellicosus et clemens, ad aemulationem lectorum progrediens principum, dum etiam tum lanugo genis inserperet speciosa, ni vergens in ludibriosos actus natura, laxantibus proximis, semet ad vana studia Caesaris Commodi convertisset, licet hic incruentus.", "st": "31.10"}, {"sp": "N", "t": "Ut enim ille, quia perimere iaculis plurimas feras spectante consueverat populo, et centum leones in amphitheatrali circulo simul emissos, telorum vario genere, nullo geminato vulnere, contruncavit, ultra hominem exsultavit, ita hic quoque, intra saepta quae appellant vivaria, sagittarum pulsibus crebris dentatas conficiens bestias, incidentia multa parvi ducebat et seria: eo tempore quo etiam si imperium Marcus regeret Antoninus, aegre sine collegis similibus et magna sobrietate consiliorum, lenire luctuosos rei publicae poterat casus.", "st": "31.10"}, {"sp": "N", "t": "Dispositis igitur, quae pro temporum captu per Gallias res rationesque poscebant, et punito scutario proditore, qui festinare principem ad Illyricum barbaris indicarat, Gratianus exinde digressus per castra, quibus Felicis Arboris nomen est, per Lauriacum ad opitulandum oppressae parti porrectis itineribus ire tendebat.", "st": "31.10"}, {"sp": "N", "t": "Eisdemque diebus, Frigerido multa atque utilia pro securitate communi sollertissime cogitanti, munireque properanti Succorum angustias, ne discursatores hostes et leves, tamquam exaestuantes nivi torrentes, per septentrionales provincias fusius vagarentur, successor Maurus nomine mittitur comes, venalis ferociae specie, et ad cuncta mobilis et incertus; is est quem praeteritorum textu rettulimus, ambigenti super corona capita imponenda Caesari Iuliano, dum inter eius armigeros militaret, Arroganti astu fidenter torquem obtulisse collo abstractam.", "st": "31.10"}, {"sp": "N", "t": "Remotusque in ipsa vertigine pereuntium rerum dux cautus et diligens, cum etiam si dudum discessisset in otium, ad procinctum reduci negotiorum magnitudine poscente deberet.", "st": "31.10"}, {"sp": "N", "t": "His forte diebus, Valens tandem excitus Antiochia, longitudine viarum emensa, venit Constantinopolim, ubi moratus paucissimos dies, seditioneque popularium levi pulsatus, Sebastiano paulo ante ab Italia (ut petierat) misso, vigilantiae notae ductori, pedestris exercitus cura commissa, quem regebat antea Traianus: ipse ad Melanthiada villam Caesarianam profectus, militem stipendio fovebat et alimentis, et blanda crebritate sermonum.", "st": "31.11"}, {"sp": "N", "t": "Unde cum itinere edicto per tesseram Nicen venisset, quae statio ita cognominatur, relatione speculatorum didicit refertos opima barbaros praeda, a Rhodopes tractibus prope Hadrianopolim revertisse: qui motu imperatoris cum abundanti milite cognito, popularibus iungere se festinant, circa Beroeam et Nicopolim agentibus praesidiis fixis: atque ilico ut oblatae occasionis maturitas postulabat, cum trecentenis militibus per singulos numeros lectis, Sebastianus properare dispositus erat, conducens rebus publicis aliquid (ut promittebat) acturus.", "st": "31.11"}, {"sp": "N", "t": "Qui itineribus celeratis, conspectus prope Hadrianopolim, obseratis vi portis, iuxta adire prohibebatur: veritis defensoribus ne captus ab hoste veniret et subornatus, atque contingeret aliquid in civitatis perniciem, quale per Acacium acciderat comitem, quo per fraudem a Magnentiacis militibus capto, claustra patefacta sunt Alpium Iuliarum.", "st": "31.11"}, {"sp": "N", "t": "Agnitus tamen licet sero Sebastianus, et urbem introire permissus, cibo et quiete curatis pro copia, quos ductabat, secuta luce impetu clandestino erupit, vesperaque incedente, Gothorum vastatorios cuneos prope flumen Hebrum subito visos, paulisper opertus aggeribus et frutectis, obscura nocte suspensis passibus consopitos adgressus est, adeoque prostravit, ut praeter paucos quos morte velocitas exemerat pedum, interirent reliqui omnes, praedamque retraxit innumeram, quam nec civitas cepit nec planities lata camporum.", "st": "31.11"}, {"sp": "N", "t": "Qua causa percitus Fritigernus, et extimescens, ne dux (ut saepe audierat) impetrabilis, dispersos licenter suorum globos raptuique intentos consumeret, improvises adoriens: revocatis omnibus prope Cabylen oppidum cito discessit, ut agentes in regionibus patulis nec inedia nec occultis vexarentur insidiis.", "st": "31.11"}, {"sp": "N", "t": "Dum haec aguntur in Thraciis, Gratianus docto litteris patruo, qua industria superaverit Alamanos, pedestri itinere praemissis impedimentis et sarcinis, ipse cum expeditiore militum manu, permeato Danubio, delatus Bononiam, Sirmium introiit, et quadriduum ibi moratus, per idem flumen ad Martis castra descendit, febribus intervallatis afflictus: in quo tractu Halanorum impetu repentino temptatus, amisit sequentium paucos.", "st": "31.11"}, {"sp": "N", "t": "Eisdemque diebus exagitatus ratione gemina Valens, quod Lentienses compererat superatos, quodque Sebastianus subinde scribens facta dictis exaggerabat, e Melanthiade signa commovit, aequiperare facinore quodam egregio adulescentem properans filium fratris, cuius virtutibus urebatur: ducebatque multiplices copias, nec contemnendas nec segnes, quippe etiam veteranos eisdem iunxerat plurimos, inter quos et honoratiores alii et Traianus recinctus est, paulo ante magister armorum.", "st": "31.12"}, {"sp": "N", "t": "Et quoniam exploratione sollicita cognitum est cogitare hostes fortibus praesidiis itinera claudere, per quae commeatus necessarii portabantur, occursum est huic conatui competenter, ad retinendas opportunitates angustiarum, quae prope erant, peditibus sagittariis et equitum turma citius missa.", "st": "31.12"}, {"sp": "N", "t": "Triduoque proximo, cum barbari gradu incederent leni et metuentes eruptionem per devia, quindecim milibus passuum a civitate discreti, stationem peterent Nicen, incertum quo errore procursatoribus omnem illam multitudinis partem, quam viderant, in numero decem milium esse firmantibus, imperator procaci quodam calore perculsus eisdem occurrere festinabat.", "st": "31.12"}, {"sp": "N", "t": "Proinde agmine quadrato incedens, prope suburbanum Hadrianopoleos venit, ubi vallo sudibus fossaque firmato, Gratianum impatienter operiens, Richomerem comitem domesticorum suscepit, ab eodem imperatore praemissum cum litteris, ipsum quoque venturum mox indicantibus.", "st": "31.12"}, {"sp": "N", "t": "Quarum textu oratus, ut praestolaretur paulisper periculorum participem, neve abruptis discriminibus temere semet committeret solum, adhibitis in consilium potestatibus variis, quid facto opus esset deliberabat.", "st": "31.12"}, {"sp": "N", "t": "Et cum Sebastiano auctore quidam protinus eundum ad certamen urgerent, Victor nomine (magister equitum) Sarmata sed cunctator et cautus, eadem sentientibus multis, imperii socium exspectari censebat, ut incrementis exercitus Gallicani adscitis, opprimeretur levius tumor barbaricus flammans.", "st": "31.12"}, {"sp": "N", "t": "Vicit tamen funesta principis destinatio, et adulabilis quorundam sententia regiorum, qui ne paene iam partae victoriae (ut opinabantur) consors fieret Gratianus, properari cursu celeri suadebant.", "st": "31.12"}, {"sp": "N", "t": "Et dum necessaria parabantur ad decernendum, Christiani ritus presbyter (ut ipsi appellant), missus a Fritigerno legatus, cum aliis humilibus venit ad principis castra, susceptusque leniter, eiusdem ductoris obtulit scripta, petentis propalam ut sibi suisque, quos extorres patriis laribus rapidi ferarum gentium exegere discursus, habitanda Thracia sola cum pecore omni concederetur et frugibus: hoc impetrato, spondentis perpetuam pacem.", "st": "31.12"}, {"sp": "N", "t": "Praeter haec idem Christianus, ut conscius arcanorum et fidus, secretas alias eiusdem regis obtulit litteras, qui astu et ludificandi varietate nimium sollers, docebat Valentem quasi mox amicus futurus et socius, aliter se popularium saevitiam mollire non posse vel ad condiciones rei Romanae profuturas allicere, nisi subinde armatum eisdem iuxta monstraret exercitum, et timore imperatorii nominis intentato, eos a pernicioso pugnandi revocaret ardore. Et legati quidem ut ambigui frustra habiti discesserunt.", "st": "31.12"}, {"sp": "N", "t": "Exoriente vero aurora diei, quem quintum Iduum Augustarum numerus ostendit annalis, signa praepropere commoventur, impedimentis et sarcinis prope Hadrianopoleos muros cum legionum tutela congrua collocatis. Thesauri enim et principalis fortunae insignia cetera, cum praefecto et consistorianis ambitu moenium tenebantur.", "st": "31.12"}, {"sp": "N", "t": "Decursis itaque viarum spatiis confragosis, cum in medium torridus procederet dies, octava tandem hora hostium carpenta cernuntur, quae ad speciem rotunditatis detornatae digesta exploratorum relatione affirmabantur. Atque (ut mos est) ululante barbara plebe ferum et triste, Romani duces aciem instruxere, et anteposito dextro cornu equitum prime, peditatus pars maxima subsidebat.", "st": "31.12"}, {"sp": "N", "t": "Cornu autem equitum laevum, disiectis adhuc per itinera plurimis, summa difficultate conductum, properabat passibus citis. Dumque idem cornu, nullo etiam tum interturbante, extenditur, horrendo fragore, sibilantibus armis, pulsuque minaci scutorum, territi barbari, quoniam pars eorum cum Alatheo et Saphrace, procul agens et accita, nondum venerat, oraturos pacem misere legatos.", "st": "31.12"}, {"sp": "N", "t": "Eorum dum vilitatem despicit imperator, ut firma fierent paciscenda, optimates poscens idoneos mitti, illi de industria cunctabantur, ut inter fallaces indutias equites sui redirent, quos affore iam sperabant: et miles fervore calefactus aestivo, siccis faucibus commarceret, relucente amplitudine camporum incendiis, quos lignis nutrimentisque aridis subditis, ut hoc fieret idem, hostes urebant. Cui malo aliud quoque accedebat exitiale, quod homines et iumenta cruciabat inedia gravis.", "st": "31.12"}, {"sp": "N", "t": "Inter quae Fritigernus, callidus futuri coniector, Martemque pertimescens ancipitem, velut caduceatorem, unum e plebe suo misit arbitrio, impetens nobiles quosdam et electos ad se prope diem obsides mitti, impavidus ipse minas militares laturus, et necessaria.", "st": "31.12"}, {"sp": "N", "t": "Laudato probatoque formidati ducis proposito, tribunus Aequitius, cui tunc erat cura palatii credita, Valentis propinquus, assentientibus cunctis ire pignoris loco mature disponitur. Quo renitente, quia semel captus ab hostibus, lapsusque a Dibalto, verebatur eorum irrationabiles motus, Richomeres se sponte obtulit propria, ireque promiserat libens, pulcrum hoc quoque facinus, et viro convenire existimans forti. Iamque pergebat, indicia dignitatis et natalium …", "st": "31.12"}, {"sp": "N", "t": "Eo ad vallum hostile tendente, sagittarii et scutarii, quos Bacurius Hiberus quidam tunc regebat et Cassio, avidius impetu calenti progressi, iamque adversis conexi, ut immature proruperant, ita inerti discessu, primordia belli foedarunt.", "st": "31.12"}, {"sp": "N", "t": "Hocque impedimento conatus intempestivi et Richomeris alacritas fracta est, nusquam ire permissi, et equitatus Gothorum cum Alatheo reversus et Saphrace, Halanorum manu permixta, ut fulmen prope montes celsos excussus, quoscumque accursu veloci invenire comminus potuit, incitata caede turbavit.", "st": "31.12"}, {"sp": "N", "t": "Cumque arma ex latere omni concuterentur et tela, lituosque Bellona luctuosos inflaret in clades Romanas solito immanius furens, cedentes nostri multis interclamantibus restiterunt, et proelium flammarum ritu accrescens, terrebat militum animos, confixis quibusdam rotatis ictibus iaculorum et sagittarum.", "st": "31.13"}, {"sp": "N", "t": "Deinde collisae in modum rostratarum navium acies, trudentesque se vicissim, undarum specie motibus sunt reciprocis iactitatae.", "st": "31.13"}, {"sp": "N", "t": "Et quia sinistrum cornu ad usque plaustra ipsa accessit, ultra (siqui tulissent suppetias) processurum: a reliquo equitatu desertum, multitudine hostili urgente, ac si ruina aggeris magni, oppressum atque deiectum est: steterunt improtecti pedites ita concatervatis manipulis, ut vix mucronem exserere aut manus reducere quisquam posset. Nec iam obiectu pulveris caelum patere potuit ad prospectum, clamoribus resultans horrificis. Qua causa tela undique mortem vibrantia, destinata cadebant et noxia, quod nec provideri poterant nec caveri.", "st": "31.13"}, {"sp": "N", "t": "Verum ubi effusi immensis agminibus barbari, iumenta conterebant et viros, et neque ad receptum confertis ordinibus laxari usquam poterat locus, et evadendi copiam constipatio densior adimebat: nostri quoque ultimo cadendi contemptu, occursantes receptis gladiis obtruncabant, et mutuis securium ictibus galeae perfringebantur atque loricae.", "st": "31.13"}, {"sp": "N", "t": "Videreque licebat celsum ferocia barbarum, genis stridore constrictis, succiso poplite aut abscisa ferro dextera vel confosso latere inter ipsa quoque mortis confinia minaciter circumferentem oculos truces: ruinaque confligentium mutua, humi corporibus stratis, campi peremptis impleti sunt, et morientium gemitus, profundisque vulneribus transfixorum, cum timore audiebantur ingenti.", "st": "31.13"}, {"sp": "N", "t": "In hoc tanto tamque confusae rei tumultu, exhausti labore et periculis pedites, cum deinceps neque vires illis neque mentes suppeterent ad consilium, diffractis hastarum plerisque collisione assidua, gladiis contenti destrictis, in confertas hostium turmas se immergebant, salutis immemores, circumspectantes ademptum esse omne evadendi suffugium.", "st": "31.13"}, {"sp": "N", "t": "Et quia humus rivis operta sanguineis gressus labiles evertebat, conabantur modis omnibus vitam impendere non inultam: adeo magno animorum robore oppositi incumbentibus, ut etiam telis quidam propriis interirent. Atra denique cruoris facie omnia conturbante, et quocumque se inflexerant oculi, acervis caesorum aggestis, exanimata cadavera sine parsimonia calcabantur.", "st": "31.13"}, {"sp": "N", "t": "Solque sublimior, decurso Leone, ad domicilium caelestis Virginis transiens, Romanos magis attenuatos inedia, sitique confectos, etiam armorum gravantibus sarcinis exurebat. Ad ultimum incumbente barbarorum pondere acies inclinatae nostrorum, quod solum postremis malis habuere subsidium, incondite qua quisque poterat, vertuntur in pedes.", "st": "31.13"}, {"sp": "N", "t": "Dumque omnes dispersi per ignotos tramites cedunt, imperator diris pavoribus circumsaeptus, paulatimque insiliens funerum moles, ad lancearios confugit et mattiarios: qui dum multitudo tolerabatur hostilis, fixis corporibus steterant inconcussi. Eoque viso Traianus exclamat spem omnem absumptam, ni desertus ab armigeris princeps saltem adventicio tegeretur auxilio.", "st": "31.13"}, {"sp": "N", "t": "Hocque audito, Victor nomine comes, Batavos in subsidiis locatos haut procul, ad imperatoris praesidium raptim cogere properans, cum invenire neminem posset, gradiens retro discessit. Parique modo Richomeres periculo semet exemit et Saturninus.", "st": "31.13"}, {"sp": "N", "t": "Sequebantur itaque furore ex oculis lucente barbari nostros, iam linquente venarum calore torpentes: quorum aliqui percussoribus cadebant incertis, non nulli ponderibus solis urgentium obruti, ictuque suorum aliqui trucidati: nec enim saepe renitentibus cedebatur, aut parcebat cedentibus quisquam.", "st": "31.13"}, {"sp": "N", "t": "Super his obstruebant itinera iacentes multi semineces, cruciatus vulnerum conquerentes, cum quibus aggeres quoque equorum constrati, cadaveribus campos implerant. Diremit haec numquam pensabilia damna, quae magno rebus stetere Romanis, nullo splendore lunari nox fulgens.", "st": "31.13"}, {"sp": "N", "t": "Primaque caligine tenebrarum, inter gregarios imperator, ut opinari dabatur (neque enim vidisse se quisquam vel praesto fuisse adseveravit), sagitta perniciose saucius ruit, spirituque mox consumpto decessit, nec postea repertus est usquam. Hostium enim paucis spoliandi gratia mortuos per ea loca diu versatis, nullus fugatorum vel accolarum illuc adire est ausus.", "st": "31.13"}, {"sp": "N", "t": "Simili clade Caesarem accepimus Decium, dimicantem cum barbaris acriter, equi lapsu prostratum, quem ferventem retinere non valuit, abiectumque in paludem, nec emergere potuisse nec inveniri.", "st": "31.13"}, {"sp": "N", "t": "Alii dicunt Valentem animam non exhalasse confestim, sed cum candidatis et spadonibus paucis, prope ad agrestem casam relatum, secunda contignatione fabre munitam, dum fovetur manibus imperitis, circumsessum ab hostibus, qui esset ignorantibus, dedecore captivitatis exemptum.", "st": "31.13"}, {"sp": "N", "t": "Cum enim oppessulatas ianuas perrumpere conati qui secuti sunt, a parte pensili domus sagittis incesserentur, ne per moras inexpedibiles populandi amitterent copiam, congestis stipulae fascibus et lignorum, flammaque supposita, aedificium cum hominibus torruerunt.", "st": "31.13"}, {"sp": "N", "t": "Unde quidam de candidatis, per fenestram lapsus captusque a barbaris, prodidit factum et eos maerore afflixit, magna gloria defraudatos, quod Romanae rei rectorem non cepere superstitem. Is ipse iuvenis, occulte postea reversus ad nostros, haec ita accidisse narravit.", "st": "31.13"}, {"sp": "N", "t": "Pari clade recuperatis Hispaniis, Scipionum alterum cremata turri in quam confugerat, absumptum incendio hostili comperimus. Illud tamen certum est, nec Scipioni nec Valenti sepulturam (qui supremitatis honor est) contigisse.", "st": "31.13"}, {"sp": "N", "t": "In hac multiplici virorum illustrium clade, Traiani mors eminuit et Sebastiani, cum quibus triginta quinque oppetivere tribuni, vacantes et numerorum rectores, et Valerianus atque Aequitius, quorum alter stabulum, alter curabat palatium. Inter hos etiam promotorum tribunus, Potentius, cecidit in primaevo flore aetatis, bono cuique spectatus, meritis Ursicini patris, magistri quondam armorum suisque commendabilis. Constatque vix tertiam evasisse exercitus partem.", "st": "31.13"}, {"sp": "N", "t": "Nec ulla annalibus praeter Cannensem pugnam ita ad internecionem res legitur gesta, quamquam Romani aliquotiens reflante Fortuna fallaciis lusi, bellorum iniquitati cesserunt ad tempus, et certamina multa fabulosae naeniae flevere Graecorum.", "st": "31.13"}, {"sp": "N", "t": "Perit autem hoc exitu Valens, quinquagesimo anno contiguus, cum per annos quattuor imperasset et decem, parvo minus.", "st": "31.14"}, {"sp": "N", "t": "Cuius bona multis cognita dicemus et vitia. Amicus fidelis et firmus, ultor acer ambitionum, severus militaris et civilis disciplinae corrector, pervigil semper et anxius, ne quis propinquitatem praetendens, altius semet efferret, erga deferendas potestates vel adimendas nimium tardus, provinciarum aequissimus tutor, quarum singulas ut domum propriam custodibat indemnes, tributorum onera studio quodam molliens singulari, nulla vectigalium admittens augmenta in adaerandis reliquorum debitis non molestus, furibus et in peculatu deprehensis iudicibus inimicus asper et vehemens. Nec sub alio principe in huius modi negotiis melius secum actum esse meminit Oriens.", "st": "31.14"}, {"sp": "N", "t": "Super his omnibus liberalis erat cum moderatione, cuius rei licet abundent exempla, unum tamen sufficiet poni. Ut sunt in palatiis non nulli alienarum avidi rerum, siqui caducum vel aliud petisset ex usu, cum magna iustorum iniustorumque distinctione, contradicturis copia servata, donabat ei qui petierat, tres vel quattuor alios absentes aliquotiens impetratorum participes iungens, ut castigatius agerent inquieti, lucra quibus inhiabant, hoc minui commento cernentes.", "st": "31.14"}, {"sp": "N", "t": "Super aedificiis autem, quae per diversas urbes et oppida vel instauravit, vel a primis instruxit auspiciis, (ne sim longior) taceo, rebus ipsis id apertius monstrare concedens. Haec bonis omnibus aemulanda sunt, ut existimo: nunc eius vitia percurramus.", "st": "31.14"}, {"sp": "N", "t": "Magnarum opum intemperans appetitor, laborum impatiens, duritiamque magis affectans immanem, in crudelitatem proclivior, subagrestis ingenii, nec bellicis nec liberalibus studiis eruditus: alienis gemitibus libenter emolumenta fructusque conquirens, tuncque magis intolerabilis, cum incidentia crimina ad contemptam vel laesam principis amplitudinem trahens, in sanguinem saeviebat, et dispendia locupletum.", "st": "31.14"}, {"sp": "N", "t": "Illud quoque ferri non poterat, quod cum legibus lites omnes quaestionesque committere videri se vellet, destinatisque velut lectis iudicibus negotia spectanda mandabat, nihil agi contra libidinem suam patiebatur: iniuriosus alia et iracundus, et criminantibus, sine differentia veri vel falsi, facillime patens, quae vitiorum labes etiam in his privatis cotidianisque rationibus impendio est formidanda.", "st": "31.14"}, {"sp": "N", "t": "Cessator et piger: nigri coloris, pupula oculi unius obstructa, sed ita ut non eminus appareret, figura bene compacta membrorum, staturae nec procerae nec humilis, incurvis cruribus exstanteque mediocriter ventre.", "st": "31.14"}, {"sp": "N", "t": "Haec super Valente dixisse sufficiet, quae vera esse aequalis nobis memoria plene testatur. Illud autem praeteriri non convenit, quod cum oraculo tripodis, quem movisse Patricium docuimus et Hilarium, tres versus illos fatidicos comperisset, quorum ultimus est<br>ἐν πεδίοισι Μίμαντος ἀγαιομένοιο Ἄρηος,<br>ut erat inconsummatus et rudis, inter initia contemnebat, processu vero luctuum maximorum, abiecte etiam timidus, eiusdem sortis recordatione Asiae nomen horrebat: ubi Erythraeo oppido superpositum montem Mimanta, et Homerum scripsisse, et Tullium, doctis referentibus audiebat.", "st": "31.14"}, {"sp": "N", "t": "Denique post interitum eius, discessumque hostilem, prope locum in quo cecidisse existimatus est, inventus dicitur saxeus monumenti suggestus, cui lapis affixus incisis litteris Graecis, sepultum ibi nobilem quendam Mimanta veterem indicabat.", "st": "31.14"}, {"sp": "N", "t": "Post exitialem pugnam cum iam tenebris nox terras implesset, hi qui superfuere, dextra pars alii laeva, vel quo metus traxerat ferebantur, quisque proximos quaerens: cum praeter se nihil singuli cernere poterant, occipitiis propriis ferrum arbitrantes haerere. Audiebantur tamen (licet longius) heiulatus miserabiles relictorum, singultusque morientium, et vulneratorum cruciabiles fletus.", "st": "31.15"}, {"sp": "N", "t": "Luce vero coeptante, victores, ut bestiae sanguinis irritamento atrocius efferatae, spei inanis illecebris agitati, Hadrianopolim agminibus petivere densetis, eam vel cum discriminibus excisuri postremis: docti per proditores et transfugas, potestatum culmina maximarum, et fortunae principalis insignia, thesaurosque Valentis, illic ut in munimento arduo conditos.", "st": "31.15"}, {"sp": "N", "t": "Et ne intervallatis ardor intepesceret moris, hora diei quarta ambitu cincto murorum, infestissime certabatur oppugnatoribus genuina ferocia ad praeceps exitium festinantibus, contraque defensorum vigore validis viribus incitato.", "st": "31.15"}, {"sp": "N", "t": "Et quia militum calonumque numerus magnus, civitatem cum iumentis introire prohibitus, affixus parietibus moenium, aedibusque continuis, pro loci humilitate fortiter decernebat, superaratque rabies imminentium ad usque horam diei nonam, subito pedites nostri trecenti, ex his qui prope ipsas stetere loricas, conferti in cuneum, desciverunt ad barbaros, eosque illi avide raptos, confestim (incertum quo consilio) trucidarunt; et ex eo deinceps observatum est, neminem huius modi aliquid vel in desperatione rerum ultima cogitasse.", "st": "31.15"}, {"sp": "N", "t": "Fervente itaque tot malorum congerie, repente cum fragore caelesti, imbres nubibus atris effusi, dispersere circumfrementium globes, reversique ad vallum dimensum tereti figura plaustrorum, immanes spiritus latius porrigentes, iubebant nostris per minaces litteras et legatum dedere civitatem, fide retinendae salutis accepta.", "st": "31.15"}, {"sp": "N", "t": "Verum introire non auso, qui missus est, per Christianum quendam portatis scriptis et recitatis, utque decebat contemptis, parandis operibus diei residuum et nox omnis absumpta. Nam intrinsecus silicibus magnis obstrusae sunt portae, et moenium intuta firmata, et ad emittenda undique tela vel saxa, tormenta per locos aptata sunt habiles, aggestaque prope sufficiens aqua. Pridie enim dimicantium quidam siti ad usque ipsa vitae detrimenta vexati sunt.", "st": "31.15"}, {"sp": "N", "t": "Contra Gothi reputantes difficiles Martis eventus, anxiique cum sterni et sauciari cernerent fortiores, et particulatim vires suas convelli, astutum iniere consilium, quod ipsa indicante Iustitia publicatum est.", "st": "31.15"}, {"sp": "N", "t": "Partis enim nostrae candidatos aliquos qui die praeterito ad eos defecerant, pellexere, ut simulata fuga velut ad propria remeantes, intra muros suscipi se curarent, ingressique latenter quandam incenderent partem: ut tamquam signo erecto occultius, dum circa exstinguendum incendium distringitur multitudo clausorum, civitas perrumperetur impropugnata.", "st": "31.15"}, {"sp": "N", "t": "Perrexere (ut statutum est) candidati: cumque prope fossas venissent, manus tendentes, orantesque ut Romanos semet admitti poscebant. Et recepti quia nulla erat suspicio quae vetaret, interrogatique super consiliis hostium, variarunt: unde factum est ut cruenta quaestione vexati, cervicibus perirent abscisis, quid acturi venerant, aperte confessi.", "st": "31.15"}, {"sp": "N", "t": "Omni itaque bellandi apparatu praestructo, adventante vigilia tertia, barbari abolito praeteritorum vulnerum metu, in urbis obseratos aditus multiplicatis ordinibus inundarunt, et obstinatione magna caventium malo. At cum armatis provinciales et palatini ad obruendos eos excitatius exsurgebant, et cuiusque modi tela in multitudine tanta, vel temere missa, cadere sine noxa non poterant.", "st": "31.15"}, {"sp": "N", "t": "Animadversum est a nostris eisdem telis barbaros uti, quibus appetebantur. Ideoque mandatum est, ut nervis ferrum lignumque conectentibus, ante iactum incisis, emitterentur arcu sagittae, quae volitantes vires integras reservabant. Infixae vero corporibus, nihil vigoris perdebant, aut certe (si cecidissent in vanum), ilico frangebantur.", "st": "31.15"}, {"sp": "N", "t": "Dedit autem rebus ita flagrantibus grave momentum casus admodum inopinus. Scorpio genus tormenti, quem onagrum sermo vulgaris appellat, e regione contra hostium aciem densam locatus, lapidem contorsit ingentem, qui licet humo frustra illisus est, visus tamen ita eos metu exanimavit, ut stupore spectaculi novi, cedentes e medio, abire temptarent.", "st": "31.15"}, {"sp": "N", "t": "Sed bucinis optimatum monitu occinentibus, instauratum est proelium, et pari modo res Romana superior stetit, nullo ferme alio telo, vel funditoris amento, in cassum excusso. Agmina enim praeeuntium ductorum, quos rapiendi Valentis malis lucrationibus quaesita cupiditas incendebat, secuti ceteri prae se ferebant, aequiperasse discrimina potiorum: namque semineces aliquot, aut magnis obtriti ponderibus, vel confixi iaculis pectora, volvebantur, non nulli scalas vehendo, ascensumque in muros ex latere omni parantes, sub oneribus ipsis obruebantur, contrusis per pronum saxis et columnarum fragmentis et cylindris.", "st": "31.15"}, {"sp": "N", "t": "Nec quemquam furentium cruoris horrenda species ad serum usque diem ab alacritate faciendi fortiter avertebat, hoc incitante, quod etiam defensorum plurimos cadere diversis ictibus videntes eminus laetabantur. Ita sine requie ulla vel modo, pro moenibus et contra moenia ingentibus animis pugnabatur.", "st": "31.15"}, {"sp": "N", "t": "Et quia nullo ordine iam sed per procursus pugnabatur et globos, quod desperationis erat signum extremae, flexo in vesperam die, digressi omnes rediere ad tentoria tristes, inconsideratae dementiae alter alterum arguentes, quod non (ut suaserat antea Fritigernus), obsidionales aerumnas ubique declinarunt.", "st": "31.15"}, {"sp": "N", "t": "Conversi post haec per omne tempus noctis (ut aestivae) non longum, ad vulnerum curas, artesque medendi gentiles, reddita luce in varias consiliorum vias diducebantur, quorsum tenderent ambigentes, multisque dictatis et controversis, occupare statuunt Perinthum, exinde vicinas urbes divitiarum refertas, docentibus omnia perfugis, etiam domorum nedum urbium interna noscentes. Hanc secuti sententiam, quam utilem existimarunt, itineribus lentis, miscentes cuncta populationibus et incendiis, nullo renitente pergebant.", "st": "31.16"}, {"sp": "N", "t": "Obsessi vero apud Hadrianopolim, post eorum abitum tempestivum, cum vacare hoste loca proxima compertae fidei nuntiassent exploratores, egressi media nocte, vitatis aggeribus publicis, per nemorosa et devia, pars Philippopolim, exindeque Serdicam, alia ad Macedoniam, cum intemeratis opibus quas vehebant, omni studio ad properandum excogitato, currebant, velut in regionibus illis repperiendo Valente: quem inter medios certaminum turbines oppetisse, vel certe ad tugurium confugisse, ubi aestimatus est vi periisse flammarum, penitus ignorabant.", "st": "31.16"}, {"sp": "N", "t": "At Gothi Hunis Halanisque permixti, nimium bellicosis et fortibus, rerumque asperarum difficultatibus induratis, quos miris praemiorum illecebris sibi sociarat sollertia Fritigerni, fixis iuxta Perinthum castris, ipsam quidem urbem, cladum memores pristinarum, nec adire nec temptare sunt ausi, agros vero fertiles late distentos et longe, ad extremam vastavere penuriam, cultoribus caesis aut captis.", "st": "31.16"}, {"sp": "N", "t": "Unde Constantinopolim, copiarum cumulis inhiantes amplissimis, formas quadratorum agminum insidiarum metu servantes, ire ocius festinabant, multa in exitium urbis inclitae molituri. Quos inferentes sese immodice, obicesque portarum paene pulsantes, hoc casu caeleste reppulit numen.", "st": "31.16"}, {"sp": "N", "t": "Saracenorum cuneus (super quorum origine moribusque diversis in locis rettulimus plura), ad furta magis expeditionalium rerum, quam ad concursatorias habilis pugnas, recens illuc accersitus, congressurus barbarorum globo repente conspecto, a civitate fidenter erupit, diuque extento certamine pertinaci, aequis partes discessere momentis.", "st": "31.16"}, {"sp": "N", "t": "Sed orientalis turma novo neque ante vise superavit eventu. Ex ea enim crinitus quidam, nudus omnia praeter pubem, subraucum et lugubre strepens, educto pugione, agmini se medio Gothorum inseruit, et interfecti hostis iugulo labra admovit, effusumque cruorem exsuxit. Quo monstroso miraculo barbari territi, postea non ferocientes ex more, cum agendum appeterent aliquid, sed ambiguis gressibus incedebant.", "st": "31.16"}, {"sp": "N", "t": "Processu dein audacia fracta, cum murorum ambitum insularumque spatiis immensis oblongum, et inaccessas pulchritudines urbis, et incolentium plebem considerarent immensam, iuxtaque fretum, quod Pontum disterminat et Aegaeum, disiectis bellorum officinis, quas parabant, post accepta maiora funera quam illata, exinde digressi sunt effusorie per arctoas provincias, quas peragravere licenter ad usque radices Alpium Iuliarum, quas Venetas appellabat antiquitas.", "st": "31.16"}, {"sp": "N", "t": "His diebus efficacia Iulii, magistri militiae trans Taurum, enituit salutaris et velox. Comperta enim fatorum sorte per Thracias, Gothos antea susceptos, dispersosque per varias civitates et castra, datis tectioribus litteris ad eorum rectores, Romanos omnes (quod his temporibus raro contingit), universos tamquam vexillo erecto, uno eodemque die mandavit occidi, exspectatione promissi stipendii securos, ad suburbana productos. Quo consilio prudenti sine strepitu vel mora completo, orientales provinciae discriminibus ereptae sunt magnis.", "st": "31.16"}, {"sp": "N", "t": "Haec ut miles quondam et Graecus, a principatu Caesaris Nervae exorsus, ad usque Valentis interitum, pro virium explicavi mensura: opus veritatem professum numquam (ut arbitror) sciens silentio ausus corrumpere, vel mendacio. Scribant reliqua potiores, aetate et doctrinis florentes. Quos id (si libuerit) aggressuros, procudere linguas ad maiores moneo stilos.", "st": "31.16"}], []);})();
